create temporary table import_summary (wikidata_id text primary key, summary text not null, source text not null);

insert into import_summary (wikidata_id, summary, source) values
  ('Q3324551', 'Mortal Kombat Advance is a 2001 fighting game developed by Virtucraft and published by Midway for the Game Boy Advance. Part of the Mortal Kombat series, it is a handheld version of Ultimate Mortal Kombat 3 (1995), although it was designed with the intention of evoking the best aspects of the first three games in the series and Mortal Kombat Trilogy.

Mortal Kombat Advance allows players to take control of one of multiple playable characters, who fights against a computer-controlled or player-controlled opponent one-on-one. The game allows players to use various combo moves, as well as fatalities at the end of the fight. Due to the Game Boy Advance having fewer buttons than the arcade cabinets the games originally appeared on, the designers had to modify how Mortal Kombat Advance controlled.', 'https://en.wikipedia.org/wiki/Mortal_Kombat_Advance'),
  ('Q3038709', 'Dragon Ball Z: Taiketsu is a fighting game developed by Webfoot Technologies and published by Atari. Based on the Dragon Ball Z anime series, it was released for the Game Boy Advance (GBA) in North America in 2003 and Europe in 2004.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_Taiketsu'),
  ('Q3042524', 'Mega Man Zero 3 is a 2004 hack and slash platform game developed by Inti Creates and published by Capcom for the Game Boy Advance (GBA) handheld game console. It is the third video game in the Mega Man Zero series of Mega Man video games. The European version featured a completely different logo, which was also used on various other Mega Man titles.

The game takes place two months after the events of Mega Man Zero 2 and follows series protagonist Zero as he attempts to stop a new villain, Dr. Weil, from wreaking havoc on Neo Arcadia.

Mega Man Zero 3 received positive reviews from critics, with praise for its combat, level design, and story, although some criticized its similarities to previous titles. In February 2020, the game was released on the PlayStation 4, Xbox One, Nintendo Switch, and PC via Steam as part of the Mega Man Zero/ZX Legacy Collection.', 'https://en.wikipedia.org/wiki/Mega_Man_Zero_3'),
  ('Q3038705', 'Dragon Ball GT: Transformation is a side-scroller beat ''em up video game developed by Webfoot Technologies and published by Atari for the Game Boy Advance in North America. The story takes place during the "Black Star Dragon Balls" and "Baby" story arcs of the Dragon Ball GT anime series.

Transformation was originally announced as the first of two Dragon Ball GT games from the developer with its sequel set to cover the remainder of the anime series and to be released at the end of 2005. The tentatively titled Dragon Ball GT: Transformation 2 was then pushed to January 2006. However, it was quietly cancelled. A bundle pack including the first Transformation and Dragon Ball Z: Buu''s Fury was released in March 2006.', 'https://en.wikipedia.org/wiki/Dragon_Ball_GT:_Transformation'),
  ('Q3038740', 'Dragon Ball Z: The Legacy of Goku II is a 2003 action role-playing video game developed by Webfoot Technologies and published by Atari for the Game Boy Advance. It is based on the anime Dragon Ball Z and is the sequel to The Legacy of Goku, the second of three games in the series. It was released in North America on June 17, 2003, in Europe on August 1, and in Japan on July 23, 2004. It is the only Dragon Ball Z game developed in the United States to be released in the franchise''s country of origin.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_The_Legacy_of_Goku_II'),
  ('Q3038752', 'Dragon Quest Monsters: Caravan Heart is the third game in the Dragon Quest Monsters series, released only in Japan by Enix for the Game Boy Advance. The game was simultaneously announced with Dragon Quest VIII in Famitsu in 2002. Like the other Dragon Quest titles, development of Caravan Heart was led by Yuji Horii.

It is the second Dragon Quest game to be released for the Game Boy Advance (after Torneko no Daibouken 2 Advance). Caravan Heart features the character Prince Kiefer from Dragon Quest VII, as the game acts as a prequel to the PlayStation game. This is also the last game released under the Enix name, since the merger between Square and Enix was finalized a few days later, on April 1, 2003.', 'https://en.wikipedia.org/wiki/Dragon_Quest_Monsters:_Caravan_Heart'),
  ('Q3010914', 'Dragon Ball: Advanced Adventure is a 2004 video game developed by Dimps and published by Atari for the Game Boy Advance. It is based on the Dragon Ball franchise.', 'https://en.wikipedia.org/wiki/Dragon_Ball:_Advanced_Adventure'),
  ('Q3030331', 'Disney''s Party is a party video game, developed by Neverland for the GameCube and by Jupiter Corporation for the Game Boy Advance. The games are much like the games of the Hudson Soft-produced Mario Party series, in which the player competes in mini-games to win the game.', 'https://en.wikipedia.org/wiki/Disney%27s_Party'),
  ('Q2748684', 'Sonic Advance 2 is a 2002 platform game developed by Dimps and published by Sega for the Game Boy Advance. It is an installment in the Sonic the Hedgehog series and the sequel to 2001''s Sonic Advance. The story follows Sonic as he sets out to save his friends and retrieve the seven magical Chaos Emeralds from Dr. Eggman. Gameplay consists of the player completing various levels as one of five characters, each with their own unique attributes. After each zone is completed, the player faces Dr. Eggman in a boss battle.

Development began in February 2002 and lasted eight months. Sonic Advance 2 was programmed using an updated version of the original''s game engine and the team aimed to make the game larger and faster-paced than the original. Sonic Advance 2 was released to positive reviews; critics praised the updates made over the original Advance and its improved replay value in comparison to past games. Some journalists, however, disliked its high difficulty level. A sequel, Sonic Advance 3, was released in 2004. Sonic Advance 2 was re-released for the Wii U''s Virtual Console in February 2016 in Japan.', 'https://en.wikipedia.org/wiki/Sonic_Advance_2'),
  ('Q1000547', 'Yggdra Union: We''ll Never Fight Alone is a tactical role-playing game for the Game Boy Advance and PlayStation Portable, developed by Sting Entertainment as the second episode of the Dept. Heaven saga of games. Atlus USA localized and published both versions of the game in North America. 505 Games published the Game Boy Advance version in a limited number of European countries, such as Italy and France. An updated version with bonus features was released in Japan for mobile platforms and Nintendo Switch in April 2019 and March 2020, respectively. A Windows version was released in early access on February 6, 2023, with a full release following on July 27, 2023, alongside a western release for Nintendo Switch.', 'https://en.wikipedia.org/wiki/Yggdra_Union'),
  ('Q974537', 'Winx Club is an animated series produced by Rainbow, with later seasons co-produced by Nickelodeon. It was created and directed by Italian animator Iginio Straffi. It premiered on 28 January 2004, becoming a ratings success in Italy and on Nickelodeon networks internationally. The series is set in a magical universe inhabited by fairies, witches, and other mythical creatures, and tells the story of Bloom, a teenage girl from planet Earth who discovers she is a fairy. Enrolling at Alfea College, she befriends four other fairies and forms a group called the Winx Club, fighting a long series of enemies threatening the Magic Dimension, and in the process, discovering her true origins and the fate of her biological family.', 'https://en.wikipedia.org/wiki/Winx_Club'),
  ('Q3023252', 'Densetsu no Starfy is a 2002 platform video game developed by Tose and published by Nintendo for the Game Boy Advance. It was released in Japan on September 6, 2002. It is the first game in The Legendary Starfy series. It received its re-release on the Nintendo Classics service on July 12, 2024, in all regions for the first time along with its sequels. It was followed by Densetsu no Starfy 2 in 2003.', 'https://en.wikipedia.org/wiki/Densetsu_no_Starfy_(video_game)'),
  ('Q1056097', 'This list provides an index of video game titles in Banpresto''s Super Robot Wars franchise, known as Super Robot Taisen in Japan. Most of the games in the series are tactical role-playing games, but several games representing other genres were also released. List is divided by video game genre and ordered by initial release date. Only the original games, Neo Super Robot Wars and Super Robot Wars Compact, had final bosses that were not directly created by Banpresto.', 'https://en.wikipedia.org/wiki/List_of_Super_Robot_Wars_video_games'),
  ('Q3057552', 'Kirby''s Adventure is a 1993 platform game developed by HAL Laboratory and published by Nintendo for the Nintendo Entertainment System (NES). It is the second game in the Kirby series after Kirby''s Dream Land (1992) on the Game Boy and the first to include the Copy Ability, which allows the main character Kirby to gain new powers by eating certain enemies. The game centers around Kirby traveling across Dream Land to repair the Star Rod after King Dedede breaks it apart and gives the pieces to his minions.

Masahiro Sakurai returned as director after serving the same role for Kirby''s Dream Land. He conceived the copy ability to add more challenge and replay value after the last game received criticism for its simplicity. Because the NES hardware had greater graphical power than the Game Boy and programmers were skilled with the now antiquated hardware, HAL Laboratory was able to create impressive visuals. Kirby''s Adventure is the first game to depict Kirby in color. Sakurai had always planned him to be pink, much to the surprise of other staff.', 'https://en.wikipedia.org/wiki/Kirby%27s_Adventure'),
  ('Q1005552', 'Riviera: The Promised Land is a 2002 role-playing video game developed by Sting Entertainment. It was originally released for WonderSwan Color as the first episode of the Dept. Heaven series of games. It was later ported to Nintendo''s Game Boy Advance in 2004, which Atlus USA released in North America in 2005. An enhanced remake was released for the PlayStation Portable in November 2006, and was released in July 2007 in North America by Atlus USA. In July 2023, an HD remaster was announced for Microsoft Windows, Nintendo Switch, iOS and Android. The HD remaster released for Windows in July 2024.', 'https://en.wikipedia.org/wiki/Riviera:_The_Promised_Land'),
  ('Q3027775', 'Digimon Battle Spirit is a fighting video game originally published by Bandai and developed by Dimps for the Japanese-only WonderSwan Color handheld system under the name Digimon Tamers: Battle Spirit. It was later ported to Nintendo''s Game Boy Advance for international releases in North America and Europe two years later.

The game features characters and Digimon that were included in the first three seasons of the animated series of the same name in a somewhat simplistic fighting scenario, and also has slightly arranged samples of the show''s soundtrack.', 'https://en.wikipedia.org/wiki/Digimon_Battle_Spirit'),
  ('Q3024823', 'Dragon Ball Z: Buu''s Fury is a 2004 action role-playing video game based on the anime Dragon Ball Z, developed by Webfoot Technologies and published by Atari. It is the sequel to Dragon Ball Z: The Legacy of Goku II, and the third game in the Dragon Ball Z: The Legacy of Goku series. It was released on September 14, 2004 in North America.

Buu''s Fury was re-released in 2006 as part of a Game Boy Advance two-pack, which includes Dragon Ball GT: Transformation on the same cartridge.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_Buu%27s_Fury'),
  ('Q1002768', 'Super Robot Wars J is a tactical role-playing video game released for the Game Boy Advance developed by A.I and published by Banpresto.', 'https://en.wikipedia.org/wiki/Super_Robot_Wars_J'),
  ('Q3482216', 'Shining Force: The Legacy of Great Intention, commonly referred to as Shining Force, is a 1992 turn-based tactical role-playing game developed by Climax Entertainment and Sonic! Software Planning and published by Sega for the Sega Genesis. It is the second entry of the Shining series, following 1991''s Shining in the Darkness. While primarily a traditional fantasy-themed game, it contains some science fiction elements.

The game has been re-released for various platforms: in Sega Smash Pack Volume 1 for the Dreamcast and Sega Smash Pack 2 for Microsoft Windows, in Sonic''s Ultimate Genesis Collection for Xbox 360 and PlayStation 3, and as a standalone game for the Wii Virtual Console and Windows via Steam. Additionally, a remake was released for the Game Boy Advance in 2004 under the title Shining Force: Resurrection of the Dark Dragon. In 2010, the game was released for iOS but was discontinued in 2015. It was re-released again on the Nintendo Classics service in 2021.', 'https://en.wikipedia.org/wiki/Shining_Force'),
  ('Q150180', 'Fire Emblem: The Blazing Blade, also known simply as Fire Emblem, is a 2003 tactical role-playing game developed by Intelligent Systems and published by Nintendo for the Game Boy Advance. It is the seventh installment in the Fire Emblem series, the second to be released for the platform after Fire Emblem: The Binding Blade, and the first to be localized for international audiences. It was released in Japan and North America in 2003, and in Europe and Australia in 2004.

The game is a prequel to The Binding Blade, set on the fictional continent of Elibe. It tells the story of Lyn, Eliwood, and Hector, three young lords who band together on a journey to find Eliwood''s missing father, Elbert, while thwarting a larger conspiracy threatening the stability of Elibe. The gameplay, which draws from earlier Fire Emblem entries, features tactical combat between armies on a grid-based map. Characters are assigned different character classes that affect abilities and are subjected to permanent death if defeated in battle.', 'https://en.wikipedia.org/wiki/Fire_Emblem:_The_Blazing_Blade'),
  ('Q2878408', 'Back to Stone is an action role-playing game using an isometric 3D perspective developed by French studio Hidden Floor. It was published by Neko Entertainment / Big Ben Interactive in Europe and by Graffiti Entertainment / O~3 Entertainment in North America. It was released for the Game Boy Advance in 2006.', 'https://en.wikipedia.org/wiki/Back_to_Stone'),
  ('Q3201635', 'NapoleonFRA is a real-time strategy video game developed by Genki and published by Nintendo for the Game Boy Advance. The game was a launch title for the handheld system in Japan. The game was also published in France under the title L''Aigle de Guerre (lit. "The Eagle of War"). The Japanese version of the game was compatible with the Mobile Adapter GB until December 14, 2002. An unofficial fan English translation patch for the game was released on December 31, 2018.

In the game''s Story Mode, players play Napoleon Bonaparte who leads the revolutionary army into battle against the British. Set in the late 18th century, Napoleon''s story is told in Fire Emblem fashion via strategic maps and character dialogue. However, the game takes many liberties with historical accuracy, such as Napoleon fighting man-eating ogres and abominable snowmen. The objectives for the missions vary slightly, but the basic idea is to send out units, defeat the enemy and take over the opponent''s stronghold.', 'https://en.wikipedia.org/wiki/Napoleon_(video_game)'),
  ('Q3091529', 'Mega Man Battle Network 2 is a 2001 tactical role-playing game developed by Capcom for the Game Boy Advance (GBA) handheld game console. It is the second game in the Mega Man Battle Network series, and a sequel to the first game; it follows Lan Hikari and his NetNavi, MegaMan.EXE, as they attempt to take down the new NetCrime syndicate Gospel.

Mega Man Battle Network 2 received generally positive reviews, with many praising it for improving upon the gameplay of the first entry; it has been re-released multiple times, including via the Wii U Virtual Console in 2014, and as part of the Mega Man Battle Network Legacy Collection compilation in 2023. It was followed up by Mega Man Battle Network 3 in 2002.', 'https://en.wikipedia.org/wiki/Mega_Man_Battle_Network_2'),
  ('Q2081510', 'Sonic Advance is a 2001 platform game developed by Sonic Team and Dimps and published by Sega for the Game Boy Advance. It was one of the first Sonic the Hedgehog games to be released on a Nintendo console along with Sonic Adventure 2: Battle on the GameCube, and was produced in commemoration of the series'' tenth anniversary. The story follows Sonic, Tails, Knuckles, and Amy as they journey to stop Doctor Eggman from taking over the world. Controlling a character, players are tasked with completing each level, defeating Eggman and his robot army, and collecting the seven Chaos Emeralds.

Development began after Sega shifted its focus to third-party software development, due to the poor performance of the Dreamcast console. Sega recruited Dimps to lead development, making the game the first in the franchise developed by the studio. While Sonic Advance follows a similar style of gameplay to the Sega Genesis Sonic games, certain concepts and designs were reused from newer games such as Sonic Adventure (1998). The game was ported to Nokia''s N-Gage in 2003 as SonicN, with ports to J2ME devices by Gameloft and Android by Sega releasing in 2011. The GBA version was re-released on the Wii U''s Virtual Console in Japan.', 'https://en.wikipedia.org/wiki/Sonic_Advance'),
  ('Q1091127', 'Oddworld: Munch''s Oddysee is a 2001 platform video game developed by Oddworld Inhabitants and originally published by Microsoft Game Studios for the Xbox where it was released as a launch title. It is the third installment in the Oddworld series and the first to not be released initially on a PlayStation console.

Originally announced as a title in development for PlayStation 2, it was instead released exclusively as one of the launch titles for Xbox. While an "Oddboxx" containing the first four Oddworld games was originally intended for a holiday season 2009 release on Steam, the fourth game in the series was not released until December 20, 2010, on Steam, over two years after the first three.', 'https://en.wikipedia.org/wiki/Oddworld:_Munch%27s_Oddysee'),
  ('Q3327153', 'Mr. Driller 2 is a 2000 puzzle video game developed and published by Namco for arcades. It is the second game in the Mr. Driller series, and was later ported to the Game Boy Advance and Windows in 2001 and 2002. The game introduces two new characters to the series, Puchi (Susumu''s dog), and Anna (Susumu''s rival).

The Game Boy Advance version of Mr. Driller 2 was digitally re-released via the Wii U Virtual Console in 2014, and via the Nintendo Classics service in 2025.', 'https://en.wikipedia.org/wiki/Mr._Driller_2'),
  ('Q150169', 'Fire Emblem: The Sacred Stones is a tactical role-playing game developed by Intelligent Systems, and published by Nintendo for the Game Boy Advance handheld video game console in 2004 for Japan and 2005 in the West. It is the eighth entry in the Fire Emblem series, the second to be released outside Japan, and the third and final title to be developed for the Game Boy Advance after The Binding Blade and its prequel The Blazing Blade.

Set in a separate continuity to earlier Fire Emblem titles, The Sacred Stones takes place on the fictional continent of Magvel, which is divided into six nations, built around five magical stones said to be linked to the imprisonment of an ancient demon. When one of the six nations, the Grado Empire, invades its neighbors and begins destroying the stones, protagonists Eirika and Ephraim of the royal family of Renais set out to gather allies and halt Grado''s conquest, while also trying to uncover the reasons for the war. The gameplay is similar to previous Fire Emblem games, focusing on turn-based, tactical movement of units across a grid-based battlefield. Core features of the game include permanent death for characters defeated in battle and support conversations that grant advantages to certain units in battle.', 'https://en.wikipedia.org/wiki/Fire_Emblem:_The_Sacred_Stones'),
  ('Q1091226', 'Mario Pinball Land, known in Europe and Japan as Super Mario Ball, is a 2004 pinball video game developed by Fuse Games and published by Nintendo for the Game Boy Advance. It is a spin-off of the Super Mario series. The game was later re-released for the Wii U Virtual Console.

The game received mixed reviews from critics, who praised the game''s presentation, especially its excellent graphics, and its premise of blending Mario with pinball, but criticized its high difficulty level alongside the playfield reset mechanic of its tables, with some also faulting its overall short length.', 'https://en.wikipedia.org/wiki/Mario_Pinball_Land'),
  ('Q3154355', 'Iridion 3D is a rail shooter video game developed by Shin''en Multimedia. A launch title for the Game Boy Advance portable game console, it was released in North America on June 11, 2001 and in Europe on September 21. The player controls a single starship defending Earth from the alien Iridion. The quasi-3D game spans seven levels from Earth to the aliens'' home planet, each following a linear path that culminate with a boss.

Iridion began development as a shooter for the Game Boy Color; when Shin''en decided to drop development and shift their focus to the Game Boy Advance, Iridion was the first game by the developer to appear on the system. Though billed as a 3D game, Shin''en used realtime encoding and resizing to manipulate the size of 2D sprites instead of creating a true 3D environment. More room on the game cartridge was available for graphics due to the game''s use of the GAX Sound Engine, which allowed real-time decoding of song data in a small file size.', 'https://en.wikipedia.org/wiki/Iridion_3D'),
  ('Q3336144', 'Naruto: Ninja Council 2 (known as Naruto: Saikyō Ninja Daikesshu 2 in Japan) is an action video game, released for Game Boy Advance and is the second installment in the Ninja Council series. It is based on the popular manga and anime series Naruto by Masashi Kishimoto and is developed by Aspect and Tomy and published by D3 Publisher and Tomy.', 'https://en.wikipedia.org/wiki/Naruto_Ninja_Council_2'),
  ('Q1072868', 'Final Fantasy Tactics Advance is a 2003 tactical role-playing game developed by Square for the Game Boy Advance, and published by Square in Japan and Nintendo internationally. A successor to Final Fantasy Tactics (1997), the story follows the trials of some children from the town of St. Ivalice after a magical book transforms their home into a fantasy realm of the same name. Gameplay has player teams fighting in turn-based combat on a grid, with units using a themed Job system. A new feature is a "Law" system, which places random limitations on player action during battles.

Yasumi Matsuno, creator of the original Tactics, had wanted to make a follow-up game but was unable to due to other projects. Production began on Tactics Advance in March 2002, and was handled by former Quest Corporation staff who worked on Tactics Ogre: The Knight of Lodis (2001). Several staff returned from Tactics including Matsuno as producer, Hideo Minaba as art director, and Hitoshi Sakimoto as lead composer. The team''s goal was a refinement of the gameplay of Tactics that could be played in short sessions. The story, art design and music were tailored for a younger audience.', 'https://en.wikipedia.org/wiki/Final_Fantasy_Tactics_Advance'),
  ('Q2086466', 'Mario Golf: Advance Tour is a 2004 sports role-playing video game developed by Camelot Software Planning and published by Nintendo for the Game Boy Advance. The game is the sequel to the Game Boy Color version of Mario Golf and the Game Boy Advance counterpart of Mario Golf: Toadstool Tour.

The game received positive reviews from critics, with particular praise towards its RPG elements, story mode, gameplay depth, and presentation, but criticism towards a lack of enough innovation and evolution compared to other Mario Golf titles and its plot''s lack of depth.', 'https://en.wikipedia.org/wiki/Mario_Golf:_Advance_Tour'),
  ('Q2878969', 'Kururin Paradise is a 2002 puzzle video game developed by Eighting and published by Nintendo for the Game Boy Advance. It is the second entry in the Kururin series and the sequel to Kuru Kuru Kururin (2001), and was released exclusively in Japan on December 6, 2002. A North American release of the game was planned and revealed at E3, but later canceled. The player controls Kururin in a constantly spinning helicopter, navigating through mazes to rescue members of his family, who he assumes were kidnapped by a group of traveling magicians. It introduces alternate paths that can be unlocked by finding keys in levels, which unlock additional levels. Additionally, a selection of sixteen minigames can be played in single-player and multiplayer.', 'https://en.wikipedia.org/wiki/Kururin_Paradise'),
  ('Q3108749', 'Mother (known as EarthBound outside Japan) is a video game series that consists of three role-playing video games: Mother (1989), known as EarthBound Beginnings outside Japan, for the Family Computer; Mother 2 (1994), known as EarthBound outside Japan, for the Super Nintendo Entertainment System; and Mother 3 (2006) for the Game Boy Advance.

Written by Shigesato Itoi, published by Nintendo, and featuring game mechanics modeled on the Dragon Quest series, Mother is known for its sense of humor, originality, and parody. The player uses weapons and psychic powers to fight hostile enemies, which include animated everyday objects, aliens and brainwashed people. Signature elements of the series include a lighthearted approach to the plot, battle sequences with psychedelic backgrounds, and the "rolling HP meter": player health ticks down like an odometer rather than instantly being subtracted, allowing the player to take preventative action, such as healing or finishing the battle, before the damage is fully dealt. While the franchise is popular in Japan, in the Anglosphere it is best associated with the cult following behind EarthBound.', 'https://en.wikipedia.org/wiki/Mother_(video_game_series)'),
  ('Q1153949', 'Tomb Raider: The Prophecy is a 2002 action-adventure video game developed by Ubi Soft Milan and published by Ubi Soft for the Game Boy Advance. Part of the Tomb Raider series, it follows protagonist Lara Croft as she explores multiple temples in search of keys to a world-destroying power. Gameplay features exploration, combat and platforming displayed from a top-down isometric perspective.', 'https://en.wikipedia.org/wiki/Tomb_Raider:_The_Prophecy'),
  ('Q1313985', 'Harvest Moon: Friends of Mineral Town is a video game for the Game Boy Advance, developed and published by Marvelous Interactive. It is the first Game Boy Advance game of the Story of Seasons series, and is a remake of Harvest Moon: Back to Nature. It was first released in Japan in April 2003, in North America in November 2003, and in Europe in March 2004. Many critics praised it as the best entry of the series, combining elements from the best-selling console entries and introducing many notable series staples. It was later released on the Virtual Console for the Wii U in June 2015.

The player is a farmer whose goal is to make a profit from the farm he runs by producing crops and raising livestock.', 'https://en.wikipedia.org/wiki/Harvest_Moon:_Friends_of_Mineral_Town'),
  ('Q2819910', 'A Sound of Thunder is a 2004 video game developed by Möbius Entertainment and published by BAM! Entertainment for the Game Boy Advance. It was released in Europe on February 28, 2004, before arriving in North America on February 1, 2005. The story is loosely based on Ray Bradbury''s 1952 short story of the same name, but follows more closely the plot of the 2005 film adaptation.

Versions for the Microsoft Xbox, GameCube and PlayStation 2, were cancelled as of December 2006. Gameplay of the console game was shown in the TV show CSI.', 'https://en.wikipedia.org/wiki/A_Sound_of_Thunder_(video_game)'),
  ('Q3093444', 'GT Advance Championship Racing is a racing game developed by MTO and published by THQ. It was a launch title for the Game Boy Advance. The game''s sequel, GT Advance 2: Rally Racing, was released on June 30, 2002, in North America.

GT Advance features forty-five licensed Japanese cars and places the player in races on thirty-two tracks. Due to positive reaction to the game in Japan, THQ purchased publishing rights for the North American and European releases to the game after a reported bidding war, and added in a controversial password save system into the game to cut costs.

The game was received with mostly positive reviews from critics that praised the game for its fun gameplay, but THQ was criticized by most reviewers for adding passwords to the game when the Japanese version had battery-backed saves.', 'https://en.wikipedia.org/wiki/GT_Advance_Championship_Racing'),
  ('Q1091004', 'Super Robot Wars A is a video game for the Nintendo Game Boy Advance, part of Banpresto''s Super Robot Wars franchise and the first to appear on the Game Boy Advance handheld; the letter "A" in the title stands for "Advance". It was ported onto mobile phones as part of the Super Robot Wars i collection in 2006. An enhanced remake of Super Robot Wars A was released for the PlayStation Portable on June 19, 2008, as Super Robot Wars A Portable.', 'https://en.wikipedia.org/wiki/Super_Robot_Wars_A'),
  ('Q3197899', 'Klonoa 2: Dream Champ Tournament is a video game published by Namco and released on the Game Boy Advance in Japan in 2002 and North America in early 2005. As the third game in the Klonoa handheld series, the game retains many of the gameplay elements of the previous titles, while adding in a few of its own.', 'https://en.wikipedia.org/wiki/Klonoa_2:_Dream_Champ_Tournament'),
  ('Q3197902', 'Klonoa Heroes: Densetsu no Star Medal is a 2002 action role-playing game developed and published by Namco for the Game Boy Advance exclusively in Japan. It is the first game in the Klonoa series to combine both standard action-gaming elements with role-playing features.', 'https://en.wikipedia.org/wiki/Klonoa_Heroes:_Densetsu_no_Star_Medal'),
  ('Q4728774', 'All Grown Up! is an American animated television series developed by Kate Boutilier, Eryk Casemiro, and Monica Piper and produced by Klasky Csupo for Nickelodeon. It serves as a sequel to Rugrats, and explores the daily lives of protagonist Tommy Pickles, his little brother Dil, and his childhood friends, now tweens/adolescents. The concept for the series was based on the Rugrats episode "All Growed Up", which served as the original series'' 10th anniversary special and proved successful with audiences.

The series ran from April 12, 2003 to August 17, 2008, for a total of five seasons and 55 episodes, and featured much of the surviving cast from the original series reprising their roles. Several episodes also feature flashbacks of the kids as toddlers.', 'https://en.wikipedia.org/wiki/All_Grown_Up!'),
  ('Q3282480', 'Summon Night: Swordcraft Story is a 2003 action role-playing game developed by Flight-Plan for the Game Boy Advance. It is a spinoff of the Summon Night series of games. It was first released in Japan in April 2003, published by Banpresto. An English localized version was released in North America by Atlus in July 2006. A sequel, Summon Night: Swordcraft Story 2, was released in Japan in August 2004, and North America in October 2006.', 'https://en.wikipedia.org/wiki/Summon_Night:_Swordcraft_Story'),
  ('Q4672963', 'Ace Combat Advance is a 2005 combat flight simulation video game in the Ace Combat series. Developed by Hungarian studio Human Soft, it is the first entry in the series released on a handheld game console and the first 2D entry in the series. Unlike other Ace Combat games, Advance was not released in Japan. It received mixed reviews from critics.', 'https://en.wikipedia.org/wiki/Ace_Combat_Advance'),
  ('Q2256904', 'Dinotopia: The Timestone Pirates is a platform based video game for Nintendo Game Boy Advance, developed by RFX Interactive and published by TDK Mediactive. It is set in James Gurney''s Dinotopia.', 'https://en.wikipedia.org/wiki/Dinotopia:_The_Timestone_Pirates'),
  ('Q5037208', 'Car Battler Joe is a 2001 vehicular combat game developed by Ancient and published by Natsume Inc. for the Game Boy Advance. The game involves using cars to fight opponents in action-styled battles, with role-playing video game game mechanics. It combined vehicular combat game with action role-playing elements in a similar manner to Autoduel from 1985.', 'https://en.wikipedia.org/wiki/Car_Battler_Joe'),
  ('Q3312351', 'Super Mario Advance is a 2001 platform game developed and published by Nintendo as a launch title for the Game Boy Advance (GBA). It is an enhanced remake of the NES video game Super Mario Bros. 2 (1988), using the graphical style of Super Mario All-Stars (1993). Players control Mario, Luigi, Peach, or Toad as they travel through the seven worlds of Subcon to save the kingdom from the evil toad Wart. It contains several additions, including voice clips for all playable characters, giant renditions of objects, and a multiplayer mode based on the original Mario Bros. arcade game.

Super Mario Advance began development in response to the success of Super Mario Bros. Deluxe (1999), a port of Super Mario Bros. released for the Game Boy Color. It was first revealed at a Japanese retail conference in January 2001, then released worldwide throughout the year; it was also released in China in June 2004. Super Mario Advance was well-received by critics upon release for its presentation and gameplay enhancements, though some felt it offered less than Deluxe. It was also a major commercial success, selling 5.5 million copies worldwide, making it one of the best-selling Game Boy Advance games. Nintendo would develop three more games with the Super Mario Advance moniker, being ports of Super Mario World, Yoshi''s Island, and Super Mario Bros. 3, which themselves released to similar critical and commercial success and would lead to the development of New Super Mario Bros. (2006).', 'https://en.wikipedia.org/wiki/Super_Mario_Advance'),
  ('Q2564704', 'Kuru Kuru Kururin is a puzzle video game developed by Eighting and published by Nintendo for the Game Boy Advance. It was released in Japan on March 21, 2001, and in Europe and Australia on June 22 as a launch title for the system. Kuru Kuru Kururin is the first title in the Kururin series and was followed by two Japan-only sequels, Kururin Paradise (2002) and Kururin Squash! (2004). The story follows Kururin, a bird who attempts to rescue his siblings after his mother lost them.

The gameplay revolves around a constantly spinning helicopter the player must navigate through mazes to reach a goal at the end of each level. If the player hits walls or other obstacles, it damages the vehicle, but if the player passes through checkpoints, their health will be restored. The idea came from director Masato Toyoshima, who recalled a memory of maneuvering furniture when moving between apartments, and pitched his idea to Nintendo. It was initially conceptualized as a game for the Game Boy Color and Nintendo 64 before the reveal of the Game Boy Advance, remaining in the drafts for two years prior. Yasunari Watanabe served as the sole programmer, and character designs were created by Yōichi Kotabe.', 'https://en.wikipedia.org/wiki/Kuru_Kuru_Kururin'),
  ('Q3281078', 'Meet the Robinsons is a 2007 action-adventure game developed by Avalanche Software and published by Buena Vista Games under the Disney banner. It is based on the 2007 film of the same name.', 'https://en.wikipedia.org/wiki/Meet_the_Robinsons_(video_game)'),
  ('Q4977851', 'Bruce Lee: Return of the Legend is a 2003 action beat ''em up developed by Vicarious Visions for the Game Boy Advance. It was first published and released in Europe by Vivendi Universal Games on March 21, 2003, and was later published and released in North America on May 15, 2003.', 'https://en.wikipedia.org/wiki/Bruce_Lee:_Return_of_the_Legend'),
  ('Q4717686', 'Alex Rider: Stormbreaker is the name of two video games based on the 2006 film Stormbreaker, which in turn was an adaptation of the original 2000 novel. They were released in 2006, on 7 July in UK, and 25 September in the U.S. for Nintendo DS and Game Boy Advance, with the former platform itself prominently appearing in the film as part of a marketing deal with Nintendo.', 'https://en.wikipedia.org/wiki/Alex_Rider:_Stormbreaker'),
  ('Q4839183', 'Back Track is a first-person shooter that was released for Windows in 2003 or 2002 and for Game Boy Advance in 2001. It is notable for being the first 3D shooter to be released on the Game Boy Advance (along with Doom).', 'https://en.wikipedia.org/wiki/Back_Track'),
  ('Q4743149', 'American Bass Challenge, known in Japan and Europe as Super Black Bass Advance, is a fishing video game developed by Starfish for the Game Boy Advance. It was published in Japan by Starfish in August 2001, and in North America and Europe by Ubi Soft in December 2001 and February 2002, respectively. It is the eleventh game in the Black Bass series, though the Black Bass name was not used for the North American release.', 'https://en.wikipedia.org/wiki/American_Bass_Challenge'),
  ('Q2150454', 'Mario Tennis: Power Tour, known as Mario Power Tennis in Europe, is a 2005 role-playing sports game developed by Camelot Software Planning and published by Nintendo for the Game Boy Advance. It is the sequel to the Game Boy Color version of Mario Tennis. While it is the handheld companion to Mario Power Tennis, released on GameCube, with the European release sharing its title, Power Tour lacks connectivity with Power Tennis, unlike how its predecessor features connectivity with its console counterpart on Nintendo 64. Power Tour was re-released on the Wii U''s Virtual Console in 2014.

The game received positive reviews from critics, with praise towards its gameplay, presentation, amount of content, RPG elements, and story mode. Several critics lauded the game as one of the best Game Boy Advance sports games.', 'https://en.wikipedia.org/wiki/Mario_Tennis:_Power_Tour'),
  ('Q4686065', 'Advance Guardian Heroes is a beat ''em up video game developed and published by Treasure for the Game Boy Advance. The game was released on September 22, 2004, in Japan, September 14 in North America and February 18, 2005, in Europe. It was released outside Japan by Ubisoft. It is a sequel to Guardian Heroes on the Sega Saturn and developed under license from Sega.', 'https://en.wikipedia.org/wiki/Advance_Guardian_Heroes'),
  ('Q2274675', 'Kōchū Ōja Mushiking, known outside Japan as Mushiking: The King of Beetles or Mushiking: Battle of the Beetles, is a 2003 collectible card video game developed and published by Sega for arcades. The game involves battles between cards describing various species of beetles. The cards can be scanned in by a Mushiking arcade machine, which will both carry out battles and dispense new cards. It is the second trading card arcade by Sega following World Club Champion Football.

As of 2008, more than 100,000 tournaments have been held, and 20 million cards have shipped. The game has made it into the Guinness World Records with the highest numbers of tournaments held for an arcade game.', 'https://en.wikipedia.org/wiki/Mushiking:_The_King_of_Beetles'),
  ('Q4958194', 'Bratz is an American fashion doll and media franchise created by former Mattel employee Carter Bryant for MGA Entertainment, which first introduced in Spring 2001. Bratz dolls were popular during the early 2000s.

The four original 10-inch (25 cm) dolls were released on May 21, 2001 — Yasmin (Latina), Cloe (English blond/white), Jade (East Asian), and Sasha (Black) — with Meygan (Scottish Redhead) being added to the group in 2002 as a fifth member. They featured almond-shaped eyes adorned with eyeshadow adding lush and big glossy lips. Bratz reached great success with the expansion to spin-offs, including Bratz Kidz, Bratz Boyz, Bratz Babyz, Bratzillaz, and a media franchise consisting of discography and adaptations into a TV series, a web series, a live-action film and video games. Global sales of the entire franchise grossed $2 billion in 2005 and by the following year, the brand had about 40 percent of the fashion-doll market.', 'https://en.wikipedia.org/wiki/Bratz'),
  ('Q4851779', 'Ballistic: Ecks vs. Sever (known as Ecks vs. Sever II: Ballistic in Europe) is a first-person shooter video game for the Game Boy Advance handheld game console, developed by Crawfish Interactive and published by BAM! Entertainment in September 2002. It is the second video game based on the 2002 film Ballistic: Ecks vs. Sever, the first being Ecks vs. Sever. While that game was based on an early draft of Ecks vs. Sever''s script, Ballistic, bearing its ultimate title, is based on its final, theatrical cut.', 'https://en.wikipedia.org/wiki/Ballistic:_Ecks_vs._Sever_(video_game)'),
  ('Q4765050', 'Animaniacs: Lights, Camera, Action! is an action game for the Nintendo DS and Game Boy Advance. It was developed by Warthog Games and published by Ignition Entertainment. The game is based on the cartoon series Animaniacs. Since the TV series had ended seven years earlier, and Wakko''s Wish being the series finale, this game was the last official appearance of the characters until the 2020 revival. It was also the last game to be developed by Warthog before its discontinuation in 2006. According to Nintendo''s database, a NTSC port was scheduled for release on November 14, 2005. It appears on some listings, but no copy or image of it is known to exist, so it was most likely cancelled.', 'https://en.wikipedia.org/wiki/Animaniacs:_Lights,_Camera,_Action!'),
  ('Q4386839', 'Dokapon: Monster Hunter, known in Japan as Dokapon-Q: Monster Hunter! and known in Europe as Dokapon: Monster Hunter!, is a 2001 role-playing video game video game developed and published by Asmik Ace Entertainment for the Game Boy Advance in Japan on August 3, 2001. It was later published in North America by AIA on October 30, 2001, and in Europe by Ubi Soft on June 21, 2002.', 'https://en.wikipedia.org/wiki/Dokapon:_Monster_Hunter'),
  ('Q5011737', 'CIMA: The Enemy, known in Japan as Frontier Stories, is a role-playing video game developed by Neverland for the Game Boy Advance. It was published in Japan by Marvelous Entertainment and in North America by Natsume Inc. It follows the story of Ark and Ivy, two aspiring Gate Guardians. It is their duty to protect the innocent from being captured by the CIMA, an alien race that feeds on human hope.', 'https://en.wikipedia.org/wiki/CIMA:_The_Enemy'),
  ('Q2471393', 'Crash Bandicoot 2: N-Tranced is a 2003 platform game developed by Vicarious Visions and published by Universal Interactive for the Game Boy Advance. It is the sequel to Crash Bandicoot: The Huge Adventure and the eighth installment in the Crash Bandicoot video game series. The game''s plot follows Crash Bandicoot as he sets out to foil the universe-conquering plans of Doctor Nefarious Tropy and free his brainwashed friends from the clutches of the evil N. Trance.

Crash Bandicoot 2: N-Tranced features side-scrolling levels and quasi-3D chase sequences as well as isometric stages in which the player must navigate by rolling a metallic sphere. Multiplayer modes are also available via the Game Link Cable. The game was received positively by critics, who praised the level variety and presentation, but criticized the gameplay for being largely identical to The Huge Adventure.', 'https://en.wikipedia.org/wiki/Crash_Bandicoot_2:_N-Tranced'),
  ('Q167359', 'Pirates of the Caribbean: Dead Man''s Chest is a 2006 action-adventure game based on the film of the same name developed by Griptonite Games and Amaze Entertainment for the Game Boy Advance, Nintendo DS, PlayStation Portable, and mobile phones.', 'https://en.wikipedia.org/wiki/Pirates_of_the_Caribbean:_Dead_Man%27s_Chest_(video_game)'),
  ('Q3276921', 'Magical Vacation is a 2001 role-playing video game developed by Brownie Brown and published by Nintendo for the Game Boy Advance only in Japan on December 7, 2001, and was later re-released in the same region in 2006. Japanese singer, model, and actress Mika Nakashima was featured in the television commercials for Magical Vacation.

A sequel was produced for the Nintendo DS in 2006, titled Magical Vacation: Itsutsu no Hoshi ga Narabu Toki. It was released in North America and Europe as Magical Starsign. Magical Vacation was later re-released for the Nintendo Classics service in 2025.', 'https://en.wikipedia.org/wiki/Magical_Vacation'),
  ('Q2547348', 'Medal of Honor: Infiltrator is a top-down third-person shooter game and the sixth installment in the Medal of Honor video game series, and the second game for the Game Boy Advance. The game was developed by Netherock Ltd. and published by EA Games in North America in November 2003, and in Europe and Japan in December 2003.', 'https://en.wikipedia.org/wiki/Medal_of_Honor:_Infiltrator'),
  ('Q5150224', 'Columns Crown is a puzzle game developed by WOW Entertainment and published by Sega for the Game Boy Advance. It is part of the Columns series and was released in Europe on December 7, 2001, in Japan on December 13, 2001, and in North America on February 4, 2002. The game was later re-released twice as part of the 2 Games in 1 twin-pack cartridge in Europe, first bundled with Sonic Pinball Party on November 11, 2005 and then with ChuChu Rocket! on November 28, 2008. The latter compilation, aside as being the final one released on the system in Europe, was the final game to be released on the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Columns_Crown'),
  ('Q3284042', 'Ed, Edd n Eddy: Jawbreakers! is a 2D side-scrolling video game developed by Climax Group and published by BAM! Entertainment, with European distribution handled by Acclaim Entertainment. It was released exclusively for the Game Boy Advance on March 25, 2003. Based on Cartoon Network''s animated television series Ed, Edd n Eddy, the game mirrors Ed, Edd, and Eddy''s television quest to make money to buy jawbreakers. Press outlets compared the gameplay to The Lost Vikings.

Jawbreakers! received mostly poor reviews from critics upon its release. Cartoon Network later released two other games based on the animated series: Ed, Edd n Eddy: The Mis-Edventures in 2005 for Game Boy Advance, GameCube, Microsoft Windows, PlayStation 2, and Xbox and Ed, Edd n Eddy: Scam of the Century for Nintendo DS in 2007.', 'https://en.wikipedia.org/wiki/Ed,_Edd_n_Eddy:_Jawbreakers!'),
  ('Q3285493', 'Rebelstar: Tactical Command is a turn-based tactics video game developed by Codo Technologies and published by Namco Hometek for the Game Boy Advance in 2005. It is the fourth game in the Rebelstar series. The game was created by Julian Gollop, who previously designed UFO: Enemy Unknown, Laser Squad and the original Rebelstar games.', 'https://en.wikipedia.org/wiki/Rebelstar:_Tactical_Command'),
  ('Q5189935', 'Cruis''n Velocity is a 2001 racing game developed by Graphic State and published by Midway Games for the Game Boy Advance. It is the fourth installment of Nintendo''s Cruis''n series and the only game in the series not to be preceded by an arcade release and features slightly different gameplay from its predecessors. The game uses the same engine as Dark Arena, a first-person shooter also developed by Graphic State, to achieve a pseudo-3D effect. This approach garnered the game mixed reviews.', 'https://en.wikipedia.org/wiki/Cruis%27n_Velocity'),
  ('Q4787555', 'Arctic Tale is a video game for the Nintendo DS, Game Boy Advance and Wii. The game is about trying to survive as a polar bear (adult or young), a walrus, a killer whale, or an Arctic fox. It is loosely based on the National Geographic documentary about Arctic wildlife also called Arctic Tale.', 'https://en.wikipedia.org/wiki/Arctic_Tale_(video_game)'),
  ('Q3285191', 'Drake & Josh is a video game based on Nickelodeon''s sitcom of the same name, developed by Artificial Mind and Movement and published by THQ for the Game Boy Advance (GBA).', 'https://en.wikipedia.org/wiki/Drake_%26_Josh_(video_game)'),
  ('Q2562228', 'Castlevania: Circle of the Moon, titled Castlevania in PAL regions, is a 2001 action role-playing game developed and published by Konami for the Game Boy Advance handheld game console. The game was developed as a stand-alone title in the Castlevania series and as a launch title for the Game Boy Advance.

The game''s plot follows a vampire hunter named Nathan Graves as he attempts to rescue his mentor from the clutches of Dracula. Following the Metroidvania style of gameplay established by Castlevania: Symphony of the Night, Circle of the Moon expands on the magic attack mechanics of the former with the Dual Set-Up System, which allows for attacks to be mixed and matched by players as they see fit.', 'https://en.wikipedia.org/wiki/Castlevania:_Circle_of_the_Moon'),
  ('Q5047407', 'Cartoon Network Speedway is a kart racing video game released for the Game Boy Advance in 2003. Published by Majesco and developed by DC Studios, the game features characters from Cartoon Network''s original animated television series; Ed, Edd n Eddy, Johnny Bravo, Courage the Cowardly Dog, Cow and Chicken, and Sheep in the Big City.', 'https://en.wikipedia.org/wiki/Cartoon_Network_Speedway'),
  ('Q5047405', 'Cartoon Network: Block Party is a 2004 arcade-style party game released for Game Boy Advance, developed by American studios Monkeystone Games and One Man Band LLC, and published by Majesco. It features characters from Cartoon Network original animated series such as Johnny Bravo, Ed, Edd n Eddy, Courage the Cowardly Dog, and Cow and Chicken. Critical reception was mostly negative.', 'https://en.wikipedia.org/wiki/Cartoon_Network:_Block_Party'),
  ('Q4749776', 'An American Tail: Fievel''s Gold Rush is a platform game that was first released in Europe on March 1, 2002, for the Game Boy Advance, then in North America on May 2, 2003. Based on Universal Studios'' An American Tail animated feature film franchise, the game was developed by Hokus-Pokus and published by Swing! Entertainment in Europe and Conspiracy Entertainment in North America.', 'https://en.wikipedia.org/wiki/An_American_Tail:_Fievel%27s_Gold_Rush'),
  ('Q4795646', 'Around the World in 80 Days is a platform video game developed by Pick Up & Play for Mobile phones, and Published by Saffire & Disney Interactive for Game Boy Advance, It is based on Walt Disney Pictures and Walden Media''s 2004 film of the same name starring Jackie Chan. The game features pre-rendered characters and graphics, and a password feature for returning to specific levels.

Like the film, the game set in the 19th century, and the player assumes the role of Passepartout (portrayed by Jackie Chan), a Chinese valet hired by an eccentric inventor Phileas Fogg (Steve Coogan) in efforts to circumnavigate the world in 80 days.', 'https://en.wikipedia.org/wiki/Around_the_World_in_80_Days_(video_game)'),
  ('Q2450773', 'Top Spin 2 is a 2006 tennis video game developed by Indie Built, MENT, and Aspyr and originally published by 2K and Superscape. It is the sequel to Top Spin and is followed by Top Spin 3.', 'https://en.wikipedia.org/wiki/Top_Spin_2'),
  ('Q3529558', 'Tweety and the Magic Gems, known in Japan as Tweety''s Hearty Party, is a party video game developed by Kotobuki System and published by Kemco in 2001 for Game Boy Advance. The game was a launch title in Japan and Europe.', 'https://en.wikipedia.org/wiki/Tweety_and_the_Magic_Gems'),
  ('Q1206503', 'Mario Party Advance is a 2005 party video game developed by Hudson Soft and published by Nintendo for the Game Boy Advance. It is the first handheld game in the Mario Party series and the seventh entry in the series overall. The game was released in Japan on January 13, 2005, North America on March 28, 2005, Europe on June 10, 2005, and Australia on September 15, 2005. The game was re-released on the Virtual Console for the Wii U in 2014.

Mario Party Advance differs from other titles in the Mario Party series in its focus on one single-player mode rather than several multiplayer modes. However, traditional Mario Party gameplay is present in players choosing a character from the Mario franchise, moving around an interactive game board, and playing a variety of minigames.', 'https://en.wikipedia.org/wiki/Mario_Party_Advance'),
  ('Q3493436', 'Spider-Man: Mysterio''s Menace is a 2001 action video game based on the Marvel Comics character Spider-Man. It was developed by Vicarious Visions and published by Activision for the Game Boy Advance. The game is a standalone sequel to Spider-Man (2000) and Spider-Man 2: Enter: Electro (2001). It was released on September 18, 2001, in North America, and on April 26, 2002, in Japan. The game was later re-released on a Twin Pack cartridge bundled with X2: Wolverine''s Revenge in 2005.', 'https://en.wikipedia.org/wiki/Spider-Man:_Mysterio%27s_Menace'),
  ('Q3493448', 'Spider-Man: Battle for New York is a 2006 action video game developed by Torus Games and published by Activision, and is a prequel to 2005''s Ultimate Spider-Man, itself based on the comic book series of the same name. It was released for the Game Boy Advance and Nintendo DS on November 14, 2006. The game features Spider-Man and the Green Goblin as the main characters and is a re-imagining of their first encounter within the Ultimate universe. Battle for New York features the Green Goblin as a playable character. The cutscenes in the game are drawn by Marvel Comics artist Ron Lim.', 'https://en.wikipedia.org/wiki/Spider-Man:_Battle_for_New_York'),
  ('Q3120896', 'Gunstar Super Heroes, also known as Gunstar Future Heroes in Europe, is a run and gun video game for the Game Boy Advance developed by Treasure and published by Sega in 2005. It is the sequel to the 1993 Sega Genesis game Gunstar Heroes, with the story taking place after the events of the original game and featuring an expanded combat system over its predecessor.', 'https://en.wikipedia.org/wiki/Gunstar_Super_Heroes'),
  ('Q3573068', 'The following is a list of video games developed and published by Konami, based on Kazuki Takahashi''s Yu-Gi-Oh! manga and anime franchise, along with its spin-off series. With some exceptions, the majority of the games follow the card battle gameplay of the real-life Yu-Gi-Oh! Trading Card Game. There are 59 in total.

Platforms: Game Boy, Game Boy Color, Game Boy Advance, GameCube, Mobile, Nintendo DS, Nintendo 3DS, Nintendo Switch, PC, PlayStation, PlayStation 2, PlayStation 3, PlayStation 4, PlayStation 5, PSP, Wii, Xbox, Xbox 360, Xbox One, Xbox Series X/S.', 'https://en.wikipedia.org/wiki/List_of_Yu-Gi-Oh!_video_games'),
  ('Q3573062', 'Yu-Gi-Oh! The Sacred Cards is a Game Boy Advance game based on the Yu-Gi-Oh! anime, developed and published by Konami. It was first released in Japan on July 4, 2002. It was released in North America the following year and in Europe the year after that.

Unlike most of the previous Yu-Gi-Oh! video games, this game has a story. It is based on the Battle City arc of the anime. The player assumes the role as a friend of Yugi Muto as they compete in the Battle City tournament.

The game was re-released in 2025 as part of the Yu-Gi-Oh! Early Days Collection game compilation.', 'https://en.wikipedia.org/wiki/Yu-Gi-Oh!_The_Sacred_Cards'),
  ('Q3504171', 'Super Dodge Ball Advance is a dodge ball video game produced by Atlus and Ubi Soft that was released for the Game Boy Advance in 2001. It is a spin-off of the Super Dodge Ball series although it does not feature the Kunio-kun characters, despite it being licensed to Atlus by the then successor of Technōs Japan, Million Co., Ltd.', 'https://en.wikipedia.org/wiki/Super_Dodge_Ball_Advance'),
  ('Q3504715', 'Superman: Countdown to Apokolips is a 2003 action video game for the Game Boy Advance, developed by Canadian studio Mistic Software and published by Infogrames under the Atari brand name. It was based on Superman: The Animated Series.', 'https://en.wikipedia.org/wiki/Superman:_Countdown_to_Apokolips'),
  ('Q3226597', 'Disney''s The Lion King 1½ (known as Disney''s The Lion King outside North America) is a 2003 platform game based on the 2004 animated film of the same name. It was developed by Vicarious Visions and published by Disney Interactive, whilst THQ distributed the game in Europe. The game was released worldwide for Game Boy Advance on October 7, 2003 (the same day the original film came to DVD for the first time), 4 months before the film came out.', 'https://en.wikipedia.org/wiki/The_Lion_King_1%C2%BD_(video_game)'),
  ('Q3271697', 'Boktai: The Sun Is in Your Hand is an action-adventure role-playing video game released by Konami for the Game Boy Advance in 2003, and the first game in the Boktai series. The player takes the role of Django, a vampire hunter, who uses a weapon called the "Gun Del Sol" (Solar Gun), that fires bolts of sunlight at enemies. The game made novel use of a light sensor on the cartridge which encouraged playing parts of the game in direct sunlight. The game was produced and designed by Hideo Kojima.', 'https://en.wikipedia.org/wiki/Boktai:_The_Sun_Is_in_Your_Hand'),
  ('Q3072358', 'Final Fantasy I & II: Dawn of Souls is a 2004 video game compilation developed by Square Enix and Tose and published by Nintendo for the Game Boy Advance. The package features the WonderSwan Color remakes of Final Fantasy (1987) and Final Fantasy II (1988), the first two games in the Final Fantasy series originally released for the Nintendo Entertainment System, which were previously featured in the 2002 PlayStation compilation Final Fantasy Origins. Apart from an enhanced presentation and quality-of-life improvements, the collection features new dungeons for the first game and a playable epilogue for the second game.', 'https://en.wikipedia.org/wiki/Final_Fantasy_I_%26_II:_Dawn_of_Souls'),
  ('Q3062930', 'F-Zero Climax is a racing video game developed by Suzak Inc. and published by Nintendo for the Game Boy Advance (GBA) handheld console. The game was released in Japan on October 21, 2004, and marked the final F-Zero installment for 19 years until the 2023 release of F-Zero 99.

Players race in vehicles on numerous courses while navigating past obstacles. While the game is a 2D racer, its Mode 7-styled graphical effect allows the track to be scaled and rotated around the vehicle to simulate a 3D environment. Climax let players store rewarded speed boosts to use with energy-draining speed boosts. Energy is a reflection of the craft''s health, and can be restored by driving over specific areas on the track.', 'https://en.wikipedia.org/wiki/F-Zero_Climax'),
  ('Q3546915', 'Justice League: Injustice for All is a 2002 video game developed by Saffire and published by Midway Games for the Game Boy Advance. The game is based on the Justice League animated television series and showcases the League''s seven members within the context of a side-scrolling beat ''em up with platforming elements. The plot centers on the League''s efforts to avert global catastrophe carried out by Lex Luthor''s Injustice Gang.

Development commenced upon Midway Games'' acquisition of the rights to the Justice League of America comic book series and TV series, which took place during an industry-wide trend of video game publishers acquiring comic book superhero licenses. The game received mixed reviews from critics, who regarded it as a short and formulaic brawler indistinct from other entries in the genre.', 'https://en.wikipedia.org/wiki/Justice_League:_Injustice_for_All'),
  ('Q3154354', 'Iridion II is a scrolling shooter video game developed by Shin''en Multimedia and published by Majesco and Vivendi Universal Games in North America and PAL regions respectively for the Game Boy Advance handheld video game console. It is the sequel to Iridion 3D although it is played from a different perspective.

Iridion was re-released on Steam on April 8, 2020, alongside Iridion 3D', 'https://en.wikipedia.org/wiki/Iridion_II'),
  ('Q3482234', 'Shining Soul is an action role-playing game for the Game Boy Advance. It is part of the Shining series. Shining Soul is a reboot of the Shining series. The game was followed by a sequel, Shining Soul II, in 2003. Both games were re-released in Japan in early 2006 as part of the Game Boy Advance "Value Selection".', 'https://en.wikipedia.org/wiki/Shining_Soul'),
  ('Q3497066', 'Star X is a rail shooter video game developed by Graphic State and published by BAM! Entertainment for the Game Boy Advance handheld video game console. It was first released in North America on April 15, 2002, and later was released in the PAL regions on May 17, 2002.', 'https://en.wikipedia.org/wiki/Star_X'),
  ('Q3072788', 'Fire Emblem: The Binding Blade is a 2002 tactical role-playing game developed by Intelligent Systems and published by Nintendo for the Game Boy Advance (GBA). It is the sixth mainline entry in the Fire Emblem series, the first title produced for the system, and the first title to appear on a handheld console.

The Binding Blade is set on the fictional continent of Elibe, which has been dominated by humans for centuries following an ancient war between humanity and dragons. The story follows Roy, a young nobleman from the small independent nation of Pherae as he leads a growing army against the forces of King Zephiel of the kingdom of Bern, who is gradually taking over Elibe with the aid of a mysterious power. As with other Fire Emblem games, battles take place on a grid-based map, with player units assigned character classes taking part in single combat with enemies and being subject to permanent death if defeated.', 'https://en.wikipedia.org/wiki/Fire_Emblem:_The_Binding_Blade'),
  ('Q3108764', 'Rhythm Tengoku is a 2006 rhythm game developed and published by Nintendo for the Game Boy Advance. It was originally released on August 3, 2006, and was the last first-party game to be released for the console. The game began as an idea created by its composer and supervisor Tsunku, who proposed it to Nintendo due to his belief that they could do a better job with it than he could. An arcade version of the game was reprogrammed and published by Sega on September 20, 2007. Both versions were released in Japan exclusively. The game was the first in the Rhythm Heaven series which spawned four international sequels; Rhythm Heaven, Rhythm Heaven Fever, Rhythm Heaven Megamix, and Rhythm Heaven Groove.', 'https://en.wikipedia.org/wiki/Rhythm_Tengoku'),
  ('Q1195267', 'WarioWare, Inc.: Mega Microgames!, known as WarioWare, Inc.: Minigame Mania in PAL regions, is a 2003 action game developed and published by Nintendo for the Game Boy Advance. The debut title in the WarioWare series, the game is about rapid completion of "microgames", short minigames given to the player consecutively and with increasing speed per each game complete. The game''s concept was inspired by the "Sound Bomber" mode of Mario Artist: Polygon Studio for the Nintendo 64DD. Many of the music tracks and sound effects (including Wario''s voice clips) were recycled from Wario Land 4. The game was produced by Takehiro Izushi and directed by Hirofumi Matsuoka. Matsuoka was also the director of Polygon Studio. Mega Microgames! was released in 2003; in Japan in March, in North America and Europe in May and in Australia in June.', 'https://en.wikipedia.org/wiki/WarioWare,_Inc.:_Mega_Microgames!'),
  ('Q3120980', 'Compile Corporation was a Japanese video game developer, most notable for having developed the Puyo Puyo series, a franchise derived from the Madō Monogatari series. On November 6, 2003, the company shut down amid bankruptcy. As a result, key staff moved to Compile Heart, the company''s spiritual successor, whereas shoot-''em-up staff moved to MileStone Inc.

The Compile trademark is being used as a brand label by Compile Heart to promote merchandise and games based on Compile properties. As of 2010, Compile Heart entered into a licensing deal with D4 Enterprise to create new video games based on franchises from Compile properties. This agreement does not affect the rights to the Puyo Puyo series as Sega retains ownership of the property.', 'https://en.wikipedia.org/wiki/Compile_(company)'),
  ('Q3482233', 'Shining Soul II is an action role-playing game for the Game Boy Advance. It was developed by Grasshopper Manufacture, as the sequel to Shining Soul and part of the Shining series. The game was originally scheduled to be released on February 24, 2004, before it was delayed by two months.

The game is a dungeon crawling hack and slash, playing similarly to Diablo or Baldur''s Gate: Dark Alliance. It features eight playable characters, ten dungeons tied into a storyline, and eight hidden dungeons to explore. The game supports multiplayer via link cable as well as single-player.', 'https://en.wikipedia.org/wiki/Shining_Soul_II'),
  ('Q3483555', 'Sigma Star Saga is a 2005 hybrid action role-playing shoot ''em up developed by WayForward and published by Namco Hometek for the Game Boy Advance. The game alternates between top-down overworld exploration and side-scrolling space combat, following human pilot Ian Recker as he infiltrates the alien Krill empire. An updated remaster, Sigma Star Saga DX, was released in April 2026 for modern consoles and PC.', 'https://en.wikipedia.org/wiki/Sigma_Star_Saga'),
  ('Q3550712', 'Yu-Gi-Oh! World Championship Tournament 2004, known in Japan as Yu-Gi-Oh! Duel Monsters Expert 3, is a card battle video game based on the Yu-Gi-Oh! franchise. This game was released for the Game Boy Advance system in 2004, and was re-released in 2025 as part of the Yu-Gi-Oh! Early Days Collection game compilation.', 'https://en.wikipedia.org/wiki/Yu-Gi-Oh!_World_Championship_Tournament_2004'),
  ('Q3532027', 'Top Gear GT Championship, known in Japan as Zen Nihon GT Senshuken, is a racing game developed and published by Kemco for the Game Boy Advance and released in 2001. The game was a launch title in Japan and Europe for the Game Boy Advance, and was the first Game Boy Advance game in the Top Gear series. The Japanese release was compatible with the Mobile Adapter GB accessory.', 'https://en.wikipedia.org/wiki/Top_Gear_GT_Championship'),
  ('Q3546928', 'Justice League: Chronicles is a 2003 beat ''em up video game developed by Full Fat and published by Midway Games for the Game Boy Advance. The game, based on the Justice League animated television series, features three episodic storylines, each showcasing a pair of the League''s members in an overhead beat ''em up format and including a challenge with a 3D Mode 7 presentation.

The game was announced as a sequel to Midway''s previous Justice League game Injustice for All under the working title Justice League: Dark Reflections. Upon release, it was received unfavorably by critics, who faulted its unresponsive controls, repetitive combat, and lackluster presentation.', 'https://en.wikipedia.org/wiki/Justice_League:_Chronicles'),
  ('Q3573059', 'Yu-Gi-Oh! Dungeon Dice Monsters is a dice-based tactics video game based on an original board game featured in the Yu-Gi-Oh! storyline. It was developed and published by Konami, and released on March 21, 2001, in Japan, February 11, 2003, in North America and July 11, 2003, in Europe for the Game Boy Advance. The gameplay revolves around battling opponents using magical dice placed on a board to create dungeons. It contains both a single-player campaign mode in which the player battles the AI, as well as a head-to-head multiplayer mode.

Critics gave the game mixed reviews, praising the game''s strategy elements, while criticizing its lack of a story mode and difficult learning curve, made harder by the lack of a tutorial.', 'https://en.wikipedia.org/wiki/Yu-Gi-Oh!_Dungeon_Dice_Monsters'),
  ('Q262638', 'TMNT is a hack and slash video game featuring the Teenage Mutant Ninja Turtles. It was developed by Ubisoft Montreal and published by Ubisoft for the Game Boy Advance. It is based on the 2007 film of the same name and was first released in North America on March 20, 2007, and was later released in Australia on March 22, 2007, and in Europe on March 23, 2007.

Another game with the same title was also released on the Xbox 360, Wii, PlayStation 2, GameCube, Microsoft Windows, Nintendo DS, and PlayStation Portable, though this version is vastly different from any of the others released, being a 2.5-D side-scrolling beat-''em-up game involving no three-dimensional gameplay - more in style of the original arcade installment.', 'https://en.wikipedia.org/wiki/TMNT_(GBA_video_game)'),
  ('Q1368157', 'WarioWare: Twisted! is an action video game developed by Nintendo and Intelligent Systems and published by Nintendo for the Game Boy Advance. It was released on October 14, 2004, in Japan; May 19, 2005 in Australia; and May 23, 2005, in North America. The third game in the WarioWare series and the seventh in the Wario series overall, Twisted! was the last Wario game to be released on a Game Boy family system, having been released after the launch of the Nintendo DS outside of Japan.

Wario and his friend Dr. Crygor invent Game Boy Advance games and units that only react when tilted around. The game follows the WarioWare formula with a variety of games that last for only a few seconds. The cartridge utilizes a gyro sensor and players must spin and twist in order to play the games.', 'https://en.wikipedia.org/wiki/WarioWare:_Twisted!'),
  ('Q2421937', 'Mega Man Zero 4 is a 2005 hack and slash platform game developed by Inti Creates and published by Capcom for the Game Boy Advance. It is the fourth and final installment of the Mega Man Zero subseries of the Mega Man franchise and is set several months after the events of Mega Man Zero 3.

The game deals with the effects of Dr. Weil''s reign over Neo Arcadia, established at the end of the previous game. Oppressed humans begin to escape in large numbers to the last-known habitable location on the planet, Area Zero, prompting violent retribution from Neo Arcadia. The effects of this conflict eventually drive Zero and the Resistance to protect Area Zero and its inhabitants from Dr. Weil.', 'https://en.wikipedia.org/wiki/Mega_Man_Zero_4'),
  ('Q2426378', 'Atomic Betty is a 2005 puzzle action video game developed by Big Blue Bubble and Breakthrough New Media and published by Namco Hometek for the Game Boy Advance. Based on the Canadian animated television series by the same name, the game takes place both on Earth and in space. The player controls five characters from the show to defeat the villain Maximus IQ.

The developers aimed to include fan-favorite characters with a focus on teamwork. Atomic Betty was promoted at the 2005 Electronic Entertainment Expo and had a sweepstakes giveaway after its release in North America. The next year, Atari released the game in Europe through a new partnership with Namco Bandai.', 'https://en.wikipedia.org/wiki/Atomic_Betty_(video_game)'),
  ('Q1754203', 'Boktai: The Sun Is in Your Hand is an action-adventure role-playing video game released by Konami for the Game Boy Advance in 2003, and the first game in the Boktai series. The player takes the role of Django, a vampire hunter, who uses a weapon called the "Gun Del Sol" (Solar Gun), that fires bolts of sunlight at enemies. The game made novel use of a light sensor on the cartridge which encouraged playing parts of the game in direct sunlight. The game was produced and designed by Hideo Kojima.', 'https://en.wikipedia.org/wiki/Boktai:_The_Sun_Is_in_Your_Hand'),
  ('Q5219604', 'F-Zero: GP Legend is a 2003 racing video game developed by Suzak Inc. and published by Nintendo for the Game Boy Advance. It was released in Japan in 2003 and in Europe and North America in 2004.

The video game is based on the anime of the same name. A sequel was released in 2004 exclusively in Japan, titled F-Zero Climax.', 'https://en.wikipedia.org/wiki/F-Zero:_GP_Legend'),
  ('Q1358804', 'The Legend of Zelda: A Link to the Past and Four Swords is a 2002 action-adventure game compilation developed by Nintendo R&D2 and Flagship and published by Nintendo for the Game Boy Advance. The game was released in December 2002 in North America and in March 2003 in Japan and Europe. The cartridge contains a modified port of A Link to the Past, originally released for the Super Nintendo Entertainment System in 1991, and an original multiplayer-only game titled Four Swords, which serves as the ninth installment in The Legend of Zelda series.

A stand-alone port of Four Swords was released for a limited time on Nintendo''s DSiWare service as The Legend of Zelda: Four Swords Anniversary Edition on September 28, 2011; this version includes new content, such as a single-player mode and additional areas.', 'https://en.wikipedia.org/wiki/The_Legend_of_Zelda:_A_Link_to_the_Past_and_Four_Swords'),
  ('Q5196402', 'Custom Robo GX is an action role-playing game developed by Noise, and published by Nintendo for the Game Boy Advance on July 26, 2002, in Japan. The game stayed on Nintendo Power''s future release list for a few years, until the release of the next title of the series, Custom Robo: Battle Revolution for the GameCube (known as Custom Robo in North America). NOISE also planned the sequel Custom Robo GX 2, but later dropped it in favor of Custom Robo Arena for the Nintendo DS. Nintendo previously planned to release it in late 2005 in Japan. Custom Robo GX is the third title of the Custom Robo series as well as the last Custom Robo title never released outside Japan.', 'https://en.wikipedia.org/wiki/Custom_Robo_GX'),
  ('Q2383167', 'Mother 3 is a 2006 role-playing video game developed by Brownie Brown and HAL Laboratory and published by Nintendo for the Game Boy Advance. It is the third and final entry in the Mother series. The game follows Lucas, a young boy with psychic abilities, and a party of characters as they attempt to prevent a mysterious invading army from corrupting and destroying the world.

Like previous entries, Mother 3 focuses on exploring the game world from a top-down perspective and engaging in turn-based combat with enemies. Its development spanned twelve years and four consoles, beginning in 1994 for the Super Famicom and then transitioning to the Nintendo 64 and its 64DD add-on, when it was known as EarthBound 64. It was initially canceled in 2000, but development was restarted in 2003 for the Game Boy Advance. The game is noted for its significantly more mature and dramatic tone than its predecessors, exploring themes such as environmentalism, capitalism, consumerism, loss and grief, and rebellion against tyranny. However, it still retains much of the series'' characteristic witty, idiosyncratic aesthetics and humor.', 'https://en.wikipedia.org/wiki/Mother_3'),
  ('Q2311359', 'X-Men: Reign of Apocalypse is a 2001 beat ''em up game developed by Digital Eclipse and published by Activision for the Game Boy Advance. Players control the X-Men as they attempt to find the missing Professor X and stop Apocalypse from devastating the world.', 'https://en.wikipedia.org/wiki/X-Men:_Reign_of_Apocalypse'),
  ('Q1754927', 'Sega Rally Championship is a 1995 racing game developed and published by Sega. Originally released for arcades using the Sega Model 2 board, ports were published for the Sega Saturn in 1995 and Microsoft Windows in 1997. It is a rally racing game that simulates driving on different surfaces with varying friction, with the car''s handling changing accordingly. As the first racing game to incorporate this feature, Sega Rally Championship is considered to be a milestone in the evolution of the racing game genre. It is however considered an arcade game with a degree of realism rather than a fully realistic simulator of rallying. The game features both cooperative and competitive multiplayer. An enhanced version was released for the Saturn in 1998, supporting analog controls with the Saturn 3D Pad and online play via the Sega Net Link.', 'https://en.wikipedia.org/wiki/Sega_Rally_Championship'),
  ('Q2446730', 'Garfield merchandise is the merchandise based on the "Garfield" comic strip by Jim Davis. Garfield is one of the world''s most prominent and widely syndicated comic strips, and was specifically designed to be marketable. Before the sale of Paws, Inc. in August 2019, all the profits from merchandise went to Paws, Inc., of which Jim Davis is the CEO and founder. The following is a compiled list of selected merchandise based on the franchise.', 'https://en.wikipedia.org/wiki/Garfield_merchandise'),
  ('Q5223138', 'Dark Arena is a first-person shooter video game for the Game Boy Advance. It was the first FPS game announced for the Game Boy Advance, but it was the fourth released. Another Game Boy Advance game, Cruis''n Velocity, used the same game engine.', 'https://en.wikipedia.org/wiki/Dark_Arena'),
  ('Q5229397', 'Dave Mirra Freestyle BMX 3 is a 2002 sports video game developed by Full Fat and published by Acclaim Entertainment for the Game Boy Advance. It was developed in conjunction with the console title BMX XXX, the obscenity of which caused its endorsement by Dave Mirra to be removed. The game received positive reviews from critics.', 'https://en.wikipedia.org/wiki/Dave_Mirra_Freestyle_BMX_3'),
  ('Q5245521', 'Dead to Rights is a 2004 top-down shooter video game developed by Torus Games and published by Namco Hometek for the Game Boy Advance. It is loosely based on the original Dead to Rights console game.', 'https://en.wikipedia.org/wiki/Dead_to_Rights_(GBA_video_game)'),
  ('Q2333614', 'Tekken Advance is a 2001 fighting game developed by Eighting and published by Namco for the Game Boy Advance. It uses sprites based on Tekken 3''s 3D models for its characters but the overall menus, fonts and art-style are all modeled after Tekken Tag Tournament. It was the first Tekken game to be released on a Nintendo platform.', 'https://en.wikipedia.org/wiki/Tekken_Advance'),
  ('Q5220738', 'Danny Phantom: Urban Jungle is a side-scrolling video game developed by Altron and published by THQ for the Game Boy Advance and Nintendo DS handhelds. It is based on the episode "Urban Jungle" from the Nickelodeon television series Danny Phantom and is the second video game for the series, after Danny Phantom: The Ultimate Enemy. Players play the role of Danny Phantom in his adventure to save Amity Park from various villains from the show.', 'https://en.wikipedia.org/wiki/Danny_Phantom:_Urban_Jungle'),
  ('Q5220737', 'Danny Phantom: The Ultimate Enemy is a 2005 video game developed by Altron and published by THQ for the Game Boy Advance console. It is based on the episode "The Ultimate Enemy!" from the television series Danny Phantom and is the first video game for the series. Players play the role of Danny Phantom in his adventure to save Amity Park from a grim future where he has become evil.', 'https://en.wikipedia.org/wiki/Danny_Phantom:_The_Ultimate_Enemy'),
  ('Q1320023', 'Yu-Gi-Oh! Worldwide Edition: Stairway to the Destined Duel, later released in Japan as Yu-Gi-Oh! Duel Monsters International, is a Game Boy Advance game developed and published by Konami in 2003. It is a modified version of Yu-Gi-Oh! Duel Monsters 6: Expert 2, previously released for the Game Boy Advance in 2001, and adapts the "Battle City" story arc of the original Yu-Gi-Oh! series. The game was re-released in 2025 as part of the Yu-Gi-Oh! Early Days Collection game compilation.', 'https://en.wikipedia.org/wiki/Yu-Gi-Oh!_Worldwide_Edition:_Stairway_to_the_Destined_Duel'),
  ('Q1322480', 'Phoenix Wright: Ace Attorney is a visual novel adventure game developed and published by Capcom. It was released in 2001 for the Game Boy Advance in Japan and has been ported to multiple platforms. The 2005 Nintendo DS version, titled Gyakuten Saiban Yomigaeru Gyakuten in Japan, introduced an English language option, and was the first time the game was released in North America and Europe. It is the first entry in the Ace Attorney series; several sequels and spin-offs were produced, while this game has seen further ports and remasters for computers, game consoles, and mobile devices.

The story follows Phoenix Wright, a rookie defense attorney who attempts to have his clients declared "not guilty". Among other characters are Phoenix''s boss, Mia Fey; his assistant and Mia''s sister, Maya; and prosecutor Miles Edgeworth. The player controls Phoenix through two sets of sections: investigations and courtroom trials. During investigations they gather information and evidence. During trials they cross-examine witnesses, and answer questions from the judge, the prosecutor, and the witnesses. The story is split into five cases. The fifth was introduced in the Nintendo DS version to take advantage of gameplay elements using the handheld''s touchscreen not available in the original Game Boy Advance version.', 'https://en.wikipedia.org/wiki/Phoenix_Wright:_Ace_Attorney'),
  ('Q2588758', 'Sword of Mana, originally released in Japan as Shin''yaku: Seiken Densetsu (新約 聖剣伝説; lit. A New Testament: The Legend of the Sacred Sword), is a 2003 action role-playing game developed by Square Enix and Brownie Brown and published by Square Enix and Nintendo for the Game Boy Advance. It is an enhanced remake of the first game in the Mana series, the Game Boy game Seiken Densetsu: Final Fantasy Gaiden, which was released as Final Fantasy Adventure in North America and as Mystic Quest in Europe. Sword of Mana was the fifth release in the series. Set in a high fantasy universe, the game follows an unnamed hero and heroine as they seek to defeat the Dark Lord and defend the Mana Tree from enemies who wish to misuse its power.', 'https://en.wikipedia.org/wiki/Sword_of_Mana'),
  ('Q4859668', 'Barbie Horse Adventures is a series of video games based on Mattel''s Barbie line of dolls. The series is aimed at children and involves various aspects of equestrianism.', 'https://en.wikipedia.org/wiki/Barbie_Horse_Adventures'),
  ('Q4866426', 'Baseball Advance (released in Japan as Greatest Nine) is a sports game for the Nintendo Game Boy Advance, developed by Smilebit and released by THQ in March 2002. It was generally praised by critics upon its release. The game is the final entry in the Greatest Nine series.', 'https://en.wikipedia.org/wiki/Baseball_Advance'),
  ('Q4869950', 'BattleBots: Beyond the BattleBox is a video game based on the BattleBots license for the Game Boy Advance. It was developed by Cave+Barn Studios and Pipe Dream Interactive and was published by Majesco. Players create and manage a team of BattleBots.

The game was reissued as BattleBots: Design & Destroy starting from August 31, 2003, in order to capitalize on rival robot combat title Robot Arena 2.', 'https://en.wikipedia.org/wiki/BattleBots:_Beyond_the_BattleBox'),
  ('Q4869949', 'BattleBots: Beyond the BattleBox is a video game based on the BattleBots license for the Game Boy Advance. It was developed by Cave+Barn Studios and Pipe Dream Interactive and was published by Majesco. Players create and manage a team of BattleBots.

The game was reissued as BattleBots: Design & Destroy starting from August 31, 2003, in order to capitalize on rival robot combat title Robot Arena 2.', 'https://en.wikipedia.org/wiki/BattleBots:_Beyond_the_BattleBox'),
  ('Q4915187', 'Bionicle: Matoran Adventures is a 2002 platform game based on Lego''s Bionicle line of constructible action figures. It was developed by Argonaut Games and co-published by Electronic Arts and Lego Interactive for the Game Boy Advance. The player controls Matoran and Turaga characters, who must work together to repel the invasion of Bohrok, insect-like robots that threaten the island of Mata Nui.

The game features six levels and three boss battles. Matoran can jump higher and throw discs, while Turaga can activate switches and destroy obstacles; players can switch between the two during gameplay depending on need, similar to the 1993 video game The Lost Vikings. Additional characters can be unlocked by collecting mask pieces scattered throughout levels. Matoran Adventures received mixed reviews from critics. The gameplay and charm were praised by some, with some comparing it favorably to The Lost Vikings, while its short length and lack of creativity were more poorly received.', 'https://en.wikipedia.org/wiki/Bionicle:_Matoran_Adventures'),
  ('Q4915188', 'Aside from the toys in the Lego Bionicle franchise, Lego has also marketed a book series, several video games (mostly for the Game Boy Advance), and four animated movies which feature important plot points. A Bionicle comic book was also published by DC Comics and made available free to members of the Lego Club with some issues of the Lego Magazines. Some comic issues were also posted on the official Bionicle website, Bionicle.com. There are also various other ancillary products available, such as watches, toothbrushes, and backpacks, as well as online adventure games.', 'https://en.wikipedia.org/wiki/List_of_Bionicle_media'),
  ('Q4943317', 'Bookworm is a word-forming puzzle video game developed and published by PopCap Games. From a grid of available letters, players connect letters to form words. As words are formed, they are removed from the grid and the remaining letters collapse to fill the available space. Players earn more points by creating longer words or words which use less common letters and earn less for smaller words. In November 2006, PopCap Games released a sequel, Bookworm Adventures. Bookworm was released for the Nintendo DS digital distribution service DSiWare on November 30, 2009. It has also been released on the regular Nintendo DS cartridge. Bookworm is the most downloaded word puzzle game, being downloaded over 100 million times. The deluxe version of the game features updated graphics, Action Game, and the Hall of Fame.', 'https://en.wikipedia.org/wiki/Bookworm_(video_game)'),
  ('Q5310157', 'Dual Blades is a fighting video game published by Metro3D for the Game Boy Advance. It is a fighting game with single player and player versus player modes. It features a "power combining system" which was very new for the genre at that time. This system allows players to create their own fighting style. Characters include ninjas, knights, and American adventurers, an Ottoman warrior named Efe and Nagasapa, an innocent-looking old lady who is in fact a Kazakh sorceress.

The game is also notable for being one of only nine Game Boy Advance games to be released with an M rating from the ESRB.

A sequel, Slashers: The Power Battle, made by Stun Games was released in 2013.', 'https://en.wikipedia.org/wiki/Dual_Blades'),
  ('Q2712105', 'Bomberman Tournament is a game in the Bomberman series for the Game Boy Advance. The game contains a multiplayer battle mode between linked Game Boy Advance consoles. The player and up to three others can compete in any of the game''s eight multiplayer battle arenas, each of which has its own unique gameplay twist.', 'https://en.wikipedia.org/wiki/Bomberman_Tournament'),
  ('Q2705679', 'Dragon Ball Z: The Legacy of Goku is an action role-playing video game for the Game Boy Advance, based on the anime series Dragon Ball Z and part of the Dragon Ball video game series, developed by Webfoot Technologies and released in 2002. The first part of the trilogy of the same name, it was released in North America on May 14, 2002 and in Europe on October 4, 2002, and was published by Infogrames. In the game, the player, as the protagonist Goku, faces various missions and fights along the plot of the first three seasons of the series, up to the Frieza Saga.', 'https://en.wikipedia.org/wiki/Dragon_Ball_Z:_The_Legacy_of_Goku_(video_game)'),
  ('Q2609107', 'Mega Man Battle Network is a 2001 tactical role-playing game developed by Capcom for the Game Boy Advance (GBA) handheld console. It is the first title of the Mega Man Battle Network series of games. It was originally released in Japan as a GBA launch game on March 21, 2001 and was released later that year in North America and Europe. The game was re-released via the Wii U Virtual Console in Japan on July 9, 2014, in Europe on July 24, 2014, and in North America on July 31, 2014. In 2023, the game was re-released again as part of the Mega Man Battle Network Legacy Collection.

Battle Network takes place during the 21st century in a world where society and everyday life is driven by the Internet. Users are able to interact with and virtually explore nearly any electronic device using highly advanced online avatars called "NetNavis". The game follows an 11-year-old young boy named Lan Hikari and his NetNavi MegaMan.EXE as they solve a series of crimes instigated by the "WWW (World Three)" organization. While many previous entries in the wider Mega Man franchise feature platformer gameplay, Battle Network is instead a tactical role-playing game in which the player controls Lan in the game''s outside world and MegaMan.EXE in its virtual world. Battles take place in real-time; special abilities called "Battle Chips" can be accessed to fight off the numerous computer viruses present in the game''s cyberspace environments.', 'https://en.wikipedia.org/wiki/Mega_Man_Battle_Network_(video_game)'),
  ('Q2712511', 'Digimon Racing is a racing video game developed by Griptonite Games and published by Bandai (now Namco Bandai Games) for the Game Boy Advance. Part of the Digimon media franchise and video game series, it utilizes Digimon''s characters and elements. Its gameplay largely resembles that of traditional racing games, but also utilizes elements of kart racing and action games. Its eleven playable characters can be increased to over 33 via Digivolution.

Digimon Racing uses 2D scaled graphics and voice acting. The game was initially announced at Electronic Entertainment Expo (E3) 2003 and later exhibited at E3 2004. It was released on April 1, 2004, in Japan; April 30 in Europe; and September 13 in North America. It received mixed reviews from critics upon release, with criticism directed at its resemblance to other kart racers of the time and praise at some aesthetic and gameplay aspects.', 'https://en.wikipedia.org/wiki/Digimon_Racing'),
  ('Q5307541', 'Drill Dozer is a platformer video game developed by Game Freak and published by Nintendo for the Game Boy Advance (GBA). Directed by Ken Sugimori, the game stars Jill and her mech Drill Dozer, which has a drill that the player can rotate in both directions to fight enemies, drill into certain surfaces, and screw objects. Sugimori aimed to make an action game that does not use traditional types of combat, and was inspired by the concept of a tokusatsu monster who could drill through anything. He also wished to make the drill not just pushing a button, but instead using one of two buttons to activate the drill (either drilling forward or in reverse). When drilling, the built-in rumble pack will activate, a feature suggested by Nintendo.', 'https://en.wikipedia.org/wiki/Drill_Dozer'),
  ('Q5472711', 'Fortress is a tower defense strategy video game developed by Pipe Dream Interactive and published by Majesco for the Game Boy Advance (GBA) handheld game console. It originally released in North America in August 2001, and later in PAL regions on November 23, 2001. It was originally announced as Fortris for PlayStation and Dreamcast by developer Prometheau Games, but was acquired by Majesco and moved to the Game Boy Advance. The game has players building and defending their fortress against either another player or a computer using falling blocks to build it up and falling weapons to fight back against opponents.', 'https://en.wikipedia.org/wiki/Fortress_(2001_video_game)'),
  ('Q2698085', 'Castlevania: Harmony of Dissonance is a 2002 action role-playing game developed and published by Konami for the Game Boy Advance. The second installment of the Castlevania series on the Game Boy Advance, the game was released in Japan in June 2002 and in North America and PAL regions later that same year. Harmony of Dissonance is set in the year 1748, fifty years after Simon Belmont vanquished Dracula''s curse in Castlevania II: Simon''s Quest. Harmony of Dissonance focuses on Simon''s grandson, Juste Belmont, and his quest to rescue a kidnapped childhood friend.

Similarly to previous Castlevania titles, the game employs role-playing game features alongside more traditional exploration elements. Progression is split between two versions of the titular castle, requiring Juste to traverse both maps in search of abilities, armor and weapons to combat an assortment of enemies, including various bosses. In addition to his whip and subweapons found around each castle''s grounds, Juste can perform more powerful magic attacks by finding spell books that can imbue sub weapons he finds in each castle with elemental properties, as well as augmentations for his whip that can destroy certain obstacles blocking progression to certain areas of each map.', 'https://en.wikipedia.org/wiki/Castlevania:_Harmony_of_Dissonance'),
  ('Q5324241', 'ESPN Final Round Golf 2002 is a golf video game developed and published by Konami. It was released in North America on August 28, 2001. In Europe it was known as ESPN Final Round Golf. The game is a facelift version of the Japanese GBA title Golf Master: Japan Golf Tour which is identical except for the player list which in the Japanese version consisted mostly of Japanese tour players.', 'https://en.wikipedia.org/wiki/ESPN_Final_Round_Golf_2002'),
  ('Q2617932', 'Duke Nukem Advance is a 2002 video game in the Duke Nukem series, released for the Game Boy Advance. Although it is a first-person shooter and many of the graphics and sounds have been ported from Duke Nukem 3D, the game has an original storyline and levels, and can thus be considered to be a spin-off of 3D.

Four difficulty levels can be selected at the beginning of the game. Multiplayer games are possible, with up to four players requiring a copy. An option to save one''s progress appears at the completion of each level, with five save game slots to choose from.

The game received mostly positive reviews.', 'https://en.wikipedia.org/wiki/Duke_Nukem_Advance'),
  ('Q5291321', 'Domo is the official mascot of Japanese public broadcaster NHK, appearing in several 30-second stop-motion interstitial sketches, which are shown as station identification in between the channel''s programming. The character is a furry monster that is boxy and brown and often has his big mouth wide open.', 'https://en.wikipedia.org/wiki/Domo_(NHK)'),
  ('Q5439325', 'Fear Factor: Unleashed is a Game Boy Advance game that is based on the reality series Fear Factor. Ports for PlayStation 2 and Xbox were planned in the next year but later cancelled.', 'https://en.wikipedia.org/wiki/Fear_Factor:_Unleashed'),
  ('Q5451412', 'The following is a list of all video games in the Fire Pro Wrestling series produced by either Human Entertainment or Spike starting in 1989. Most of the titles in the series were released exclusively in Japan.', 'https://en.wikipedia.org/wiki/List_of_Fire_Pro_Wrestling_games'),
  ('Q477882', 'Wing Commander: Prophecy is the fifth installment in the Wing Commander science fiction space combat simulator franchise of computer games. The game was released in 1997 for Windows, produced by Origin Systems and distributed by Electronic Arts. In 2003, a Game Boy Advance conversion with added multiplayer was produced by Italy-based Raylight Studios and distributed by Destination Software.

The game features a new game engine (the VISION Engine), new spacecraft, characters and story elements. The events depicted in Prophecy are set over a decade after Wing Commander IV: The Price of Freedom and, rather than the Kilrathi, the player must deal with a new alien threat, an insectoid race codenamed Nephilim that has invaded the human galaxy through a wormhole. Prophecy was the first main-line Wing Commander game in which the player did not take on the role of Christopher Blair, instead being introduced to a new player character, Lance Casey. Some of the characters and actors from previous games return in Prophecy, where they rub elbows with an entirely new cast of Confederation pilots and personnel.', 'https://en.wikipedia.org/wiki/Wing_Commander:_Prophecy'),
  ('Q2625613', 'Shrek the Third is an action-adventure video game based on the 2007 DreamWorks Animation animated film of the same name, developed by Amaze Entertainment, 7 Studios, Shaba Games and Vicarious Visions. The game was published by Activision in May 2007, for Game Boy Advance, Microsoft Windows, Nintendo DS, Wii, Xbox 360, PlayStation 2 and PlayStation Portable.

The soundtrack was composed by Winifred Phillips and produced by Winnie Waldron, with additional music by Geoff Zanelli. It was the last DreamWorks Animation game released for the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Shrek_the_Third_(video_game)'),
  ('Q2045645', 'Pokémon Emerald Version is a 2004 role-playing video game developed by Game Freak and published by The Pokémon Company and Nintendo for the Game Boy Advance. It was first released in Japan in 2004, and was later released internationally in 2005. It is the fifth version, after both Pokémon Ruby and Sapphire and Pokémon FireRed and LeafGreen, and is the final game of the third generation of the Pokémon video game series.

The gameplay and controls are largely the same as the previous games in the series; players control a Pokémon trainer from an overhead perspective. As with Ruby and Sapphire, the player''s general goal is to explore the Hoenn Region and conquer a series of eight Pokémon Gyms in order to challenge the Elite Four and the Hoenn League Champion, while the main subplot is to defeat two criminal organizations attempting to harness a legendary Pokémon''s power for their own goals. Along with Pokémon that debuted in Ruby and Sapphire, the game incorporates Pokémon from Pokémon Gold and Silver not featured in Ruby and Sapphire.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Emerald'),
  ('Q610923', 'Sonic Battle is a 2003 fighting game developed by Sonic Team and published by Sega for the Game Boy Advance. It is the second fighting game in the Sonic the Hedgehog series, after Sonic the Fighters (1996). Taking place between the events of Sonic Advance 2 (2002) and Sonic Advance 3 (2004), Sonic Battle revolves around various characters fighting over an ancient robot. It was released in Japan in December 2003 and in North America and Europe in early 2004. The game received a mixed response from critics.', 'https://en.wikipedia.org/wiki/Sonic_Battle'),
  ('Q602642', 'Banjo-Pilot is a 2005 kart racing video game for the Game Boy Advance (GBA) and the fourth installment in Rare''s Banjo-Kazooie series. It plays similarly to the Mario Kart series by Nintendo: the player races one of nine playable characters around tracks, attacking other racers with bullets and collecting power-ups. The game features a number of single-player and multiplayer modes, such as time attack and item hunts. Unlike other kart racing games, characters control airplanes instead of go-karts.

Rare and Nintendo announced Banjo-Pilot at E3 2001 under the title Diddy Kong Pilot. At this point, it was the sequel to Rare''s Diddy Kong Racing (1997), and featured characters from Nintendo''s Donkey Kong and Mario series. However, company politics and Nintendo''s concerns about quality delayed Diddy Kong Pilot past its planned release date in March 2002. After Microsoft acquired Rare in September 2002, it lost the rights to the Nintendo characters and replaced them with characters from its Banjo series.', 'https://en.wikipedia.org/wiki/Banjo-Pilot'),
  ('Q4046997', 'Pirates of the Caribbean: The Curse of the Black Pearl is a video game prequel to the film of the same name, developed by British company Pocket Studios and released for Game Boy Advance in 2003.', 'https://en.wikipedia.org/wiki/Pirates_of_the_Caribbean:_The_Curse_of_the_Black_Pearl_(video_game)'),
  ('Q4116496', 'Ice Age is a 2002 platform game based on the film of the same name, developed by Artificial Mind and Movement, published by Ubi Soft and released exclusively for the Game Boy Advance. A sequel, Ice Age 2: The Meltdown, was released on multiple platforms in 2006, itself based on the film of the same name.

It was also used as a runner-up prize during Cartoon Network''s Frozen Fantasy Sweepstakes, where people would register via the company''s website, while the grand prize winner would get an Alaskan cruise for four, where they''ll see glaciers.', 'https://en.wikipedia.org/wiki/Ice_Age_(2002_video_game)'),
  ('Q1527204', 'Army Men Advance is a 2001 top-down shooter video game developed by DC Studios and published by the 3DO Company for the Game Boy Advance. Much like Army Men: Sarge''s Heroes, the story has General Plastro and his army of tan figurines have decided to take over the world, and it is up to Sarge and reporter Vikki Grimm to thwart the conquest. Throughout the game, the player is required to rescue team members, infiltrate tan bases, escape from a jail, investigate an extraterrestrial presence, and retrieve communications equipment. The player can choose to play as either Sarge or Vikki, but the quests for each are identical, and once a character has been chosen, it is impossible to switch to the other unless the player wants to start again from the first mission.', 'https://en.wikipedia.org/wiki/Army_Men_Advance'),
  ('Q1527222', 'Army Men: Operation Green is a 2001 top-down shooter video game developed by Pocket Studios and published by The 3DO Company for the Game Boy Advance. It is part of the Army Men series of games by The 3DO Company, which is based on army men toys. It is the second game in the series for the Game Boy Advance, after 2001''s Army Men Advance.

The player controls a lone green army men soldier in tan army men soldier territory. The green soldier must complete objectives across 15 levels in order for the player to complete the game. Reception was mixed, noting that the game was an improvement over others in the Army Men video game series, but still finding fault with the game''s level design and missions.', 'https://en.wikipedia.org/wiki/Army_Men:_Operation_Green'),
  ('Q4050406', 'Super Monkey Ball Jr. is a platform video game developed by Realism and Creations and published by Sega for the Game Boy Advance. It is one of the few games on the system to make use of its 3D graphics capabilities. It reuses levels from other games in the Super Monkey Ball series. It was the last game to be developed by Creations before their acquisition by Acclaim Entertainment.', 'https://en.wikipedia.org/wiki/Super_Monkey_Ball_Jr.'),
  ('Q588270', 'Tiny Toon Adventures: Wacky Stackers is the first Tiny Toon Adventures video game released on the Nintendo Game Boy Advance. It was released on December 30, 2001, and was developed by Warthog and published by Conspiracy Games in North America and Swing! Entertainment in Europe. It is the first puzzle-style game for the franchise. The game features several characters from the television series, including: Buster Bunny, Montana Max, Elmyra Duff, Furrball, Babs Bunny, Plucky Duck, Gogo Dodo and Dizzy Devil.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Wacky_Stackers'),
  ('Q4044070', 'Message in a Haunted Mansion is the third installment in the Nancy Drew point-and-click adventure game series by Her Interactive. The game is available for play on Microsoft Windows platforms as well as Game Boy Advance. Players take on the first-person view of fictional amateur sleuth Nancy Drew and must solve the mystery through interrogation of suspects, solving puzzles, and discovering clues. There are two levels of gameplay: Junior and Senior detective modes. Each mode offers a different difficulty level of puzzles and hints, but none of these changes affect the plot of the game. The game is loosely based on the book The Message in the Haunted Mansion (1995).', 'https://en.wikipedia.org/wiki/Nancy_Drew:_Message_in_a_Haunted_Mansion'),
  ('Q2019488', 'Tales of the World: Narikiri Dungeon 3 is a spin-off from the Tales RPG series made by Namco. The game was released exclusively in Japan for the Game Boy Advance on January 6, 2005. Tales of the World: Narikiri Dungeon 3''s characteristic genre name is Cosplay S-RPG.', 'https://en.wikipedia.org/wiki/Tales_of_the_World:_Narikiri_Dungeon_3'),
  ('Q2038683', 'Crazy Taxi: Catch a Ride is a racing action video game for the Game Boy Advance, part of the Crazy Taxi series. It was developed by Graphic State and published by Sega. This game is an attempt to port the original Crazy Taxi to the Game Boy Advance, featuring two cities (one unlockable), nine Crazy Box minigames and all four cabbies from the original game.', 'https://en.wikipedia.org/wiki/Crazy_Taxi:_Catch_a_Ride'),
  ('Q4051516', 'Tiny Toon Adventures: Buster''s Bad Dream is the second Tiny Toon Adventures-related game released on the Nintendo Game Boy Advance. It was released on July 5, 2002, in Europe and was developed by Treasure Co. Ltd and published by Swing! Entertainment.', 'https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Buster%27s_Bad_Dream'),
  ('Q580676', 'Disney Sports Basketball is a 2002 sports video game published by Konami. It was released for the GameCube, and the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Disney_Sports_Basketball'),
  ('Q4051158', 'The Little Mermaid is an American media franchise created by The Walt Disney Company based on "The Little Mermaid", written by Danish poet Hans Christian Andersen. The success of the 1989 animated film led to a sequel, a prequel, a television series, a musical, several video games, theme park attractions, and other merchandise. A live-action remake of the film was released in 2023. The Little Mermaid paved the way for what would become the Disney Renaissance, with the original film becoming the first film of that era. It is also one of the highest-grossing media franchises.', 'https://en.wikipedia.org/wiki/The_Little_Mermaid_(franchise)'),
  ('Q6372794', 'Karnaaj Rally is a racing and vehicular combat game for the Game Boy Advance handheld video game console developed by Polish game developer, Infinite Dreams. It was released on November 21, 2002. The game was well received by critics. It was re-released on UIQ3 platforms as K-Rally in 2007. It uses 3D polygons.', 'https://en.wikipedia.org/wiki/Karnaaj_Rally'),
  ('Q6314922', 'Jurassic Park III: Island Attack (known as Jurassic Park III: Advanced Action in Japan and Jurassic Park III: Dino Attack in Europe; originally known as Jurassic Park III: Primal Fear) is a video game for the Game Boy Advance, and is loosely based on the 2001 film Jurassic Park III. It is the third and final game, under the title Jurassic Park III, for the Game Boy Advance title games after The DNA Factor and Park Builder, both released in the same year.', 'https://en.wikipedia.org/wiki/Jurassic_Park_III:_Island_Attack'),
  ('Q6902814', 'Monster Rancher Advance 2 (known in Japan as Monster Farm Advance 2) is the second of the Monster Rancher games to be released on Game Boy Advance. It is the sequel to Monster Rancher Advance.', 'https://en.wikipedia.org/wiki/Monster_Rancher_Advance_2'),
  ('Q3714563', 'Double Dragon Advance is a 2003 beat ''em up video game developed by Japanese studio Million and published by Atlus for the Game Boy Advance. It is a remake of Technōs Japan''s 1987 arcade game Double Dragon and incorporates elements from its sequels and home versions.

It was rereleased on Steam, PS4, Xbox and Nintendo Switch on 8th November 2023.', 'https://en.wikipedia.org/wiki/Double_Dragon_Advance'),
  ('Q6168261', 'Jazz Jackrabbit is a 2002 platform game developed by Game Titan and published by Jaleco under license from Epic Games. It is the third game in the Jazz Jackrabbit series.', 'https://en.wikipedia.org/wiki/Jazz_Jackrabbit_(2002_video_game)'),
  ('Q1839174', 'Sonic Pinball Party is a 2003 pinball video game developed by Sonic Team and Jupiter and published by Sega for the Game Boy Advance. The game features many references to Sonic Team''s previous games, most prominently Sonic the Hedgehog, Nights into Dreams, and Samba De Amigo.

Sonic Pinball Party received generally positive reviews from critics. In 2005, the game would be released on two Twin Pack cartridges bundled with Sonic Battle and Sonic Advance, respectively.', 'https://en.wikipedia.org/wiki/Sonic_Pinball_Party'),
  ('Q3815419', 'Peter Jackson''s King Kong: The Official Game of the Movie (also known as Peter Jackson''s King Kong, or simply King Kong) is a 2005 action-adventure video game developed by Ubisoft Montpellier and published by Ubisoft, based on the 2005 film King Kong. It was created in collaboration between the film''s director Peter Jackson and the game''s director Michel Ancel. The film''s cast members reprise their roles. The game follows New York scriptwriter Jack Driscoll through Skull Island, as he attempts to save love interest Ann Darrow who has been sacrificed by the island''s natives to the giant gorilla Kong.', 'https://en.wikipedia.org/wiki/King_Kong_(2005_video_game)'),
  ('Q6703677', 'Lunar Legend (LUNARレジェンド) is a 2002 role-playing video game for Game Boy Advance developed by Japan Art Media and published internationally by Ubi Soft, who also provided the translation. It is a re-telling of the events of Lunar: The Silver Star with story and content changes. All the characters from the original game appear.', 'https://en.wikipedia.org/wiki/Lunar_Legend'),
  ('Q6699626', 'Lufia: The Ruins of Lore, known in Japan as Chinmoku no Iseki: Estpolis Gaiden, is a role-playing video game developed by Atelier Double and published by Taito in Japan in 2002 and by Atlus a year later in North America. It is the fourth title in the Lufia series of video games and was released as a "gaiden", or side story, to the main series; as a result, it does not feature many elements common to the rest of the series, such as the Sinistrals and the Dual Blade.', 'https://en.wikipedia.org/wiki/Lufia:_The_Ruins_of_Lore'),
  ('Q6798460', 'Mazes of Fate is a first-person role-playing video game developed by Argentinian studio Sabarasa and published by Graffiti Entertainment for the Game Boy Advance and the Nintendo DS. The Game Boy Advance version was released in North America on December 12, 2006.

A reconversion, titled Mazes of Fate DS, was released for the Nintendo DS on July 25, 2008, in Europe and on September 9, 2008, in North America. It improved on the original by fixing bugs present in the original, introducing a 3D engine in dungeons as a replacement of fake-3D, adding new secret areas in dungeons, and including new dungeon maps. A major bug in the DS port removed the challenge of combat by making nearly all enemies killable before they can approach the player and start counterattacking.', 'https://en.wikipedia.org/wiki/Mazes_of_Fate'),
  ('Q1797550', 'Mario & Luigi: Superstar Saga is a 2003 role-playing video game developed by AlphaDream and published by Nintendo for the Game Boy Advance. It is the first game in the Mario & Luigi series. The story follows Mario and Luigi as they travel to the Beanbean Kingdom in order to combat Cackletta and Fawful, who stole Princess Peach''s voice for the purpose of harnessing the power of a special artifact called the Beanstar.

Superstar Saga is the third role-playing game in the Mario franchise, following Super Mario RPG (1996) and Paper Mario (2000), and features a lighthearted, whimsical script with a greater emphasis on comedy than earlier titles. The player controls Mario and Luigi simultaneously as they traverse the overworld, fight enemies, gain experience points, and find new items and gear. The battle system differs from traditional role-playing games, with more emphasis on timing and elaborate attacks called Action Commands. Created by Shigeru Miyamoto, Tetsuo Mizuno, and Satoru Iwata, the game was announced at E3 2003, later releasing the same year.', 'https://en.wikipedia.org/wiki/Mario_%26_Luigi:_Superstar_Saga'),
  ('Q6038366', 'Inspector Gadget: Advance Mission is a video game based on the television show of the same name.', 'https://en.wikipedia.org/wiki/Inspector_Gadget:_Advance_Mission'),
  ('Q6902711', 'Monster Force is an action video game developed by Digital Eclipse and published by Universal Interactive exclusively for Game Boy Advance. A planned PlayStation version of the game was to be released in 2001 by Konami, as well as a Game Boy Color version, but these never achieved fruition. In the game, players control stylized versions of classic Universal movie monsters, as they attempt to thwart the plans of their creator''s evil brother.', 'https://en.wikipedia.org/wiki/Monster_Force_(video_game)'),
  ('Q6126468', 'It''s Mr. Pants is a puzzle video game developed by Rare and published by THQ for the Game Boy Advance. It was released in North America in 2004 and Europe in 2005. A port of the game for mobile phones was developed and published internationally by In-Fusio in 2005–2006. The game stars Mr. Pants, a crudely drawn mascot formerly featured on Rare''s website who had made cameo appearances in several prior Rare games.', 'https://en.wikipedia.org/wiki/It%27s_Mr._Pants'),
  ('Q3718598', 'Ecks vs. Sever is a first-person shooter video game developed by Crawfish Interactive and released for the Game Boy Advance in November 2001. It is based on an early script of the 2002 film Ballistic: Ecks vs. Sever. The sequel Ballistic: Ecks vs. Sever follows its plot line more closely than the first game does. Ecks vs. Sever received positive reviews and is considered one of the best first-person shooters for the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Ecks_vs._Sever'),
  ('Q6145062', 'Tomato Adventure is a role-playing video game developed by AlphaDream and published by Nintendo for the Game Boy Advance on January 25, 2002, exclusively in Japan.

The game is recognized as a precursor to AlphaDream''s Mario & Luigi role-playing game series.', 'https://en.wikipedia.org/wiki/Tomato_Adventure'),
  ('Q6917976', 'Moto Racer Advance is a motocross racing game developed by Adeline Software International, produced by Delphine Software International and published by Ubisoft for the Game Boy Advance. It was released in 2002 in PAL regions on October 4 and in North America on December 4. It is part of the Moto Racer series and was the last game to be developed by Adeline Software and also the last with any involvement from Delphine Software.

Moto Racer Advance features several different modes, but much of it centers on a "Progression" mode, which requires the player to compete in races in a variety of environments. Multiplayer is supported through the link cable. Moto Racer Advance garnered positive reception from critics, noting its graphical quality and overall presentation as two of the main reasons for its success. IGN''s Craig Harris called it one of the top racing games from 2002. As of 2009, Moto Racer Advance has received compilation scores of 86/100 and 83% on Metacritic and GameRankings respectively.', 'https://en.wikipedia.org/wiki/Moto_Racer_Advance'),
  ('Q6804438', 'Mech Platoon, known in Japan as Kikaika Gunta - Mech Platoon is a real-time strategy video game developed and published by Kemco. It was the first real-time strategy game released on the Game Boy Advance platform, and was released in 2001.', 'https://en.wikipedia.org/wiki/Mech_Platoon'),
  ('Q374820', 'Darius is a 1987 horizontally scrolling shooter video game developed and published by Taito for arcades. Players control a starship named the Silver Hawk in its mission to destroy the Belser empire before they wipe out the planet Darius. Its gameplay involves traversing through a series of scrolling levels while destroying enemies and collecting power-up icons. It is notable for its unique three-screen panoramic display.

The game was designed by a small team of others led by Junji Yarita. In contrast to other similar games, which feature mechanical or insect-like enemies, Darius uses aquatic creatures like fish and crabs for its enemies and screen-filling bosses. Its large arcade cabinet, based on Taito''s earlier panoramic display game Laser Grand Prix (1983), was designed to provide a cinematic atmosphere and stand out from other games at the time. The soundtrack was created by Taito''s "house band" Zuntata, the majority being composed through a combination of FM synthesis and sampling.', 'https://en.wikipedia.org/wiki/Darius_(video_game)'),
  ('Q6944938', 'Heureka Klett was a German software engineering company which has made several personal computer games of the sort called "edutainment". They are point-and-click puzzle-adventure games, heavily inspired by Myst for Windows and Mac. These were distributed by Tivola International to be localized for many markets.

On June 1, 2005, Heureka-Klett sold its edutainment software to BrainGame Publishing. The holdings and marketing rights of the 22 games in their back catalogue were transferred.

Seven games in the educational series collectively sold over 500,000 units and won numerous awards.', 'https://en.wikipedia.org/wiki/Heureka-Klett'),
  ('Q6305392', 'Juka and the Monophonic Menace is an action-adventure video game published and developed by Orbital Media, Inc. in PAL regions, and published by SouthPeak Interactive in NA. It was slated for release on the Nintendo DS, but it was ultimately canceled.', 'https://en.wikipedia.org/wiki/Juka_and_the_Monophonic_Menace'),
  ('Q6314930', 'Numerous video games based on the Jurassic Park franchise have been released. Developers Ocean Software, BlueSky Software and Sega produced various games in 1993, coinciding with the first film, Jurassic Park. In 1997, several developers, including DreamWorks Interactive and Appaloosa Interactive, produced various games for nine different platforms to coincide with the release of the film The Lost World: Jurassic Park.

For the 2001 film, Jurassic Park III, a total of seven games were produced, including three for the Game Boy Advance and three PC games. A park-building game, Jurassic Park: Operation Genesis, was released in 2003. Jurassic Park: The Game, released in 2011, takes place after the events of the first film. Lego Jurassic World was released in 2015 and is based on the first four films. Subsequent games have continued to use the Jurassic World name, including Jurassic World Evolution, another park-building game that was released in 2018.', 'https://en.wikipedia.org/wiki/Jurassic_Park_video_games'),
  ('Q3782924', 'Hamtaro: Ham-Ham Heartbreak is a 2002 video game in the Hamtaro game series for Game Boy Advance developed by Pax Softnica and published by Nintendo, as the sequel to Tottoko Hamutaro: Tomodachi Daisakusen Dechu and Hamtaro: Ham-Hams Unite!. It was the second Hamtaro game released in America and Europe, but the third released in Japan. It was released in Japan on May 31, 2002, in North America on April 7, 2003, in Australia on May 30, 2003, and in Europe on June 27, 2003. Hamtaro: Ham-Ham Heartbreak was followed by Hamtaro: Rainbow Rescue.

Like its predecessors, Hamtaro: Ham-Ham Heartbreak is an adventure game. Set in the world of the Hamtaro books and anime, the player controls the hamster ("Ham-Ham", as the hamsters tend to call themselves) Hamtaro. The game expands on the gameplay of the earlier titles by adding Bijou, a friend of Hamtaro who has a crush on him, as a partner. Together, they have to save the other hamsters'' relationships from Spat, an evil hamster with a hatred for any kind of relation.', 'https://en.wikipedia.org/wiki/Hamtaro:_Ham-Ham_Heartbreak'),
  ('Q3782925', 'Hamtaro: Rainbow Rescue is an adventure video game developed by AlphaDream for Game Boy Advance. It was released by Nintendo in Japan and PAL regions, and was set to be released in North America, but was cancelled. It is based on the Hamtaro series by Ritsuko Kawai.', 'https://en.wikipedia.org/wiki/Hamtaro:_Rainbow_Rescue'),
  ('Q1853367', 'Virtua Tennis, known in Japan as Power Smash, is a 1999 tennis video game developed by Sega AM3 and published by Sega. Originally released for arcades on the Sega NAOMI hardware, it was ported to the Dreamcast in 2000 and later to Microsoft Windows, Game Boy Advance and N-Gage. The home versions expanded the arcade game with a World Circuit career mode in which players compete in matches and complete training minigames to improve their ranking.

The Dreamcast version received widespread critical acclaim and was nominated for Console Sports Game of the Year, Console Game of the Year and overall Game of the Year at the 4th Annual Interactive Achievement Awards. The game was followed by Virtua Tennis 2 in 2001 and became the first entry in the Virtua Tennis series.', 'https://en.wikipedia.org/wiki/Virtua_Tennis_(video_game)'),
  ('Q5505256', 'Frogger Advance: The Great Quest is a platform game developed by Vicarious Visions and published by Konami for the Game Boy Advance. It was released in North America on May 28, 2002. The game was previously released for the PlayStation 2 under the title Frogger: The Great Quest.', 'https://en.wikipedia.org/wiki/Frogger_Advance:_The_Great_Quest'),
  ('Q2484133', 'Mega Man Zero is a 2002 hack and slash platform game developed by Inti Creates and published by Capcom for the Game Boy Advance. It is the first installment in the Mega Man Zero series, the fifth series in Capcom''s Mega Man video game franchise. The game is set 100 years after the events of the Mega Man X series and follows Zero, a Reploid awakened from his sleep to aid a human scientist named Ciel and her resistance force in a fight against the utopia of Neo Arcadia.

Mega Man Zero was produced as a commission product by Inti Creates for Capcom, who were given free rein on the project''s direction and premise. During development, the developers aimed to make Zero among the most challenging games in the franchise, and to bridge the gap between the mechanical feel of the X series, and the human feel of the Legends series. The initial idea for the antagonist was to have the original X be the villain, however this was changed late into production to a copy robot due to fears of it not sitting well with players.', 'https://en.wikipedia.org/wiki/Mega_Man_Zero_(video_game)'),
  ('Q5505248', 'Frogger''s Adventures: Temple of the Frog is a 2001 platform video game developed and published by Konami for the Game Boy Advance. It was followed by Frogger''s Adventures 2: The Lost Wand in 2002 for the same console. In 2003, another game titled Frogger''s Adventures: The Rescue appeared for PlayStation 2, GameCube and Windows.', 'https://en.wikipedia.org/wiki/Frogger%27s_Adventures:_Temple_of_the_Frog'),
  ('Q5514771', 'GT Advance 3: Pro Concept Racing is a racing game developed by MTO and published by THQ for the Game Boy Advance. It is the sequel to GT Advance 2: Rally Racing, based heavily on the gameplay from GT Advance Championship Racing, and the third game in the GT Advance series.', 'https://en.wikipedia.org/wiki/GT_Advance_3:_Pro_Concept_Racing'),
  ('Q5514768', 'GT Advance 2: Rally Racing is a rally racing game developed by MTO and published by THQ for the Game Boy Advance, as a sequel to GT Advance Championship Racing. The game features cars from several real Japanese car manufacturers. The player can race on fourteen different courses located in various parts of the world or act as the co-driver. The game was released in Japan on the on December 7, 2001, and in North America and Europe in June 2002. It received generally favorable reviews from critics.', 'https://en.wikipedia.org/wiki/GT_Advance_2:_Rally_Racing'),
  ('Q5530293', 'Gekido Advance: Kintaro''s Revenge is a beat ''em up game for the Game Boy Advance, created by Italian studio NAPS Team. It is a sequel to the PlayStation game Gekido. Unlike the previous installment, this game centers on one protagonist, instead of multiple characters as seen in Gekido. A version for N-Gage was planned but never released.

In 2018, Gekido: Kintaro''s Revenge was re-released for the Nintendo Switch, PlayStation 4, Xbox One, and Microsoft Windows.', 'https://en.wikipedia.org/wiki/Gekido_Advance:_Kintaro%27s_Revenge'),
  ('Q5530555', 'Gem Smashers is a puzzle video game developed in Italy by Frame Studios and published by Metro3D for the Game Boy Advance. The game was released in North America on July 1, 2003, and in Japan on November 21, 2003.', 'https://en.wikipedia.org/wiki/Gem_Smashers'),
  ('Q4017481', 'WWE Survivor Series is a professional wrestling video game developed by Natsume Co., Ltd. and published by THQ for the Game Boy Advance handheld console. WWE Survivor Series is based on the World Wrestling Entertainment (WWE) annual pay-per-view, Survivor Series. The game is the sequel to Road to WrestleMania X8. WWE Survivor Series was released in North America on October 21, 2004 and in Europe on November 19, 2004, and was also the last WWE video game released for a Nintendo handheld console until WWE SmackDown vs. Raw 2008 for the Nintendo DS in 2007.

With it being two years since the last Game Boy Advance WWE game, the roster is vastly different from previous one and included eight Raw and eight SmackDown! wrestlers. The story mode was changed to accompany the WWE''s Brand Extension from 2002, meaning the player could choose a particular brand to get to the top before switching brands to conquer another brand. The story mode was also changed in that winning matches wasn''t necessarily the main aim. Instead, the aim was to give out a good match and make matches less one-sided.', 'https://en.wikipedia.org/wiki/WWE_Survivor_Series_(video_game)'),
  ('Q5591947', 'Gradius Galaxies, released in Europe as Gradius Advance and in Japan as Gradius Generation, is a 2001 horizontally scrolling shooter video game developed by Mobile21 and published by Konami for the Game Boy Advance. It was originally released in Europe in November 2001, North America the same month and Japan in January 2002. It is part of the Gradius series. The game''s plot is set between Gradius III and Gradius Gaiden. Bacterion was developing a powerful weapon to use against the planet Gradius, but it was destroyed. A few years later it crashed on a planet and the planet gradually changed into a mechanical fortress. The planet Gradius then sent the Vic Viper to stop it.', 'https://en.wikipedia.org/wiki/Gradius_Galaxies'),
  ('Q5574528', 'Go! Go! Beckham! Adventure on Soccer Island is a platform video game developed by Denki and published by Rage Software for the Game Boy Advance. It was released in Europe in 2002 and was not released in other regions.

The game follows the main character, David Beckham, on his quest to defeat the evil Mister Woe in order to restore peace to Soccer Island. Beckham can use his football in order to collect items and to remove enemies from play. Eurogamer''s Tom Bramwell called the game the best original platform game on the Game Boy Advance released in 2002. As of 2009, Adventure on Soccer Island has received a compilation score of 75% from GameRankings.', 'https://en.wikipedia.org/wiki/Go!_Go!_Beckham!_Adventure_on_Soccer_Island'),
  ('Q2357489', 'Wario Land 4 is a 2001 platform game developed by Nintendo R&D1 and published by Nintendo for the Game Boy Advance. It is the fourth installment in the Wario Land subseries of the Wario series. It was released in Japan in August 2001 and November 2001 internationally. In the game, Wario has to gather four treasures to unlock a pyramid and save Princess Shokora from the Golden Diva. The game received acclaim for its graphics and gameplay.', 'https://en.wikipedia.org/wiki/Wario_Land_4'),
  ('Q2569478', 'Advance Wars 2: Black Hole Rising is a turn-based strategy video game developed by Intelligent Systems and published by Nintendo for the Game Boy Advance. It was released in North America and PAL regions in 2003. It is the second game in the Advance Wars sub-series of Nintendo Wars. It is preceded by Advance Wars and followed by Advance Wars: Dual Strike. Despite being developed in the region, the original Japanese release was canceled, but the game was later released in the region alongside the original Advance Wars as part of a compilation cartridge called Game Boy Wars Advance 1+2 in 2004. The game was released on the Wii U''s Virtual Console in North America and Europe in 2015. At E3 2021, Nintendo announced that Black Hole Rising, alongside the original Advance Wars, would be remade and released together for the Nintendo Switch by WayForward in another compilation titled Advance Wars 1+2: Re-Boot Camp.', 'https://en.wikipedia.org/wiki/Advance_Wars_2:_Black_Hole_Rising'),
  ('Q2736150', 'Yoshi''s Universal Gravitation (released in North America as Yoshi Topsy-Turvy) is a 2004 platform game developed by Artoon and published by Nintendo for the Game Boy Advance. It features a built-in tilt sensor, which is used to manipulate the game''s environment. By tilting the Game Boy Advance left or right, the player can tilt the game area, causing enemies and other objects to slide as the direction of gravity changes. This gameplay mechanic is used to solve puzzles or aid Yoshi in completing levels. The game received mixed reviews; with praise for its aesthetics and premise, mixed opinions about its usage of tilt controls, and criticism for its short length compared to other Yoshi games and its repetitive level design and objectives.', 'https://en.wikipedia.org/wiki/Yoshi%27s_Universal_Gravitation');

insert into import_summary (wikidata_id, summary, source) values
  ('Q4023156', 'Yu Yu Hakusho: Tournament Tactics is a video game for the Game Boy Advance. It is based on the manga and anime series YuYu Hakusho created by Yoshihiro Togashi. The plot follows the protagonist Yusuke Urameshi, a teenage delinquent who dies in an accident and is brought back to life as a "Spirit Detective", a protector of the living world. Tournament Tactics specifically adapts the Dark Tournament story arc of the manga, in which Yusuke and his companions participate in a deadly, demon martial arts competition.

Tournament Tactics is a tactical role-playing game. Gameplay involves having the player move up to five characters on a grid-like battlefield, engage enemy units, and complete objectives. As player characters gain experience points, they level up, improving their statistics and granting them access to special "spirit attacks". Tournament Tactics was co-developed by Sensory Sweep Studios and Screaming Games as part of a publishing deal for Atari to distribute YuYu Hakusho games outside Japan. Tournament Tactics is the third Yu Yu Hakusho game that never saw a release in Japan.', 'https://en.wikipedia.org/wiki/Yu_Yu_Hakusho:_Tournament_Tactics'),
  ('Q5268358', 'Dexter''s Laboratory: Deesaster Strikes! is a 2001 action-adventure video game for the Game Boy Advance based on the Cartoon Network animated series Dexter''s Laboratory. It was released in North America on September 26, 2001, and in the PAL region on November 2, 2001.', 'https://en.wikipedia.org/wiki/Dexter%27s_Laboratory:_Deesaster_Strikes!'),
  ('Q5268357', 'Dexter''s Laboratory is an American animated science fiction comedy television series created by Genndy Tartakovsky for Cartoon Network. The series follows Dexter, an enthusiastic boy-genius with a science laboratory in his bedroom, which he keeps secret from his unsuspecting parents. Dexter is at constant odds with his older and more extroverted sister Dee Dee, who regularly accesses the laboratory and inadvertently foils his experiments. Prominently featured in the first and second seasons are other segments focusing on superhero-based characters Monkey, Dexter''s pet lab-monkey with a superhero alter ego, and the Justice Friends, a trio of superheroes who share an apartment.', 'https://en.wikipedia.org/wiki/Dexter%27s_Laboratory'),
  ('Q2515386', 'Super Mario World is a 1990 platform game developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). It was released in Japan in 1990, in North America in 1991 and PAL territories in 1992. The player controls Mario on his quest to save Princess Peach and Dinosaur Land from the series'' antagonist Bowser and the Koopalings. The gameplay is similar to that of earlier Super Mario games; players control Mario through a series of levels in which the goal is to reach the goalpost at the end. Super Mario World introduces Yoshi, a rideable dinosaur who can eat enemies and spit some of them out as projectiles.', 'https://en.wikipedia.org/wiki/Super_Mario_World'),
  ('Q4016792', 'W.I.T.C.H. is a platform game for the Game Boy Advance. It was developed by Climax Studios and released in Europe on 7 October 2005 by Buena Vista Games. The game was not released outside of Europe.

Although the box art resembles the look of the characters in the comic book, the game''s storyline and graphics are based on season 1 of the animated television series adaptation of the same name.', 'https://en.wikipedia.org/wiki/W.I.T.C.H._(video_game)'),
  ('Q2569809', 'Spyro: Attack of the Rhynocs (known in Europe as Spyro Adventure) is a 2003 platform game developed by Digital Eclipse and published by Universal Interactive for the Game Boy Advance. It was the last Spyro game to be released under the Universal Interactive label, which would be phased out shortly after the game''s release. It was also the final Spyro game to be developed by Digital Eclipse, who would be replaced for the next major handheld entries by Amaze Entertainment.', 'https://en.wikipedia.org/wiki/Spyro:_Attack_of_the_Rhynocs'),
  ('Q2569862', 'Spyro 2: Season of Flame is a 2002 platform game developed by Digital Eclipse and published by Universal Interactive for the Game Boy Advance. It is the fifth installment in the Spyro video game series and a sequel to Spyro: Season of Ice. The game''s story centers on the abduction of the Dragon Realm''s fireflies at the hands of the Rhynocs, causing the dragons to lose their ability to breathe fire. The protagonist of the story, Spyro the Dragon, must recover the fireflies and uncover the culprit behind the firefly theft.

The game received generally favorable reviews from critics, many of whom considered the game to be superior to Spyro: Season of Ice, though the game was criticized for its "tricky" controls.', 'https://en.wikipedia.org/wiki/Spyro_2:_Season_of_Flame'),
  ('Q5575297', 'The King of Fighters EX 2 Howling Blood (KOF EX 2) is a fighting game developed by Marvelous Entertainment for Nintendo''s Game Boy Advance. It is a spin-off of SNK''s The King of Fighters series and acts as a sequel to The King of Fighters EX: Neo Blood. Despite taking graphics, characters and audio from The King of Fighters 2000, the game features an original storyline that focuses on Kyo Kusanagi and his allies in stopping the revival of the demon Yamata no Orochi from Heavenly Kings. It was announced for a 2003 release in the same console. The game was also ported to the N-Gage under the name The King of Fighters Extreme. Hudson Soft developed the game, and it was published by Nokia in Europe.', 'https://en.wikipedia.org/wiki/The_King_of_Fighters_EX2:_Howling_Blood'),
  ('Q2712856', 'Mega Man Zero 2 is a 2003 hack and slash platform game developed by Inti Creates and published by Capcom for the Game Boy Advance (GBA) handheld game console. It is the second video game in the Mega Man Zero subseries of Mega Man video games.

The game is set one year following the events of Mega Man Zero, and follows the same basic format as its predecessor, being a side-scrolling, platform action game. Once again, players take control of the Reploid known as Zero, and lead him through various levels in the battle against the forces of Neo Arcadia.

The European version also released the same day as Mega Man X7 was in North America. It was released in Japan on the Wii U''s Virtual Console on January 7, 2015. In February 2020, the game was released on PlayStation 4, Xbox One, Nintendo Switch, and PC via Steam as part of the Mega Man Zero/ZX Legacy Collection.', 'https://en.wikipedia.org/wiki/Mega_Man_Zero_2'),
  ('Q2500267', 'Spyro: Season of Ice is a 2001 platform game developed by Digital Eclipse and published by Universal Interactive Studios for the Game Boy Advance. It acts as an alternate sequel to the first three games along with Spyro 2: Season of Flame and Spyro: Attack of the Rhynocs.', 'https://en.wikipedia.org/wiki/Spyro:_Season_of_Ice'),
  ('Q2565269', 'ChuChu Rocket! is a 1999 action puzzle game developed by Sonic Team and published by Sega for the Dreamcast. The objective is for the player to place arrows on a board to lead mice into escape rockets while avoiding cats. The game features single-player modes in which a player must save all the mice on a board, and a multiplayer mode in which players battle to collect the most mice.

Directed and produced by Yuji Naka, ChuChu Rocket! was developed to test the Dreamcast''s processing power by displaying many characters at once, and also to test the online functionality of the Dreamcast and Sega''s servers, as it was the first Dreamcast game designed to make use of online. The knowledge gained from the network portion of the project helped Sonic Team in their development of Phantasy Star Online (2000). When it arrived in the United States, Sega held an online tournament where players could battle against Sega and Sonic Team employees. In PAL regions, it was given free to subscribers of Sega''s online gaming service Dreamarena. Although Sega''s online services have long shut down, the game can still be played online via private servers.', 'https://en.wikipedia.org/wiki/ChuChu_Rocket!'),
  ('Q4274305', 'Blender Bros. is a 2002 platform game developed by Hudson Soft and published by Infogrames. The game was originally released for the Game Boy Advance, but in 2020, the game was ported to Windows by Piko Interactive.', 'https://en.wikipedia.org/wiki/Blender_Bros.'),
  ('Q389344', 'Wings is a World War I video game developed and published by Cinemaware. It was released for the Amiga in 1990. The action sequences are similar in style to those of the 1927 silent film Wings.

An enhanced version was released for the Game Boy Advance as Wings Advance in 2002. A remake of the original, Wings! Remastered, was published in 2014 and 2015 for Windows, MacOS, Android, and iOS.', 'https://en.wikipedia.org/wiki/Wings_(1990_video_game)'),
  ('Q2342264', 'Golden Sun: The Lost Age is a 2002 role-playing video game for the Game Boy Advance, developed by Camelot Software Planning and published by Nintendo. It is the second installment in the Golden Sun series and was released on June 28, 2002, in Japan, and in 2003 in North America and Europe.

Taking place after the events of the previous game, The Lost Age puts the player into the roles of the previous games'' antagonists, primarily from the perspective of magic-attuned "adepts" Felix and his allies as they seek to restore the power of alchemy to the world of Weyard. Along the way, the player uses Psynergy to defeat enemies and discover new locations, help out local populations, and find elemental djinn which augment the characters'' powers. Players can transfer their characters and items from Golden Sun to The Lost Age through a password system or Game Link Cable, and are rewarded for fully completing both games.', 'https://en.wikipedia.org/wiki/Golden_Sun:_The_Lost_Age'),
  ('Q4035489', 'Buffy the Vampire Slayer: Wrath of the Darkhul King is a 2003 video game developed by the Japanese company Natsume and published by THQ for the Game Boy Advance. It is an action platformer and the third of six video games based on the supernatural television series Buffy the Vampire Slayer. Set in the show''s fourth season, Wrath of the Darkhul King centers on Buffy Summers and her allies as they attempt to prevent a demonic warlord from initiating an apocalyptic event. The player controls Buffy through sixteen levels that focus on solving puzzles and defeating enemies by using customizable weapons. THQ produced Wrath of the Darkhul King in a publishing agreement with Fox Interactive.', 'https://en.wikipedia.org/wiki/Buffy_the_Vampire_Slayer:_Wrath_of_the_Darkhul_King'),
  ('Q3980414', 'The Tales series, known in Japan as the Tales of series, is a franchise of fantasy Japanese role-playing video games published by Bandai Namco Games (formerly Namco), and developed by its subsidiary, Namco Tales Studio (formerly Wolf Team) until 2011 and presently by Bandai Namco. First begun in 1995 with the development and release of Tales of Phantasia for the Super Famicom, the series currently spans twenty-eight main titles, multiple spin-off games and supplementary media in the form of manga series, anime series, and audio dramas.

While entries in the series generally stand independent of each other with different characters and stories, they are commonly linked by their gameplay, themes and high fantasy settings. Most of the main Tales games have been localized for North America and Europe, although almost all of the spinoff titles have not been released abroad. While generally seen as a niche series in English speaking regions, Tales is considered a high-profile property in Japan, just behind other series such as Final Fantasy and Dragon Quest. As of 2024, the series has shipped over 30 million copies.', 'https://en.wikipedia.org/wiki/List_of_Tales_media'),
  ('Q2012171', 'Metroid: Zero Mission is a 2004 action-adventure game developed and published by Nintendo for the Game Boy Advance. It is a remake of the original Metroid (1986), with updated visuals and gameplay.

Like other Metroid games, the player controls the bounty hunter Samus Aran. Samus travels to the planet Zebes after learning that the Space Pirates are experimenting with Metroids, hostile parasitic creatures, which they plan to use to take over the universe. The gameplay focuses on exploration, with the player searching for power-ups to reach previously inaccessible areas. The remake adds items, additional areas, mini-bosses, difficulty levels and a rewritten story that explores Samus''s past.', 'https://en.wikipedia.org/wiki/Metroid:_Zero_Mission'),
  ('Q2015472', 'WWE Road to WrestleMania X8 is a professional wrestling video game released on the Game Boy Advance handheld console by THQ in 2002, based on WWE''s 2002 pay-per-view WrestleMania X8. The game featured improved gameplay and grappling techniques compared to its predecessor. This game was the Game Boy Advance successor to WWF Road to WrestleMania from 2001 and was succeeded by WWE Survivor Series in 2004. It was one of two games named after the event, the other being WWE WrestleMania X8 for the GameCube, released five months prior in June 2002. Of the three WWE games developed by Natsume Co., Ltd. for the Game Boy Advance, WWE Road to WrestleMania X8 was the most successful in regard to both sales and reviews.', 'https://en.wikipedia.org/wiki/WWE_Road_to_WrestleMania_X8'),
  ('Q2015488', 'WWF Road to WrestleMania is a video game released on the Game Boy Advance handheld console by THQ, based on the World Wrestling Federation''s pay-per-view of the same name. The game was released in Europe on November 16, 2001, and North America on November 19, 2001. It was the first WWF game to be released on the Game Boy Advance, and the only one released under the WWF name, as the promotion was renamed to WWE in 2002. The main part of the game is the season mode where players have to win matches to get a heavyweight championship title match.

The game was succeeded by WWE Road to WrestleMania X8.', 'https://en.wikipedia.org/wiki/WWF_Road_to_WrestleMania'),
  ('Q2291309', 'Castlevania: Aria of Sorrow is a 2003 action role-playing game developed by Konami Computer Entertainment Tokyo and published by Konami for the Game Boy Advance. It is the 20th main entry in the Castlevania series, as well as the third and final game produced for the system. Producer Koji Igarashi, who had led the production teams for previous Castlevania games, oversaw Aria of Sorrow''s development in parallel with its predecessor Castlevania: Harmony of Dissonance (2002). Michiru Yamane returned to compose the music alongside Takashi Yoshida and Soshiro Hokkai. Director Junichi Murakami was new to the Castlevania series.', 'https://en.wikipedia.org/wiki/Castlevania:_Aria_of_Sorrow'),
  ('Q4951731', 'Boxing Fever is a boxing video game developed by Digital Fiction and published by Majesco for the Game Boy Advance. It was released in North America on October 30, 2001, and in Europe on February 15, 2002.

Boxing Fever is a first person boxing game, portrayed from the perspective of the player''s fighter. Multiplayer is supported through the link cable. Boxing Fever received positive reviews from critics, who noted its creative visual style.', 'https://en.wikipedia.org/wiki/Boxing_Fever'),
  ('Q2478949', 'Metroid Fusion is a 2002 action-adventure game developed and published by Nintendo for the Game Boy Advance. It is the fourth main Metroid game. Players control the bounty hunter Samus Aran, who investigates a space station infected with shapeshifting parasites known as X. Along with the GameCube game Metroid Prime, Fusion marked the return of the Metroid series after an eight-year hiatus following Super Metroid (1994).

Like previous Metroid games, Fusion is a side-scrolling game with platform jumping, shooting, and puzzle elements. It introduces mission-based progression that guides the player through certain areas. Fusion can be linked to Prime using the GameCube–Game Boy Advance link cable to unlock additional content for Prime.', 'https://en.wikipedia.org/wiki/Metroid_Fusion'),
  ('Q5533579', 'Gensō Suikoden Card Stories is a spin-off title of the Suikoden franchise by Konami which includes both a Game Boy Advance game and a physical collectible card game. Both were released in the fall of 2001 in Japan.

Unlike other areas of the Suikoden franchise, in which the storyline is a major

element of gameplay, Card Stories focuses mainly on the card battles themselves

and less on the plot.

Most of the cards feature characters who appear in both Suikoden and Suikoden II of Konami''s role-playing video game series.

Several cards also feature characters who would later go on to appear in Suikoden III.', 'https://en.wikipedia.org/wiki/Gens%C5%8D_Suikoden_Card_Stories'),
  ('Q5259317', 'Densetsu no Starfy 2 is a 2003 platform video game developed by Tose and published by Nintendo for the Game Boy Advance in Japan on September 5, 2003. It is the second game in The Legendary Starfy series. It received its re-release on the Nintendo Classics service on July 12, 2024, in all regions for the first time along with its predecessor and sequels.', 'https://en.wikipedia.org/wiki/Densetsu_no_Starfy_2'),
  ('Q5259320', 'Densetsu no Starfy 3 is a platform video game developed by Tose and published by Nintendo for the Game Boy Advance in Japan on August 5, 2004. It is the third game in The Legendary Starfy series. Its sequel, Densetsu no Starfy 4, was developed for the Nintendo DS. It received its re-release on the Nintendo Classics service on July 12, 2024, in all regions for the first time along with the other GBA entries, albeit not translated from Japanese.', 'https://en.wikipedia.org/wiki/Densetsu_no_Starfy_3'),
  ('Q2019474', 'Tales of the World: Narikiri Dungeon 2 is a spin-off from the Tales RPG series made by Namco. The game was released exclusively in Japan for the Game Boy Advance in October 2002. Tales of the World: Narikiri Dungeon 2''s characteristic genre name is Cosplay RPG. While it succeeds Tales of Phantasia: Narikiri Dungeon, this was the first game in the Tales of the World series, which is known for featuring characters from various main Tales games.

Narikiri Dungeon 2, like Tales of Phantasia: Narikiri Dungeon, is a dungeon crawler/RPG. It features the Condensed Linear Motion Battle System, a variation of the series'' trademark battle system.', 'https://en.wikipedia.org/wiki/Tales_of_the_World:_Narikiri_Dungeon_2'),
  ('Q2306443', 'Kirby & The Amazing Mirror is a 2004 platform game developed by HAL Laboratory, Flagship and Dimps and published by Nintendo for the Game Boy Advance. The seventh mainline Kirby entry, the game is notable for its unique Metroidvania playstyle and being the first in the series to support cooperative four-player multiplayer, and follows Kirby as he goes on a journey through the Mirror Dimension to reassemble a mirror after Dark Meta Knight traps Meta Knight inside it.', 'https://en.wikipedia.org/wiki/Kirby_%26_the_Amazing_Mirror'),
  ('Q1545555', 'Golden Sun is a 2001 role-playing video game developed by Camelot Software Planning and published by Nintendo for the Game Boy Advance. The game follows a band of magic-attuned teenagers called Adepts on a mission to protect the world of Weyard from alchemy, a potentially destructive power that was sealed away long ago. During their quest, the Adepts develop new magic abilities called Psynergy, assist others, and learn more about why alchemy was sealed away. Golden Sun is followed by a sequel, The Lost Age, which together form a complete story.

Golden Sun was released in August 2001 in Japan, November 2001 in North America, and February 2002 in Europe. It began as a single planned game for the Nintendo 64, but production shifted to the Game Boy Advance over the course of development. After facing hardware constraints, the developers decided to split the game into two.', 'https://en.wikipedia.org/wiki/Golden_Sun_(video_game)'),
  ('Q2003093', 'Digimon Battle Spirit 2 is a fighting video game released for WonderSwan Color in 2002 and Game Boy Advance in 2004. It was developed by Dimps and published by Bandai based on the fourth season of the Digimon anime, Digimon Frontier. It was originally released in Japan for the WonderSwan Color handheld in December 2002 with the title Digimon Frontier: Battle Spirit. It was later ported to the Game Boy Advance for the Western market, released in North America in September 2003, and Europe in August 2004.', 'https://en.wikipedia.org/wiki/Digimon_Battle_Spirit_2'),
  ('Q3962987', 'Smashing Drive is a racing video game developed and published by Gaelco and distributed by Namco. The game was released in arcades in 2000 and was ported to the GameCube and Xbox in 2002 by Point of View and Game Boy Advance in 2004 by DSI Games and Namco.', 'https://en.wikipedia.org/wiki/Smashing_Drive'),
  ('Q3977600', 'Super Robot Taisen: Original Generation 2 is a tactical role-playing game for the Game Boy Advance. It is the second Super Robot Taisen game that was officially released in North America.

The story selection system of Super Robot Taisen: Original Generation did not return. Instead, Original Generation 2 has a branching storyline during intervals of the game. Original Generation 2 primarily focuses on two protagonists from the first game, one of which is selected by the player at the start: Kyosuke Nanbu and Excellen Browning. In addition, a total of four new series (three of them past Super Robot Wars games, while one is a manga) appear, adding new characters, mechs, major events from the respective stories of the series and some original creations for this game itself. The user interface was also redesigned.', 'https://en.wikipedia.org/wiki/Super_Robot_Wars_OG_2'),
  ('Q3977615', 'Super Robot Wars R is a video game for the Game Boy Advance and is part of the Super Robot Wars franchise. It is the second game for the handheld system, preceded by Super Robot Wars A. Like its predecessor, it is ported into a mobile cellphone as part of the Super Robot Wars i line.', 'https://en.wikipedia.org/wiki/Super_Robot_Wars_R'),
  ('Q4023155', 'Yu Yu Hakusho: Spirit Detective is a video game for the Game Boy Advance (GBA) handheld console. Based on the manga and anime series YuYu Hakusho created by Yoshihiro Togashi, the plot follows the central character Yusuke Urameshi, a street-brawling, often truant teenager who dies trying to save a young boy''s life. After meeting an incarnation of the Grim Reaper, Yusuke is given a second chance at life as a "Spirit Detective", a protector of the living world.

Spirit Detective is an action-adventure game that retells the various events of the anime''s story arc of the same name. The player takes control of one of six characters from the series and must complete various objectives from collecting items and completing mazes to battling enemies and occasional bosses. Spirit Detective was co-developed by Sensory Sweep Studios and Screaming Games as part of a western region publishing deal from Atari. Spirit Detective is the first Yu Yu Hakusho game that never saw a release in Japan.', 'https://en.wikipedia.org/wiki/Yu_Yu_Hakusho:_Spirit_Detective'),
  ('Q5523136', 'Garfield merchandise is the merchandise based on the "Garfield" comic strip by Jim Davis. Garfield is one of the world''s most prominent and widely syndicated comic strips, and was specifically designed to be marketable. Before the sale of Paws, Inc. in August 2019, all the profits from merchandise went to Paws, Inc., of which Jim Davis is the CEO and founder. The following is a compiled list of selected merchandise based on the franchise.', 'https://en.wikipedia.org/wiki/Garfield_merchandise'),
  ('Q4274898', 'Boktai 2: Solar Boy Django, also known as Zoktai, is a video game that was developed and published by Konami for the Game Boy Advance. Released in North America and Japan in 2004 and in Europe in 2005, it is the sequel to Boktai: The Sun Is in Your Hand.

Boktai 2''s game cartridge includes a photometric light sensor that measures the amount of sunlight/UV rays exposed to it.', 'https://en.wikipedia.org/wiki/Boktai_2:_Solar_Boy_Django'),
  ('Q211858', 'DK: King of Swing is a 2005 puzzle-platform game developed by Paon and published by Nintendo for the Game Boy Advance. King of Swing diverges from the gameplay of other games in the Donkey Kong series, instead featuring characters rotating around pegs and using their spinning momentum to progress. King of Swing has a single-player adventure mode, as well as a competitive multiplayer mode for up to four players. The game received mixed reception.

DK: King of Swing was re-released for the Wii U''s Virtual Console in Japan and North America in November 2014 and in Europe and Australia in January 2015. A sequel, DK: Jungle Climber, was released for the Nintendo DS in 2007.', 'https://en.wikipedia.org/wiki/DK_King_of_Swing'),
  ('Q5282475', 'Disney Sports Skateboarding is a 2002 skateboarding video game developed and published by Konami. It was released for the GameCube and Game Boy Advance. It received negative reviews.', 'https://en.wikipedia.org/wiki/Disney_Sports_Skateboarding'),
  ('Q2734887', 'Tactics Ogre: The Knight of Lodis is a tactical role-playing game developed by Quest Corporation and published by Nintendo for the Game Boy Advance (GBA). It was released in Japan in 2001, and in North America by Atlus USA in 2002. It is a spin-off of Tactics Ogre (1995), acting as a prequel to the rest of the Ogre Battle series. It was the last video game developed by Quest before their acquisition by Square.

The storyline follows Lodis soldier Alphonse Loeher as he learns of his country''s oppression of the neighbouring land of Ovis and eventually turns against his former comrades. As with Tactics Ogre, the game is mission based, with combat taking place on grid-based battlefields and revolving around character classes and character statistics.', 'https://en.wikipedia.org/wiki/Tactics_Ogre:_The_Knight_of_Lodis'),
  ('Q5282474', 'Disney Sports Soccer, known as Disney Sports Football in Europe, is a pair of 2002 sports video games released by Konami, one for the GameCube, and the other for the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Disney_Sports_Soccer'),
  ('Q2517463', 'Pokémon Pinball: Ruby & Sapphire is a 2003 pinball game developed by Jupiter and published by The Pokémon Company and Nintendo for the Game Boy Advance handheld game console. It was first revealed at E3 2003. The North American release was done to coincide with the fifth anniversary of the North American release of Pokémon Red and Blue. It is based on Pokémon Ruby and Sapphire, and is a sequel to Pokémon Pinball for the Game Boy Color. In some ways, it plays like a traditional pinball game, where the objective is to get a high score by keeping the ball in play as long as possible and hitting bumpers. In keeping with the theme of Pokémon, it features Pokémon collection, where while the players play pinball, they must also capture the eponymous creatures.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Pinball:_Ruby_%26_Sapphire'),
  ('Q1574163', 'Mario vs. Donkey Kong is a 2004 puzzle-platform game developed by Nintendo Software Technology and published by Nintendo for the Game Boy Advance. The game is the spiritual successor to Donkey Kong, which was released in 1994 for the Game Boy.

The gameplay revolves around a combination of platform and puzzle elements. Players control Mario through small sets of challenges to find a key and rescue Mini-Marios from Donkey Kong.

Mario vs. Donkey Kong received positive reviews, particularly for its gameplay and graphics. It spawned a franchise of the same name with the first sequel, Mario vs. Donkey Kong 2: March of the Minis, released on Nintendo DS in September 2006. A remake for the Nintendo Switch was released in February 2024.', 'https://en.wikipedia.org/wiki/Mario_vs._Donkey_Kong'),
  ('Q2513822', 'Rayman: Hoodlums'' Revenge, (French: Rayman: La Revanche des Hoodlums) is a platform game developed by Digital Eclipse and published by Ubisoft for the Game Boy Advance in 2005. It was the first Rayman game to be a isometric platformer and was set after Rayman 3: Hoodlum Havoc.', 'https://en.wikipedia.org/wiki/Rayman:_Hoodlums%27_Revenge'),
  ('Q740515', 'Madagascar is a 2005 platform game based on the animated film of the same name by Eric Darnell and Tom McGrath, produced by DreamWorks Animation. The game was released on May 24, 2005 in North America and on June 30, 2005 in Europe. The GameCube, PlayStation 2 and Xbox versions were developed by Toys for Bob. The Microsoft Windows version was developed by Beenox and the Nintendo DS and Game Boy Advance versions were developed by Vicarious Visions. All versions of the game were published by Activision. Madagascar: Operation Penguin was the next Madagascar video game to be released on the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Madagascar_(video_game)'),
  ('Q3898391', 'Paws and Claws: Pet Vet is a pet-raising simulation video game by German studio Radon Labs in which players can nurse dogs, cats, horses, birds, hamsters, guinea pigs and rabbits back to health. The game features 20 ailments. Players can design their own clinic, choose which kennels to build and expand existing buildings to provide further services to their patients.', 'https://en.wikipedia.org/wiki/Paws_and_Claws:_Pet_Vet'),
  ('Q3955335', 'indieszero Corporation, Ltd. is a Japanese video game developer headquartered in Musashino, Tokyo, Japan. Founded on April 21, 1997, it is a frequent collaborator with Nintendo, developing some of their smaller scale and more experimental titles.', 'https://en.wikipedia.org/wiki/Indieszero'),
  ('Q1988536', 'He-Man: Power of Grayskull is an isometric action game for the Game Boy Advance, published by TDK Mediactive in 2002.', 'https://en.wikipedia.org/wiki/He-Man:_Power_of_Grayskull'),
  ('Q2001228', 'Dynasty Warriors Advance is a 2005 hack and slash video game developed by Omega Force and published by Koei for the Game Boy Advance. A spin-off of the Dynasty Warriors series, it was published outside Japan by Nintendo. It is the only installment in the series to be released for the Game Boy Advance as well as the first to not be released on a PlayStation console.', 'https://en.wikipedia.org/wiki/Dynasty_Warriors_Advance'),
  ('Q3907201', 'Polarium Advance is a 2005 puzzle video game developed by Mitchell Corporation and published by Nintendo for the Game Boy Advance. Despite starting development before it, it is not a sequel to Polarium on the Nintendo DS. It was released in Japan in October 2005 and Europe in March 2006, with Atlus releasing it in North America in November 2006. The objective of the game is similar to that of its predecessor; black and white tiles fill a grid, and by drawing a single line in the grid, tiles can be flipped from black to white (or vice versa). Solid, horizontal lines of all black or all white tiles are erased, and the goal is to erase the entire grid in this manner.', 'https://en.wikipedia.org/wiki/Polarium_Advance'),
  ('Q3959791', 'Shrek: Hassle at the Castle is a 2D beat ''em up video game released in 2002 for the Game Boy Advance. It is based on the 2001 movie Shrek, and features characters from it. It is the only game in the franchise that follows the plot of the first movie. A sequel, Shrek: Reekin'' Havoc, was released in 2003.', 'https://en.wikipedia.org/wiki/Shrek:_Hassle_at_the_Castle'),
  ('Q3957907', 'Serious Sam Advance (also marketed as Serious Sam) is a 2004 first-person shooter game developed by Climax London and published by Global Star Software for the Game Boy Advance. A spin-off in the Serious Sam series, the game has the player control Sam "Serious" Stone through confined levels—first in ancient Egypt, then in ancient Rome—defeating varying enemies using an assortment of weapons. Serious Sam Advance was developed by Climax London, a studio of former Crawfish Interactive developers, using ray casting technology. Global Star Software announced the game in January 2004 and released it in April. Serious Sam Advance received mixed reviews, with praise for its weapons, enemies, level design, and sound effects, conflicting opinions about its graphics, and criticism for its controls and frame rate issues.', 'https://en.wikipedia.org/wiki/Serious_Sam_Advance'),
  ('Q3882554', 'One Piece, also referred to as Shonen Jump''s One Piece, is a side-scrolling beat ''em up game for the Game Boy Advance. It is based on the One Piece anime series. Developed by Dimps and published by Bandai America''s games division, it was released on September 7, 2005. It is the only One Piece game to be released exclusively in North America, and the first of two to not see a release in Japan. Due to being an American-only title released while 4Kids Entertainment was involved in the dubbing and localization of the anime, there are a few discrepancies compared to the canon material, matching 4Kids'' edits and changes of the anime.', 'https://en.wikipedia.org/wiki/One_Piece_(video_game)'),
  ('Q7121849', 'Pac-Man Pinball Advance is a pinball video game developed by Hungarian studio Human Soft and published by Namco Hometek for the Game Boy Advance. It was released in North America on May 3, 2005. It is part of the Pac-Man video game franchise.

The game switches from normal Pac-Man gameplay to a pinball-style video game. Pac-Man Pinball Advance received mixed to negative reviews from critics, who felt that its gameplay was limited.', 'https://en.wikipedia.org/wiki/Pac-Man_Pinball_Advance'),
  ('Q1886919', 'Super Mario Advance 4: Super Mario Bros. 3 is a 2003 platform game developed and published by Nintendo for the Game Boy Advance. It was released in Japan, and later released in Europe, North America, and Australia. It is an enhanced remake of the 1988 NES video game Super Mario Bros. 3, and is based on the remake found in Super Mario All-Stars for the Super Nintendo Entertainment System. Players control either Mario or Luigi as they travel through the eight kingdoms of the Mushroom World to rescue Princess Peach from Bowser. The game was revealed at Nintendo''s conference at the E3 2003 convention. It contains several enhancements, including the addition of Mario and Luigi''s voices by Charles Martinet, the ability to scan e-Cards into Nintendo''s e-Reader to add certain content, and a multiplayer mode based on the original arcade game Mario Bros.. The game also allows players to save replays of their gameplay.', 'https://en.wikipedia.org/wiki/Super_Mario_Advance_4:_Super_Mario_Bros._3'),
  ('Q7682744', 'Tang Tang is a platform game released in arcades in 2000 by the South Korean arcade game developer Excellent Soft Design (ESD). It received a port on the Game Boy Advance which released on August 28, 2001.', 'https://en.wikipedia.org/wiki/Tang_Tang'),
  ('Q6428752', 'Konami Collector''s Series: Arcade Advanced, known in Japan as Konami Arcade Game Collection and in Europe as Konami Collector''s Series: Arcade Classics, is a compilation video game developed and published by Konami in 2002 for the Game Boy Advance. The anthology features enhanced remakes of six of the company''s popular arcade games from the 1980s. In addition to updated visuals, the title took advantage of the handheld console''s Game Link Cable to provide multiplayer modes for several of the games.

Development lasted six months and was led by Minoru Toyota. Challenges during the process included converting the visuals to a screen size different from the original arcades'' hardware and reducing the game''s file size enough to implement single-cartridge multiplayer. Plug and play versions were released later in 2004 and 2006.', 'https://en.wikipedia.org/wiki/Konami_Collector%27s_Series:_Arcade_Advanced'),
  ('Q7487406', 'Shaman King: Legacy of the Spirits, Soaring Hawk and Shaman King: Legacy of the Spirits, Sprinting Wolf are role-playing video games based on the Shaman King manga and anime series. The games were released for the Game Boy Advance by Konami on February 8, 2005. Both Soaring Hawk and Sprinting Wolf feature the same story, gameplay, characters and locations. The difference is that each has its own set of spirits so to recruit all spirits the player has to trade them via Game Link Cable between the games.', 'https://en.wikipedia.org/wiki/Shaman_King:_Legacy_of_the_Spirits'),
  ('Q7487407', 'Shaman King: Legacy of the Spirits, Soaring Hawk and Shaman King: Legacy of the Spirits, Sprinting Wolf are role-playing video games based on the Shaman King manga and anime series. The games were released for the Game Boy Advance by Konami on February 8, 2005. Both Soaring Hawk and Sprinting Wolf feature the same story, gameplay, characters and locations. The difference is that each has its own set of spirits so to recruit all spirits the player has to trade them via Game Link Cable between the games.', 'https://en.wikipedia.org/wiki/Shaman_King:_Legacy_of_the_Spirits'),
  ('Q7487409', 'Shaman King: Master of Spirits 2 is the sequel to the Game Boy Advance game Shaman King: Master of Spirits that had been released in 2004. Konami decided to make a sequel to this game, released on August 2, 2005, in the United States and Europe.', 'https://en.wikipedia.org/wiki/Shaman_King:_Master_of_Spirits_2'),
  ('Q5654167', 'Sega Smash Pack (Sega Archives from USA in Japan) is a series of video game compilations developed and published by Sega. Released for Microsoft Windows, Dreamcast, and Game Boy Advance between 1999 and 2002, the collections primarily feature games originally released for the Sega Genesis.', 'https://en.wikipedia.org/wiki/Sega_Smash_Pack'),
  ('Q5985324', 'Ice Nine is a first-person shooter video game for the Game Boy Advance. It was one of the final first-person shooters on the console. It was originally going to be a tie-in with the film The Recruit. However, this fell through, but the plot remains unchanged. There was also a planned PlayStation 2 version, but it was canceled at some point in development.', 'https://en.wikipedia.org/wiki/Ice_Nine_(video_game)'),
  ('Q6470527', 'Lady Sia is a platformer with action-adventure elements made by RFX Interactive for the Game Boy Advance. It was published by TDK Mediactive, released in the USA on October 15, 2001, and released in Europe on October 19, 2001. Lady Sia is one of the few original games produced by RFX Interactive. The game takes place in a fantasy world where the player assumes the role of the She-Ra/Xena-esque warrior princess, Lady Sia. It is her task to defeat the T''soas, a race of creatures created by the evil warlock Onimen who has declared war on the other realms. Her quest leads her through four different realms, the last one being the home continent of the T''soas themselves. A sequel was planned for the GameCube and GBA in 2003 but was cancelled due to TDK Mediactive being purchased by Take-Two Interactive that same year.', 'https://en.wikipedia.org/wiki/Lady_Sia'),
  ('Q6518566', 'Lego Knights'' Kingdom is an action-adventure video game based on the Lego toy brand. It was developed by Razorback Developments and published in October 2004 by THQ for the Game Boy Advance handheld system. It was the second game based on the Knights'' Kingdom theme, after Lego Creator: Knights'' Kingdom. However, that game was based on the first version of Knights'' Kingdom, while the GBA game is based on the second version.', 'https://en.wikipedia.org/wiki/Lego_Knights%27_Kingdom'),
  ('Q7028539', 'Nicktoons: Freeze Frame Frenzy (also known as SpongeBob SquarePants and Friends in Freeze Frame Frenzy in PAL regions) is a video game for the Game Boy Advance based on various Nicktoons. The game was released for the Game Boy Advance in 2004. The gameplay is similar to that of Gekibo: Gekisha Boy, a PC Engine game about a photographer with cartoony graphics. A prototype of the cancelled PlayStation 2 version of the game, under the working title Nicktoons: Snap Shot, was discovered in 2021.', 'https://en.wikipedia.org/wiki/Nicktoons:_Freeze_Frame_Frenzy'),
  ('Q5956754', 'Justice League Heroes: The Flash is a 2006 beat ''em up video game developed by Wayforward Technologies and published by Warner Bros. Interactive for the Game Boy Advance (GBA). A spinoff of the console video game Justice League Heroes, the game features the Flash, who must work with the Justice League to defeat an alliance of supervillains. The gameplay incorporates the Flash''s speed-based powers, including the ability to slow down time.

The game received mixed reviews upon release. Critics highlighted the speed-based mechanics, vibrant visuals, and challenging boss battles, though some found it lacking in depth or lasting appeal, particularly due to a reliance on basic attacks outside of the Flash''s powers.', 'https://en.wikipedia.org/wiki/Justice_League_Heroes:_The_Flash'),
  ('Q5910242', 'Hot Potato is a puzzle video game developed by Pukka Games and published by BAM! Entertainment for the Game Boy Advance. It was released in North America on June 28, 2001, and in the United Kingdom on November 2, 2001.

In the game, the player must simultaneously drive a bus and clear roads of alien potato beings. The beings are scattered across the street, and by shooting out rows of alien potatoes, they can be cleared from the player''s path. The player must clear a set number of aliens to proceed in the game. Hot Potato received mostly above average reviews from critics.', 'https://en.wikipedia.org/wiki/Hot_Potato_(video_game)'),
  ('Q7637916', 'Summon Night: Swordcraft Story 2 is a 2004 action role-playing game developed by Flight-Plan for the Game Boy Advance. It is part of the Summon Night series of games, and is the sequel to Summon Night: Swordcraft Story. The game was first released in Japan by Banpresto in August 2004, and in North America by Atlus in October 2006. The game received generally favorable reviews. It was followed by Summon Night Swordcraft Story 3: Stone of Beginnings, released in December 2005.', 'https://en.wikipedia.org/wiki/Summon_Night:_Swordcraft_Story_2'),
  ('Q7637922', 'Summon Night Swordcraft Story 3: Stone of Beginnings is an action role-playing game developed by Flight-Plan for the Game Boy Advance. It is part of the Summon Night series of games and the sequel to Summon Night: Swordcraft Story 2. Unlike the previous two games, Stone of Beginnings was not released outside of Japan. It was released in Japan on December 8, 2005.', 'https://en.wikipedia.org/wiki/Summon_Night_Swordcraft_Story_3:_Stone_of_Beginnings'),
  ('Q7642255', 'Super Chinese is a series of action role-playing games for the arcade and various Nintendo systems. The plot of several of the games follow two young boys, Jack and Ryu, as they adventure through their home, Chinaland.

Each of the games in the series were developed by Culture Brain, the earlier games developed by Nihon Game, a name the company used before Culture Brain. The games that were released in North America were retitled, such as Super Chinese, which became Kung Fu Heroes. Many of the games were not released outside Japan.', 'https://en.wikipedia.org/wiki/Super_Chinese'),
  ('Q5750391', 'Hi Hi Puffy AmiYumi is an American animated comedy television series created by Sam Register for Cartoon Network. It follows the adventures of rock stars Ami Onuki (Janice Kawaye) and Yumi Yoshimura (Grey DeLisle), who are fictionalized versions of the Japanese pop rock duo Puffy. The duo tour internationally with their greedy manager Kaz Harada (Keone Young) and their pet cats, Jang-Keng (DeLisle) and Tekirai (Kawaye). It was produced by Renegade Animation and Cartoon Network Studios.

The series premiered on November 19, 2004, and ended on June 27, 2006, with a total of three seasons and 39 episodes. During its short-lived run, the series was nominated for an Annie Award three times. Merchandise based on the series has also been produced, such as video games, home media releases, toys, and clothing.', 'https://en.wikipedia.org/wiki/Hi_Hi_Puffy_AmiYumi'),
  ('Q7093915', 'Onimusha Tactics is a 2003 tactical role-playing game developed and published by Capcom for the Game Boy Advance. A spin-off of the Onimusha series, it was the first game in the series to be released for a Nintendo system. It does not follow the storyline of the previous PlayStation 2 games and is considered a side story, but it features a similar plot: a samurai who possesses the Oni Gauntlet can become the Onimusha and fights against Nobunaga and his army of genma.', 'https://en.wikipedia.org/wiki/Onimusha_Tactics'),
  ('Q7642148', 'Super Army War is a 2005 video game developed by French company Neko Entertainment for the Game Boy Advance. It was released in Europe under the title Glory Days: The Essence of War.', 'https://en.wikipedia.org/wiki/Super_Army_War'),
  ('Q7699288', 'Ten Pin Alley 2 is a ten-pin bowling simulation video game by American studio Pronto Games, published by XS Games and released on the Game Boy Advance platform and later for the Wii. It is the sequel to the game Ten Pin Alley, but was not developed or published by the same company.', 'https://en.wikipedia.org/wiki/Ten_Pin_Alley_2'),
  ('Q7547922', 'Snood is a puzzle video game programmed by Dave Dobson. Snood was released for Mac OS in 1996 as shareware, then for MS-DOS and Microsoft Windows in 1999. An adaptation for Game Boy Advance was developed by Rebellion Developments and released by Destination Software in 2001, and an iOS version was developed by Iron Galaxy and released by EA Mobile on May 8, 2009. Dobson founded Snood, LLC to sell the game.

As in Puzzle Bobble, connecting three or more identical Snoods makes them disappear from the board. When the board is cleared, the level advances. If the Snoods reach the bottom of the screen, a life is lost. There is no time limit in most game modes.', 'https://en.wikipedia.org/wiki/Snood_(video_game)'),
  ('Q7487408', 'Shaman King: Master of Spirits is a Metroidvania video game developed by Konami Computer Entertainment Japan and published by Konami. This is the first Shaman King game that was developed for the Game Boy Advance in America. It was developed to accompany the English dub by 4kids Entertainment.', 'https://en.wikipedia.org/wiki/Shaman_King:_Master_of_Spirits'),
  ('Q7378612', 'Rugrats: Castle Capers is a single-player platform game developed by Software Creations and published by THQ and was released only for the Game Boy Advance, based on the Rugrats cartoon series. The story revolves around the Rugrats, who must retrieve their toys from Angelica after she steals them, imagining herself to be queen of a newly constructed playground set. Gameplay is very similar to the gameplay of Rugrats: Royal Ransom and shares the same plot, released a year later. The game was re-released in 2026 as part of the Rugrats: Retro Rewind Collection compilation.', 'https://en.wikipedia.org/wiki/Rugrats:_Castle_Capers'),
  ('Q7378613', 'Rugrats: I Gotta Go Party is a 2002 Game Boy Advance game based on the Rugrats series, developed by Eurocom Entertainment Software and published by THQ. It was also released on a triple pack cartridge with Tak and the Power of Juju and SpongeBob SquarePants: SuperSponge in 2005.', 'https://en.wikipedia.org/wiki/Rugrats:_I_Gotta_Go_Party'),
  ('Q7643850', 'Superman Returns is a 2006 open world action video game based on the 2006 movie of the same name. It was developed by EA Tiburon and co-published by Electronic Arts and Warner Bros. Interactive Entertainment in conjunction with DC Comics. It was released for PlayStation 2, Xbox, Xbox 360, and Nintendo DS.

In the game, Superman combats Bizarro, as well as other classic villains (including Metallo, Mongul, and Riot) as well as being able to play as Bizarro in one of the minigames. The game features the voice and likeness of Brandon Routh (Superman / Clark Kent) as well as the voices of Kevin Spacey (Lex Luthor), Kate Bosworth (Lois Lane), Parker Posey (Kitty Kowalski) and Sam Huntington (Jimmy Olsen), all reprising their roles from the film.', 'https://en.wikipedia.org/wiki/Superman_Returns_(video_game)'),
  ('Q5681309', 'Hatena Satena is a Game Boy Advance puzzle video game by Japanese developer Hudson Soft with design elements by Framegraphics of Japan in courtesy of Super Lovers. The gameplay can be described as a mix of nonogram puzzles and Minesweeper, whereas the design is similar to that of Super Milk Chan.', 'https://en.wikipedia.org/wiki/Hatena_Satena'),
  ('Q7355500', 'Rockman EXE 4.5 Real Operation is a 2004 tactical role-playing game developed by Capcom for the Game Boy Advance (GBA) handheld game console. It is a spin-off title in the Mega Man Battle Network sub-series of Mega Man video games. The game was released in Japan on August 6, 2004, but was not localized or released in other territories.', 'https://en.wikipedia.org/wiki/Rockman_EXE_4.5_Real_Operation'),
  ('Q7403165', 'Sakura Momoko no Ukiuki Carnival is a 2002 role-playing video game developed by Nintendo and indieszero and published by Nintendo for the Game Boy Advance. The game was never released outside Japan.

The game is billed as an "internet simulation game" where the player ventures between the game''s "real-life" town and internet. The game was originally planned for the Game Boy Color, but was switched to the Game Boy Advance.

The game''s characters were designed by manga artist Momoko Sakura, best known for writing Chibi Maruko-chan. Her sister, Noriko Miura, designed the basis for the game and contributed to its script, while Shigeru Miyamoto, Takashi Tezuka, and Satoru Iwata also contributed to the game''s development as producers or advisors.', 'https://en.wikipedia.org/wiki/Sakura_Momoko_no_Ukiuki_Carnival'),
  ('Q632632', 'Scurge: Hive is an action-adventure video game by Orbital Media released for the Game Boy Advance and Nintendo DS in 2006. The game follows the protagonist Jenosa Arma, a bounty huntress tasked with hunting a parasitic lifeform called the "Scurge" an alien entity capable of rapidly adapting to and infecting biological, mechanical, and digital systems, including the player. Throughout the game, Jenosa Arma will have to battle various forms of the Scurge virus and race against the clock as the parasite slowly takes over Jenosa''s body. The gameplay takes place in an isometric perspective.

In 2025, ahead of the game''s twentieth anniversary, it was announced Scurge would be ported to eighth and ninth-generation consoles and Microsoft Windows within that year, with additional features.', 'https://en.wikipedia.org/wiki/Scurge:_Hive'),
  ('Q6952681', 'NBA Jam 2002 is a sports Game Boy Advance game made by Acclaim Entertainment as a licensed basketball simulation for the 2002-2003 NBA season. It was the follow-up to NBA Jam 2001 and was the last game in the NBA Jam series to mention a year in its title. The game was originally set for release in late November 2001 before being delayed to February 2002.

There were 29 NBA teams to play as with more than 140 players in all.', 'https://en.wikipedia.org/wiki/NBA_Jam_2002'),
  ('Q6581169', 'The Lord of the Rings: The Third Age is a turn-based tactics game for the Game Boy Advance. It was released in 2004 by Electronic Arts and is the handheld version of a role-playing video game of the same name released for GameCube, PlayStation 2 and Xbox.', 'https://en.wikipedia.org/wiki/The_Lord_of_the_Rings:_The_Third_Age_(GBA_video_game)'),
  ('Q625317', 'Jurassic Park III: The DNA Factor is a side scrolling and puzzle game set in the Jurassic Park movie universe. It was developed by Konami Computer Entertainment Hawaii and published by Konami for the Game Boy Advance. It was coincided with the release of the film Jurassic Park III on July 17, 2001.

The two other games, Jurassic Park III: Park Builder and Jurassic Park III: Island Attack, are also released by Konami.', 'https://en.wikipedia.org/wiki/Jurassic_Park_III:_The_DNA_Factor'),
  ('Q7038903', 'Ninja Five-O, known in the PAL region as Ninja Cop, is a 2003 action-platform video game developed by Hudson Soft and published by Konami. It was released for the Game Boy Advance in North America and Europe in April 2003. Players take the role of Joe Osugi, a ninja who must stop a terrorist group influenced by mystical masks. It was first announced at "Konami Gamers'' Day" in early 2003.

The game received generally positive reviews from video game critics, but it failed to garner sales and is often regarded as one of the most sought-after handheld games.

The original version was re-released on February 25, 2025, for Windows, Nintendo Switch, PlayStation 4 and PlayStation 5.', 'https://en.wikipedia.org/wiki/Ninja_Five-O'),
  ('Q7044930', 'No Rules: Get Phat is a 2001 action video game developed by Flying Tiger Development and published by TDK Mediactive for the Game Boy Advance. It is a licensed video game based on the No Rules line of clothing. Upon release, Get Phat received mixed reviews.', 'https://en.wikipedia.org/wiki/No_Rules:_Get_Phat'),
  ('Q622386', 'Konami Krazy Racers is a 2001 kart racing game developed and published by Konami for the Game Boy Advance. Released as a launch title for the system, Konami Krazy Racers uses a variety of characters and concepts from multiple different Konami franchises, including Castlevania, Metal Gear, and Gradius. It plays similarly to the Mario Kart series, with eight characters per circuit and offensive/defensive items placed at predetermined points in the tracks.

Konami Krazy Racers received positive reviews upon release. It was later released through the Virtual Console for the Wii U in 2015.', 'https://en.wikipedia.org/wiki/Konami_Krazy_Racers'),
  ('Q7396363', 'Sabre Wulf is a 2004 video game by Rare for the Game Boy Advance. The player controls the safari adventurer Sabreman, who runs and jumps between platforms to retrieve treasure guarded by the Sabre Wulf. The game is a remake of the 1984 action-adventure Sabre Wulf. Though the remake''s reviews were generally favourable, sales were lackluster. Reviewers noted the game''s simplicity and shallow puzzles. While some found it fun and praised its character animations, reviewers considered its gameplay repetitive.', 'https://en.wikipedia.org/wiki/Sabre_Wulf_(2004_video_game)'),
  ('Q6432477', 'Koro Koro Puzzle Happy Panechu! is a puzzle video game developed by Nintendo R&D2 and Mobile21 and published by Nintendo for the Game Boy Advance. It was released only in Japan on March 8, 2002. It is the first Game Boy Advance title to use a tilt-sensor chip.', 'https://en.wikipedia.org/wiki/Koro_Koro_Puzzle_Happy_Panechu!'),
  ('Q6471856', 'The following is a list of video games developed and published by Konami, based on Kazuki Takahashi''s Yu-Gi-Oh! manga and anime franchise, along with its spin-off series. With some exceptions, the majority of the games follow the card battle gameplay of the real-life Yu-Gi-Oh! Trading Card Game. There are 59 in total.

Platforms: Game Boy, Game Boy Color, Game Boy Advance, GameCube, Mobile, Nintendo DS, Nintendo 3DS, Nintendo Switch, PC, PlayStation, PlayStation 2, PlayStation 3, PlayStation 4, PlayStation 5, PSP, Wii, Xbox, Xbox 360, Xbox One, Xbox Series X/S.', 'https://en.wikipedia.org/wiki/List_of_Yu-Gi-Oh!_video_games'),
  ('Q7694328', 'Teen Titans is a video game that released for the Game Boy Advance on October 16, 2005. The game is based on the television show Teen Titans. The game was going to be released in Europe shortly after its release in North America, though the European release was later cancelled.', 'https://en.wikipedia.org/wiki/Teen_Titans_(2005_video_game)'),
  ('Q7156698', 'Payback is a video game developed and published by Apex Designs. It was first released in 2001. It was followed by a sequel in 2012, Payback 2.', 'https://en.wikipedia.org/wiki/Payback_(video_game)'),
  ('Q7100014', 'Orbient, known in Japan as Orbital, is a puzzle video game developed by Skip Ltd. and published by Nintendo for the Wii''s WiiWare digital distribution service. It is one of twelve games in the Art Style series of video games available for WiiWare and DSiWare. It is a remake of a Japan-only Game Boy Advance video game titled Orbital, released for the bit Generations series of video games.

The objective of Orbient is to control a white star which grows larger by absorbing blue stars and collecting smaller gray stars to form orbiting satellites.

While the original bit Generations version was met with mixed reactions, the WiiWare version of Orbient was very well-received, holding an average score of 82.3% and 82/100 from GameRankings and Metacritic respectively.', 'https://en.wikipedia.org/wiki/Orbient'),
  ('Q7354209', 'Rock ''Em Sock ''Em Robots is a fighting video game developed by Full Fat and published by Destination Software in 2006 for the Game Boy Advance. The game is based heavily on the 1964 toy of the same name, and involves the player taking control of a brightly coloured plastic robot and engaging in close combat with an opposing robot. The first robot to inflict enough damage to cause his opponent''s head to pop up is declared the winner. The game is notable for garnering significant negative criticism for its gameplay mechanics and inherent lack of difficulty, poor-quality visuals and repetitive ''button-mashing'' gameplay. Chris Adams of gaming website IGN said in his review of the title that ''it is the single worst game I''ve ever played on the Game Boy Advance''.', 'https://en.wikipedia.org/wiki/Rock_%27Em_Sock_%27Em_Robots_(video_game)'),
  ('Q7370567', 'Rotohex (Released in Japan as Dialhex) is a puzzle video game developed by Skip Ltd. and published by Nintendo for the Wii''s WiiWare service. It is a remake of the Japan-only bit Generations title Dialhex. It was released as WiiWare in North America on October 27, 2008.', 'https://en.wikipedia.org/wiki/Rotohex'),
  ('Q7413099', 'Samurai Jack: The Amulet of Time is an action video game developed by British studio Virtucraft and published by BAM! Entertainment (European distribution handled by Acclaim Entertainment) for the Game Boy Advance. Based on the animated series Samurai Jack, the game came about after a licensing agreement deal was reached between Cartoon Network and BAM! Entertainment in January 2002. It was released worldwide on March 25, 2003, and is the first of three official Samurai Jack video games.', 'https://en.wikipedia.org/wiki/Samurai_Jack:_The_Amulet_of_Time'),
  ('Q7206482', 'Pocky & Rocky with Becky is a shoot ''em up video game for the Game Boy Advance handheld game console where the player may control either Pocky, Rocky, or Becky, the latter originating from the spin-off KiKi KaiKai: Dotou-hen, as they attempt to defeat a ghostly hydra who escaped his seal. The player character takes two hits to lose a life, but only one in Japan. While prior entries were developed by Taito, this game was developed and published by Altron in Japan, and published by Natsume Inc. in North America.

The game is mechanically similar to the arcade game KiKi KaiKai. It was later released on the Wii U''s Virtual Console service. It has received mixed reception, with some critics criticizing it for its short length and lack of difficulty, while feeling that shoot ''em up fans would enjoy it.', 'https://en.wikipedia.org/wiki/Pocky_%26_Rocky_with_Becky'),
  ('Q7262647', 'Puyo Pop, known as Minna de Puyo Puyo in Japan, is the first of the Puyo Puyo games made for the Game Boy Advance, and the first produced by Sonic Team. It is the last game to solely use the original Madō Monogatari cast, as later games would introduce many new characters to go alongside them.

The Japanese title refers to the game''s four player mode and became a staple in future games. The Western title is simply named Puyo Pop (a recycled title from the Neo-Geo Pocket version of Puyo Puyo 2).', 'https://en.wikipedia.org/wiki/Puyo_Pop_(video_game)'),
  ('Q7888526', 'Zone of the Enders: The Fist of Mars, known in Japan as Zone of the Enders: 2173 Testament (ZONE OF THE ENDERS 2173 TESTAMENT, Zōn obu Endāzu 2173 Tesutamento), is a tactical role-playing video game developed by Winkysoft and published by Konami in 2001 for the Game Boy Advance. The game is story-orientated, and is based around turn-based strategic mecha combat.', 'https://en.wikipedia.org/wiki/Zone_of_the_Enders:_The_Fist_of_Mars'),
  ('Q843205', 'Kingdom Hearts: Chain of Memories is a 2004 action role-playing game developed by Square Enix and Jupiter and published by Square Enix in collaboration with Disney Interactive for the Game Boy Advance (GBA). The second game in the Kingdom Hearts series, it is a direct sequel to Kingdom Hearts whose ending is set about a year before the events of Kingdom Hearts II. Chain of Memories follows Sora and his friends as they explore Castle Oblivion while battling Organization XIII, a new group of antagonists. The game uses a new card-based battle system rather than its predecessor''s real-time combat system, and it was one of the first GBA games to incorporate full-motion video (FMV).', 'https://en.wikipedia.org/wiki/Kingdom_Hearts:_Chain_of_Memories'),
  ('Q775291', 'SpyHunter is a vehicular combat game released for the PlayStation 2 in 2001. It is a reboot and sequel of the 1983 arcade game of the same name. It was later ported to GameCube, Xbox, Game Boy Advance, Windows, Mac OS X, and Tapwave Zodiac. In the game, the player drives the G-6155 Interceptor, an advanced, weaponized spy vehicle. Unlike the original''s top-down view, the remake is played with a chase camera, similar to a racing game. The PlayStation 2 version received positive reviews while reception for the ports was mixed. A sequel, SpyHunter 2, was released in 2003.', 'https://en.wikipedia.org/wiki/SpyHunter'),
  ('Q7229281', 'Popeye: Rush for Spinach is a Game Boy Advance video game based on the comic strip of same name created by E. C. Segar, licensed from King Features Entertainment. It was developed by French studio Magic Pockets and published by Namco Hometek in 2005, and Atari Europe in 2006.', 'https://en.wikipedia.org/wiki/Popeye:_Rush_for_Spinach'),
  ('Q765425', 'Sonic Advance 3 is a 2004 platform game developed by Sonic Team and Dimps and published by Sega for the Game Boy Advance. It is part of the Sonic the Hedgehog series, the sequel to Sonic Advance 2 (2002) and a follow-up to Sonic Battle (2003). The game stars the characters Sonic, Tails, Knuckles, Amy, and Cream as they seek to keep Doctor Eggman and his robot assistant Gemerl from building empires on each of seven chunks Eggman has divided the Earth into.

The game is a fast-paced 2D platformer that takes place across seven zones, each divided into three acts and a boss fight. It allows one or two players to control any two of the five characters; each one has different abilities that allow players varying access to parts of levels. While the graphics are mainly 2D, the game features some 3D rotation effects. It sold quickly upon release and received positive reviews from critics, who praised its gameplay and aesthetics, though they were more divided on the team-up dynamic. The game was later released for the Wii U''s Virtual Console in Japan in May 2016.', 'https://en.wikipedia.org/wiki/Sonic_Advance_3'),
  ('Q7707743', 'Texas Hold ''Em Poker is a card game video game developed by Skyworks Technologies and published by Majesco for the Game Boy Advance and Nintendo DS. The Game Boy Advance version was also released on a Twin Pack cartridge bundled with Golden Nugget Casino.', 'https://en.wikipedia.org/wiki/Texas_Hold_%27Em_Poker_(video_game)'),
  ('Q7742425', 'The Invincible Iron Man is a 2002 run and gun video game published by Activision and developed by Torus Games for the Game Boy Advance. The game, played from a side-scrolling perspective, is based on the Marvel Comics superhero Iron Man, and is the character''s first appearance on a handheld game console. Within the game''s narrative, Iron Man must traverse through a series of levels and recover one of his stolen suits of armor while battling supervillains such as the Blizzard and Crimson Dynamo.

The Invincible Iron Man received mixed reviews from critics, who compared the gameplay to the Mega Man series. While they praised the visuals and generally found the gameplay to be solid, they faulted the game''s lack of variety and length, and held middling opinions toward the audio.', 'https://en.wikipedia.org/wiki/The_Invincible_Iron_Man_(video_game)'),
  ('Q7716260', 'The Adventures of Maya the Bee (German: Die Biene Maja und ihre Abenteuer) is a children''s book by the German writer Waldemar Bonsels published in 1912. The stories revolve around a little bee named Maya and her friends among bees, other insects and other creatures. The book depicts Maya''s development from an adventurous youngster to a responsible adult member of bee society.

The book has been published in many other languages and adapted into different media. Bonsels wrote a sequel, Heaven Folk, which was published in 1915.', 'https://en.wikipedia.org/wiki/The_Adventures_of_Maya_the_Bee'),
  ('Q7722305', 'The Cheetah Girls is a Disney Channel media franchise based on the novel series of the same name by Deborah Gregory, who was also co-producer of the first three films. The films are about a female vocal group seeking success and fortune.', 'https://en.wikipedia.org/wiki/The_Cheetah_Girls_(franchise)'),
  ('Q755186', 'Doom II, also known as Doom II: Hell on Earth, is a 1994 first-person shooter video game developed and published by id Software for MS-DOS. It was released on Mac OS the following year. Whereas the original Doom was initially only available through shareware and mail order, Doom II was the first Doom game released initially in stores.

Doom II features larger levels, new enemies, a new Super Shotgun weapon, and a new power-up. Master Levels for Doom II, an expansion pack with 21 new levels, was released on December 26, 1995. Another expansion, No Rest for the Living, which adds nine extra levels, was developed for the release of the game on Xbox Live Arcade and is also included in the Doom 3: BFG Edition, as part of Doom Classic Complete, and as a free add-on for the 2019 Unity engine port of Doom II. It was also included in the 2024 KEX Engine port.', 'https://en.wikipedia.org/wiki/Doom_II'),
  ('Q2068675', 'Mario Kart: Super Circuit is a 2001 kart racing game for the Game Boy Advance (GBA). It is the third Mario Kart game and retains its predecessors'' gameplay: as a Mario franchise character, the player races opponents around tracks based on locales from the Super Mario platform games. Tracks contain obstacles and power-ups that respectively hamper and aid the player''s progress. Super Circuit includes various single-player and multiplayer game modes, including a Grand Prix racing mode and a last man standing battle mode.

Super Circuit was developed by Intelligent Systems and published by Nintendo. It was the first handheld Mario Kart game and the only game in the series developed by Intelligent Systems. Its graphical style changed drastically from early demos, with the final release resembling Super Mario Kart (1992) visually. Nintendo revealed Super Circuit alongside the GBA in 2000 and released it in mid-2001, months after the console''s launch.', 'https://en.wikipedia.org/wiki/Mario_Kart:_Super_Circuit'),
  ('Q7757155', 'The Pinball of the Dead is a pinball video game developed by Sega''s Wow Entertainment division and published by Sega. It was released for the Game Boy Advance in 2002 and 2003. Based on Sega''s The House of the Dead series of light gun games, particularly The House of the Dead and The House of the Dead 2, the game contains three tables and includes a "Challenge" mode. Full-motion video sequences and audio samples from previous games were also added. The game was first announced during the 2001 Nintendo Space World. Composer Hitoshi Sakimoto was involved with making the game''s music.

The Pinball of the Dead received generally positive reviews from video game critics, receiving an Editor''s Choice award on GameZone. Critics praised the graphics and sound while its gameplay physics was more mixed. It also received several comparisons to other pinball games like Devil''s Crush. In 2005, the game was later called one of the best games of all time from gaming magazine Nintendo Power.', 'https://en.wikipedia.org/wiki/The_Pinball_of_the_Dead'),
  ('Q761957', 'Crash Bandicoot: The Huge Adventure (released as Crash Bandicoot XS in Europe) is a 2002 platform game developed by Vicarious Visions and published by Universal Interactive for the Game Boy Advance. It is the seventh installment in the Crash Bandicoot video game series, the first Crash Bandicoot game not to be released on a PlayStation console, and the first Crash Bandicoot game to be released on a handheld console. The game''s story centers on a plot to shrink the Earth by the main antagonist, Doctor Neo Cortex, through the use of a gigantic weapon named the "Planetary Minimizer". The protagonist of the story, Crash Bandicoot, must gather Crystals to power a device that will return the Earth to its proper size, defeating Cortex and his minions along the way.', 'https://en.wikipedia.org/wiki/Crash_Bandicoot:_The_Huge_Adventure'),
  ('Q645003', 'Phoenix Wright: Ace Attorney – Justice for All is a visual novel adventure video game developed and published by Capcom. It was originally released for the Game Boy Advance in 2002 in Japan, and has since been released on multiple platforms. The Nintendo DS version, initially released in 2006 in Japan, was released in English in the West in 2007. The game is the second entry in the Ace Attorney series, following Phoenix Wright: Ace Attorney.

The story follows Phoenix Wright, a defense attorney who defends his clients in four episodes. Among other characters are his investigative partner and spirit medium Maya Fey, her cousin Pearl, and the rival prosecutor Franziska von Karma. The game is divided into two types of sections: courtroom sessions, where the player cross-examines witnesses and tries to uncover contradictions in their testimonies; and investigations, where the player gathers evidence and talks to witnesses.', 'https://en.wikipedia.org/wiki/Phoenix_Wright:_Ace_Attorney_%E2%80%93_Justice_for_All'),
  ('Q7842368', 'Tringo is a 2006 puzzle video game developed by Kermitt Quick and Nathan Keir. Tringo was originally written as a game event in Second Life, the ''virtual world'' created by Linden Lab that allows users to creative extensive custom content which they continue to own the rights to. It was released on April 11, 2006.', 'https://en.wikipedia.org/wiki/Tringo'),
  ('Q7758623', 'The Proud Family is an American animated sitcom created by Bruce W. Smith that premiered on Disney Channel from September 15, 2001, to August 19, 2005. The series centers on the life of the titular family, including the show''s main protagonist, Penny Proud, a 14-year-old African-American teenage girl who navigates her adolescence while dealing with her friends and family. Episodes deal with Penny discovering her boundaries and struggling with family relationships and peer pressure. Penny has strong relationships with her entrepreneurial father Oscar Proud and her veterinarian mother Trudy Proud, as well as her friends Dijonay Jones, LaCienega Boulevardez, Zoey Howzer, and Sticky Webb.', 'https://en.wikipedia.org/wiki/The_Proud_Family'),
  ('Q7897212', 'Uno Free Fall is a 2006 puzzle game released on the Game Boy Advance and mobile phone based on the card game Uno. It is also included on the Nintendo DS 3-in-1 game, Uno / Skip-Bo / Uno Freefall. It was released in the PAL Region on March 2, 2007. It was released in North America on March 6, 2007.', 'https://en.wikipedia.org/wiki/Uno_Free_Fall'),
  ('Q7900078', 'Urban Yeti! is an action video game developed by Cave + Barn Studios and published by Telegames for the Game Boy Advance. It was released in North America on August 16, 2002.', 'https://en.wikipedia.org/wiki/Urban_Yeti!'),
  ('Q7959063', 'Wade Hixton''s Counter Punch is a boxing video game developed by Inferno Games and Engine Software and published by Destination Software. It was released for the Game Boy Advance on March 16, 2004 in North America, and on October 1, 2004 in Europe.', 'https://en.wikipedia.org/wiki/Wade_Hixton%27s_Counter_Punch'),
  ('Q7296346', 'Rave Master, Rave, and alternatively, The Groove Adventure Rave in Japan, is a Japanese manga series written and illustrated by Hiro Mashima. The series follows Haru Glory, a teenager on a quest to find the five fragments of Rave, the sacred stone of light, to bring peace to the world by defeating the criminal group Demon Card. Mashima created this series with the idea of travelling around the world and was presented with difficulties in its serialization due to its considerable length.

The manga was serialized in Kodansha''s Weekly Shōnen Magazine from July 1999 to July 2005, with its chapters collected in 35 tankōbon volumes. The manga series was licensed for an English release in North America by Tokyopop until Kodansha allowed their contract to expire. It was also adapted into a 51-episode anime television series by Studio Deen, which was broadcast on TBS from October 2001 to September 2002. Tokyopop also licensed the anime adaptation, which was broadcast in the United States on Cartoon Network from June 2004 to July 2005.', 'https://en.wikipedia.org/wiki/Rave_Master'),
  ('Q721710', 'Phoenix Wright: Ace Attorney – Trials and Tribulations is a visual novel adventure video game developed and published by Capcom. It was originally released for the Game Boy Advance in 2004 in Japan, and has since been released for several platforms, including a Nintendo DS version that was released in 2007 in Japan and North America and in 2008 in Europe. It is the third game in the Ace Attorney series, following Phoenix Wright: Ace Attorney (2001) and Justice for All (2002).

The story follows defense attorneys Phoenix Wright and Mia Fey, who defend their clients in five episodes. Among other characters are Phoenix''s assistant and Mia''s sister Maya, her cousin Pearl, and prosecutor Godot. The gameplay is split into courtroom sections, where the player cross-examines witnesses and tries to discover contradictions in their testimonies, and investigations, where they gather evidence and talk to witnesses.', 'https://en.wikipedia.org/wiki/Phoenix_Wright:_Ace_Attorney_%E2%80%93_Trials_and_Tribulations'),
  ('Q7236402', 'Power Rangers S.P.D. is a side-scrolling beat-em-up video game developed by Natsume Co., Ltd. and published by THQ for the Game Boy Advance on September 6, 2005. It was the sixth Power Rangers video game to be published by THQ.', 'https://en.wikipedia.org/wiki/Power_Rangers_S.P.D._(video_game)'),
  ('Q7828239', 'Totally Spies! is a French animated spy fiction television series created by Vincent Chalvon-Demersay and David Michel mainly produced by French company Zodiak Kids & Family France, with seasons three to five being co-produced with Canadian company Image Entertainment Corporation. It focuses on three teenage girls from Beverly Hills, California, who work as undercover agents for the World Organization of Human Protection (WOOHP).

Prior to its debut in France on April 3, 2002, on TF1''s TFOU block, the series was first shown in the United States on November 3, 2001, on ABC Family before moving to Cartoon Network, and later to Universal Kids for the sixth season. It premiered in Canada on Teletoon on September 2, 2002, for the English version, and on Télétoon for the French version. During its original run, the show spanned five seasons, with 130 episodes and several specials. A sixth season was released in 2013 on the same block TFOU. In 2017, Totally Spies began airing on Gulli. Following a ten-year hiatus, a seventh season premiered in France via Gulli on May 12, 2024, and internationally through both Cartoon Network and Discovery Kids on January 4, 2025; the series is renewed for an eighth season.', 'https://en.wikipedia.org/wiki/Totally_Spies!'),
  ('Q7279681', 'Racing Gears Advance is a combat racing game for the Game Boy Advance system released in 2004 and includes licensed vehicles from GM, Dodge, Mitsubishi and Lotus Cars.

The soundtrack is notable for having been composed by Neil Voss, known for his prior work on Tetrisphere and The New Tetris.

All circuit cups (there are five total) take the name of letters from the Greek alphabet (Alpha, Gamma, Delta, Epsilon, Omega), with each cup having five tracks (25 tracks total).

Characters such as Spacewave, Jack Speed, Throttle, etc., drive the following cars:

Cadillac Cien

Chevrolet Corvette

Chevrolet SSR', 'https://en.wikipedia.org/wiki/Racing_Gears_Advance'),
  ('Q663809', 'Jurassic Park III: Park Builder is a 2001 construction and management simulation game developed and published by Konami for the Game Boy Advance.

It is the second game in the Jurassic Park III series of titles for the Game Boy Advance after The DNA Factor, and is followed by Island Attack.', 'https://en.wikipedia.org/wiki/Jurassic_Park_III:_Park_Builder'),
  ('Q7353400', 'Robotech: The Macross Saga is a side-scrolling shoot ''em up for the Game Boy Advance handheld system, developed by Lucky Chicken Games and published by TDK Mediactive. This title was released during a renaissance of Robotech video games, where struggling projects were no longer cancelled and actually made it to market. A remake was published in 2021, Robotech: The Macross Saga HD Edition.', 'https://en.wikipedia.org/wiki/Robotech:_The_Macross_Saga'),
  ('Q648099', 'Grand Theft Auto Advance (also marketed as Grand Theft Auto) is a 2004 action-adventure game developed by Digital Eclipse and published by Rockstar Games. The eighth entry in the Grand Theft Auto series, it was released for the Game Boy Advance in October 2004. The game takes place in Liberty City (a fictional parody of New York City), the same setting used for Grand Theft Auto III, to which it serves as a prequel. Set one year before Grand Theft Auto III''s events, the story follows criminal Mike''s quest for revenge after his partner''s supposed death, which leads him to become entangled in a world of organised crime, gang warfare, and corruption.', 'https://en.wikipedia.org/wiki/Grand_Theft_Auto_Advance'),
  ('Q7298499', 'Rayman Raving Rabbids (French: Rayman contre les Lapins Crétins) is a 2006 platform game developed and published by Ubisoft for the Game Boy Advance and Nintendo DS. It was the handheld version of the party video game Rayman Raving Rabbids.', 'https://en.wikipedia.org/wiki/Rayman_Raving_Rabbids_(handheld_game)'),
  ('Q7581687', 'Spy Muppets: License to Croak is a 2003 action game, based on The Muppets franchise, developed by Vicarious Visions and published by TDK Mediactive for Microsoft Windows and Game Boy Advance. It is a spoof of the James Bond films, the title being a reference to Licence to Kill. The player controls Kermit the Frog through several stages in order to stop the bad guys.

The game was released to mostly mixed reviews, with criticism generally aimed at the game''s short length.', 'https://en.wikipedia.org/wiki/Spy_Muppets:_License_to_Croak'),
  ('Q839015', 'Super Robot Taisen: Original Generation is a tactical role-playing game for the Game Boy Advance. It was developed by Banpresoft and published by Banpresto in Japan, Atlus in North America, and 505 Games in Europe.

The game was originally released in Japan on November 22, 2002, and stars various original characters created by Banpresto for their Super Robot Wars series. Like the much earlier Super Robot Wars Gaiden, the game features no licensed mecha or characters at all - instead, it uses only Banpresto''s own creations, in an original story. The games sold well in Japan, and later adapted for a short animated OVA called Super Robot Wars Original Generation: The Animation, which takes place after the second game in the series. A television series, Super Robot Wars Original Generation: Divine Wars, retells the story of the first game. Original Generation was released in the United States on August 8, 2006. It is the first game in the Super Robot Wars series to ever be commercially released overseas, since, unlike the rest of the series, it contains no characters from other media, therefore, no legal entanglements were involved in a foreign release.', 'https://en.wikipedia.org/wiki/Super_Robot_Taisen:_Original_Generation'),
  ('Q953229', 'Advance Wars is a turn-based strategy video game developed by Intelligent Systems and published by Nintendo for the Game Boy Advance. It is the seventh title in the Wars series of video games, and the first in the Advance Wars sub-series. The game takes place on a fictional continent, where two nations, Orange Star and Blue Moon, have been fighting each other for years. The conflict enters a new stage when an Orange Star commanding officer named Andy is accused of attacking the armies of two other nations, Yellow Comet and Green Earth, without reason, resulting in a worldwide war.

As with previous Wars titles, Advance Wars was not originally intended for release outside Japan, due to Nintendo feeling that Western consumers would not be interested in turn-based games because of their complex mechanics. In order to alleviate this, the developers made the mechanics easy to understand, adding in an in-depth tutorial that did not require players to read the manual. Designer Kentaro Nishimura commented that the game''s success shifted Nintendo''s attitude over Western tastes, and that same success is frequently credited as a driving force for Nintendo bringing another Intelligent Systems franchise, Fire Emblem, outside of Japan beginning with the seventh installment.', 'https://en.wikipedia.org/wiki/Advance_Wars'),
  ('Q7769738', 'The Tower SP is a 2005 construction and management simulation video game developed by Vivarium and published by Nintendo for the Game Boy Advance. It was released in March 2005 in Japan and April the same year by Sega in North America. It is a port and revision of SimTower (1994), which Vivarium''s predecessor OPeNBook developed, with some elements of its sequel Yoot Tower (1998). In the game, the player is tasked to construct a tower for their company boss, Yama.', 'https://en.wikipedia.org/wiki/The_Tower_SP'),
  ('Q7813931', 'Tokyo Majin Gakuen: Fuju Hōroku is the second video game (excluding the fan disc for the first game) in the Tokyo Majin Gakuen franchise, and an entry in said franchise''s Hito no Shō setting. It was originally released on October 12, 2000, on the WonderSwan, and later ported to Game Boy Advance. Like most entries in the franchise, it has never been released outside Japan.', 'https://en.wikipedia.org/wiki/Tokyo_Majin_Gakuen:_Fuju_H%C5%8Droku'),
  ('Q868057', 'Klonoa: Empire of Dreams is a 2001 puzzle-platform game published by Namco for the Game Boy Advance. Falling somewhere between Klonoa: Door to Phantomile and Klonoa 2: Lunatea''s Veil, Empire of Dreams takes place in the new realm in the Klonoa series, the Empire of Jillius.', 'https://en.wikipedia.org/wiki/Klonoa:_Empire_of_Dreams'),
  ('Q7828238', 'Totally Spies! is a French animated spy fiction television series created by Vincent Chalvon-Demersay and David Michel mainly produced by French company Zodiak Kids & Family France, with seasons three to five being co-produced with Canadian company Image Entertainment Corporation. It focuses on three teenage girls from Beverly Hills, California, who work as undercover agents for the World Organization of Human Protection (WOOHP).

Prior to its debut in France on April 3, 2002, on TF1''s TFOU block, the series was first shown in the United States on November 3, 2001, on ABC Family before moving to Cartoon Network, and later to Universal Kids for the sixth season. It premiered in Canada on Teletoon on September 2, 2002, for the English version, and on Télétoon for the French version. During its original run, the show spanned five seasons, with 130 episodes and several specials. A sixth season was released in 2013 on the same block TFOU. In 2017, Totally Spies began airing on Gulli. Following a ten-year hiatus, a seventh season premiered in France via Gulli on May 12, 2024, and internationally through both Cartoon Network and Discovery Kids on January 4, 2025; the series is renewed for an eighth season.', 'https://en.wikipedia.org/wiki/Totally_Spies!'),
  ('Q751268', 'Astro Boy: Omega Factor is a beat ''em up video game developed by Treasure and Hitmaker, and published by Sega (THQ in Europe). The game was released for the Game Boy Advance on December 18, 2003, in Japan; August 17, 2004, in North America; and February 18, 2005, in Europe. The game is based on Osamu Tezuka''s manga and anime franchise Astro Boy. However, it also features characters and plotlines from the artist''s entire canon of work.

While Astro Boy had been well known for decades in Japan, the North American release was delayed to coincide with the premiere of the Astro Boy TV series in 2004. During this delay, Treasure made some game improvements to the North American version of the game. The game received positive reviews from critics, with strong praise focused on the game''s visuals, and limited criticism on level design. In 2010, the game was included as one of the titles in the book 1001 Video Games You Must Play Before You Die.', 'https://en.wikipedia.org/wiki/Astro_Boy:_Omega_Factor'),
  ('Q806590', 'Banjo-Kazooie: Grunty''s Revenge is a 2003 platform game developed by Rare and published by THQ for the Game Boy Advance (GBA). It is the third installment in the Banjo-Kazooie series and is set between the Nintendo 64 games Banjo-Kazooie (1998) and Banjo-Tooie (2000). In Grunty''s Revenge, the evil witch Gruntilda travels back in time to prevent the events of Banjo-Kazooie from happening, and the bear Banjo and his bird friend Kazooie set out to stop her. Grunty''s Revenge retains the focus on collecting items and most of the other game mechanics from its predecessors, but is presented in 2D rather than 3D. Aside from the main game, players can also access minigames such as fishing and target shooting.', 'https://en.wikipedia.org/wiki/Banjo-Kazooie:_Grunty%27s_Revenge'),
  ('Q863600', 'Metal Slug Advance is a 2004 run and gun video game developed by Noise Factory and published by SNK Playmore for the Game Boy Advance. It is part of the Metal Slug series.', 'https://en.wikipedia.org/wiki/Metal_Slug_Advance'),
  ('Q953869', 'F-Zero: Maximum Velocity is a 2001 racing game developed by NDcube and published by Nintendo as a launch title for the Game Boy Advance. It was the first F-Zero game released on a handheld game console.

Maximum Velocity takes place 25 years after F-Zero, in another F-Zero Grand Prix. The past generations of F-Zero had "piloted their way to fame", so it is the second F-Zero game without Captain Falcon, Samurai Goroh, Pico, or Dr. Stewart after BS F-Zero Grand Prix 2. Players control fast hovering crafts and use their speed-boosting abilities to navigate through the courses as quickly as possible.', 'https://en.wikipedia.org/wiki/F-Zero:_Maximum_Velocity'),
  ('Q11640289', 'Yu-Gi-Oh! The Eternal Duelist Soul is a card battle video game based on the Yu-Gi-Oh! franchise. It was developed and published by Konami and released on July 5, 2001 in Japan, October 16, 2002 in the United States for Game Boy Advance. It features a single-player campaign against opponents from the Yu-Gi-Oh! anime as well as a multiplayer head-to-head mode.

It was positively received by critics for its gameplay, although the game''s campaign was criticized for its lack of a true story, and the absence of a tutorial mode was noted as an issue for inexperienced players. The game was re-released in 2025 as part of the Yu-Gi-Oh! Early Days Collection game compilation.', 'https://en.wikipedia.org/wiki/Yu-Gi-Oh!_The_Eternal_Duelist_Soul'),
  ('Q9383518', 'Super Mario World 2: Yoshi''s Island is a 1995 platform game developed and published by Nintendo for the Super Nintendo Entertainment System (SNES). The player controls Yoshi dinosaurs on their quest to reunite baby Mario with his brother Luigi, who has been kidnapped by the wizard Kamek. Yoshi runs and jumps to reach the end of each level while solving puzzles and collecting items with Mario''s help.

Having introduced the character in the previous Super Mario game, Super Mario World (1990), Nintendo decided to develop a game starring Yoshi, with the aim of making it more accessible. Yoshi''s Island introduced his signature flutter jump and egg-spawning abilities. The marker-drawn art style was created by scanning hand-drawn pictures and approximating them pixel-by-pixel. Some special effects were powered by a new Super FX2 microchip.', 'https://en.wikipedia.org/wiki/Yoshi%27s_Island'),
  ('Q11350430', 'Mega Man Battle Chip Challenge is a video game developed by Inti Creates and published by Capcom for the Game Boy Advance (GBA) handheld game console. It is a spin-off title in the Mega Man Battle Network series. The game saw a simultaneous August 8, 2003 release in Japan on the WonderSwan Color and Swan Crystal titled Rockman EXE N1 Battle. The GBA version was localized in North America and Europe the following March. The game was released on the Wii U''s Virtual Console on July 30, 2014 in Japan, with both the North American and PAL region release occurring in August 2014.

Taking place within the timeline of the Battle Network series, Battle Chip Challenge involves a battling tournament called the "Battle Chip GP" among various pairs of online avatars called "NetNavis" and their human operators. Rather than directly control the player character through the traditional real-time tactical role-playing battles of the other Battle Network games, Battle Chip Challenge tasks the player with creating a "Program Deck" made up of abilities called "Battle Chips". The game randomly selects chips for the player and executes them in a duel with a computer-controlled opponent. Battle Chip Challenge suffered a relatively negative critical reception.', 'https://en.wikipedia.org/wiki/Mega_Man_Battle_Chip_Challenge'),
  ('Q11344719', 'Monster Rancher Advance (known in Japan as Monster Farm Advance) is a 2001 life simulation video game developed and published by Tecmo for the Game Boy Advance. It is a spin-off of the Monster Rancher series.', 'https://en.wikipedia.org/wiki/Monster_Rancher_Advance'),
  ('Q8564088', 'Flushed Away is a 2006 action-adventure video game based on the animated film of the same name for the GameCube, PlayStation 2, Game Boy Advance, and Nintendo DS. It was developed by Vicious Cycle Software and published by D3 Publisher. It was released in Japan for the Nintendo DS as Volume 17 of the Simple series.', 'https://en.wikipedia.org/wiki/Flushed_Away_(video_game)'),
  ('Q16259154', 'Robot Wars: Advanced Destruction is the third video game based on the British game show Robot Wars. It was the third of four games based on the show, with the first three selling over 250,000 copies. It was developed by Crawfish Interactive and published by BBC Multimedia and was released exclusively for the Game Boy Advance in 2001. It was also released in the US by Vivendi Universal Games. The game is based on Series 3 & 4 of Robot Wars.', 'https://en.wikipedia.org/wiki/Robot_Wars:_Advanced_Destruction'),
  ('Q16258817', 'Ultimate Card Games is a 2004 video game developed by German studio Cosmigo and published by Telegames for the Game Boy Advance and Nintendo DS platforms. It contains several thinking games, such as poker and solitaire. Ultimate Card Games for the Nintendo DS was initially scheduled for release in spring of 2005. After numerous delays, an October 2007 press release from Nintendo placed the game''s release in March 2008, but the game was not shipped to retailers. Ultimate Card Games DS was released only in North America on November 8, 2011.', 'https://en.wikipedia.org/wiki/Ultimate_Card_Games'),
  ('Q14906024', 'Game & Watch Gallery 4, known as Game & Watch Gallery Advance in Europe and Australia and Game Boy Gallery 4 in Japan, is a video game developed by Tose and published by Nintendo for the Game Boy Advance in October 2002. It is the fifth and final game in the Game & Watch Gallery series. It contains eleven remastered games from the Game & Watch line of Nintendo handheld games, several of which were featured in previous series entries, plus nine unlockable bonus games.

The game was initially only released in English-speaking markets; a Japanese version was not released until 2016 on the Wii U''s Virtual Console service. The game received mixed reviews, with critics praising the game''s presentation and accessible gameplay, but criticizing the uneven quality of the games and difficulty of unlocking its hidden content.', 'https://en.wikipedia.org/wiki/Game_%26_Watch_Gallery_4'),
  ('Q13415771', 'Hey Arnold!: The Movie is a 2002 platform video game developed by Altron and published by THQ for the Game Boy Advance, based upon the TV show''s film released the same year. It is the only video game to be exclusively based on Hey Arnold!.', 'https://en.wikipedia.org/wiki/Hey_Arnold!:_The_Movie_(video_game)'),
  ('Q16259532', 'This is about the 2001 game for Game Boy Advance. For the series, see Fire Pro Wrestling.

Fire Pro Wrestling (released in Japan as Fire Pro Wrestling A) is a professional wrestling video game in the Fire Pro Wrestling series and was the first Fire Pro game to receive an official release outside of Japan. A direct sequel, Fire Pro Wrestling 2, was released in 2002.', 'https://en.wikipedia.org/wiki/Fire_Pro_Wrestling_(2001_video_game)'),
  ('Q16259109', 'Rampage Puzzle Attack is a 2001 puzzle video game developed by Finnish studio Ninai Games and published by Midway for the Game Boy Advance. It is a clone of the puzzle game Drop Mania and based on the Rampage characters. At the beginning of the game, the three characters from the original game, George, Lizzie and Ralph, are available, but more characters who appeared in other games of the series can be unlocked through the Rescue mode. The characters appear on screen during the gameplay, climbing the side of the play arena or being caged at the bottom. The game uses password saves to track player progress.', 'https://en.wikipedia.org/wiki/Rampage_Puzzle_Attack'),
  ('Q16259321', 'Bratz is an American fashion doll and media franchise created by former Mattel employee Carter Bryant for MGA Entertainment, which first introduced in Spring 2001. Bratz dolls were popular during the early 2000s.

The four original 10-inch (25 cm) dolls were released on May 21, 2001 — Yasmin (Latina), Cloe (English blond/white), Jade (East Asian), and Sasha (Black) — with Meygan (Scottish Redhead) being added to the group in 2002 as a fifth member. They featured almond-shaped eyes adorned with eyeshadow adding lush and big glossy lips. Bratz reached great success with the expansion to spin-offs, including Bratz Kidz, Bratz Boyz, Bratz Babyz, Bratzillaz, and a media franchise consisting of discography and adaptations into a TV series, a web series, a live-action film and video games. Global sales of the entire franchise grossed $2 billion in 2005 and by the following year, the brand had about 40 percent of the fashion-doll market.', 'https://en.wikipedia.org/wiki/Bratz'),
  ('Q10322876', 'Madagascar: Operation Penguin is a 2005 licensed platform game developed by Vicarious Visions and published by Activision for the Game Boy Advance. It is based on the DreamWorks Animation movie Madagascar and loosely follows events from the film''s subplot, involving four penguins who attempt to escape the Central Park Zoo in order to live in Antarctica. Using various gadgets, the player traverses through 18 side-scrolling levels. The game''s critical reception was mostly positive, with praise for its visuals and some criticism directed towards its gameplay and audio.', 'https://en.wikipedia.org/wiki/Madagascar:_Operation_Penguin'),
  ('Q11888801', 'Power Rangers Wild Force is a video game based on the television series of the same name, developed by Natsume and published by THQ for the Game Boy Advance in 2002.', 'https://en.wikipedia.org/wiki/Power_Rangers_Wild_Force_(video_game)'),
  ('Q11888799', 'Power Rangers Ninja Storm is a set of two video games based on the Power Rangers Ninja Storm TV show for Game Boy Advance and Windows. Developed by Natsume, the Game Boy Advance version is a side-scrolling action game with beat ''em up elements. The Windows version, developed by Artech, features a collection of minigames with arcade-style gameplay.', 'https://en.wikipedia.org/wiki/Power_Rangers_Ninja_Storm_(video_game)'),
  ('Q16569631', 'Frogger''s Adventures 2: The Lost Wand is a 2002 action game developed and published by Konami for the Game Boy Advance. It is the sequel to 2001''s Frogger''s Adventures: Temple of the Frog, and follows Frogger as he attempts to find the scattered pieces of a magic wand.', 'https://en.wikipedia.org/wiki/Frogger%27s_Adventures_2:_The_Lost_Wand'),
  ('Q16569633', 'Frogger''s Journey: The Forgotten Relic is a 2003 action-adventure game developed and published by Konami for the Game Boy Advance. It follows Frogger, an anthropomorphic frog who attempts to find his missing grandfather. The gameplay is similar to that of previous Frogger titles, as players control Frogger through a series of top-down levels with the objective to reach a goal at the end. Levels are broken up by sections in a hub world where the player must explore, talk to NPCs and find items in order to progress to the next level.', 'https://en.wikipedia.org/wiki/Frogger%27s_Journey:_The_Forgotten_Relic'),
  ('Q16267104', 'Elevator Action Old & New is platform video game developed by Taito and published by MediaKite in Japan for the Game Boy Advance in 2002. It is an update to the 1983 title, Elevator Action. The game consists of old and new game modes. Old Mode is based on the original arcade game.

In New Mode, player can choose between three characters (Robin, Berry, Fan) like Elevator Action EX, but bullet and grenades are now limited, and are counted as separate inventories. In addition, each stage has time limits. New items include sunglasses, bullet, watch and a hamburger. There are 8 buildings in 1-Player Mode. In 2-Player Mode, players can play cooperatively or against each other.', 'https://en.wikipedia.org/wiki/Elevator_Action_Old_%26_New'),
  ('Q16266774', 'The Revenge of Shinobi is a 2002 hack-and-slash action game developed by 3d6 Games and published by THQ for the Game Boy Advance. Although both games share the same title and follow the exploits of a ninja character, the game is not a continuation or port of the Mega Drive/Genesis game of the same name.', 'https://en.wikipedia.org/wiki/The_Revenge_of_Shinobi_(2002_video_game)'),
  ('Q26157664', 'Daredevil is a video game released for the Game Boy Advance in 2003. It is based on the Marvel Comics character Daredevil and is a tie-in to the live-action 2003 film of the same name.', 'https://en.wikipedia.org/wiki/Daredevil_(video_game)'),
  ('Q21039913', 'The Scorpion King: Sword of Osiris is a platform game developed by WayForward Technologies and published by Universal Interactive for the Game Boy Advance in 2002. It is based on the film The Scorpion King, serving as a sequel to it.', 'https://en.wikipedia.org/wiki/The_Scorpion_King:_Sword_of_Osiris'),
  ('Q25396610', 'XXX (stylized as xXx) is a 2002 action video game developed by Digital Eclipse and published by Activision for the Game Boy Advance. Based on the film of the same name, the narrative follows Xander "xXx" Cage, an underground thrill-seeker who is recruited as a spy to stop the evil Anarchy 99 organization before it unleashes an assault on the Earth. Much of the game is played in a side-scrolling run and gun format, while a few levels feature vehicular combat inspired by Road Rash. The game was developed in approximately two months and received mixed reviews upon release, with critics faulting the gameplay''s lack of innovation, simplistic AI, and short length, though the visuals (particularly those of the motorcycle levels) and music were assessed positively.', 'https://en.wikipedia.org/wiki/XXX_(video_game)'),
  ('Q21079031', 'Davis Cup Tennis (known in Europe as Davis Cup) is a 2002 tennis video game for the Game Boy Advance developed by Hokus Pokus Games and published by Ubi Soft.

In the game''s two game modes, the player assumes control of either a tennis player during a single match or an entire country''s team in the Davis Cup, an international competition. Multiplayer is supported through the link cable. The game garnered mixed reviews from critics, who overall felt that it paled in comparison to 2002''s Virtua Tennis and earlier versions of Mario Tennis.', 'https://en.wikipedia.org/wiki/Davis_Cup_Tennis'),
  ('Q24935617', 'Jackie Chan Adventures: Legend of the Dark Hand is a 2001 beat ''em-up video game based on the animated series Jackie Chan Adventures, which focuses on a fictionalized version of Hong Kong action film star Jackie Chan. The game was developed by Torus Games, published by Activision and released for the Game Boy Advance on November 21, 2001 in North America and November 30, 2001 in Europe.', 'https://en.wikipedia.org/wiki/Jackie_Chan_Adventures:_Legend_of_the_Dark_Hand'),
  ('Q20995103', 'Disney Sports Snowboarding is a 2003 snowboarding racing video game developed and published by Konami for the Game Boy Advance. The game is part of a series of Disney-licensed sports titles under the Disney Sports brand. Upon release, the game received mixed to average reception, with praise directed towards the game''s pre-rendered background visuals and range of collectables, and criticism to the controls, course design and limited content.', 'https://en.wikipedia.org/wiki/Disney_Sports_Snowboarding'),
  ('Q20240929', 'Namco Museum is a 2001 video game compilation developed by Mass Media and published by Namco for the Game Boy Advance. It contains ports of five of their classic arcade games, Ms. Pac-Man, Pole Position, Dig Dug, Galaga, and Galaxian.', 'https://en.wikipedia.org/wiki/Namco_Museum_(GBA_video_game)'),
  ('Q20726215', 'MotoGP: Ultimate Racing Technology, known in the United States as simply MotoGP, is a Grand Prix motorcycle racing video game for Game Boy Advance, Xbox, Microsoft Windows, mobile phones, and N-Gage. It is based on the 2001 Grand Prix motorcycle racing season.

The game''s features include weather effects, a dynamic replay mode and custom soundtracks. The game includes 10 real-world race tracks and all the riders and bikes from the 2001 MotoGP season. The menu theme music is Psynn by Shawn Hargreaves.

An online-enabled demo of MotoGP shipped with Xbox Live starter kits in 2002. Players who didn''t own the full game could access 23 riders and three courses while players who did own the full game could access all the content they had unlocked.', 'https://en.wikipedia.org/wiki/MotoGP:_Ultimate_Racing_Technology'),
  ('Q17514208', 'Brother Bear is a 2003 video game based on the 2003 animated film of the same name. It was released on November 4, 2003, for Game Boy Advance, and November 11 for Microsoft Windows.', 'https://en.wikipedia.org/wiki/Disney%27s_Brother_Bear_(video_game)'),
  ('Q18149331', 'Tarzan: Return to the Jungle is a 2002 platform game developed by Digital Eclipse and published by Activision for the Game Boy Advance. The game is based on the 2001–2003 animated television series The Legend of Tarzan.', 'https://en.wikipedia.org/wiki/Tarzan:_Return_to_the_Jungle'),
  ('Q26903145', 'Pokémon Ruby Version and Pokémon Sapphire Version are 2002 role-playing video games developed by Game Freak for the Game Boy Advance. Although the games were published by Nintendo internationally in 2003, The Pokémon Company published them in Japan in late 2002, making them the first mainline games to have this distinction, as well as the second games to have it overall, after Pokémon Card GB2: Great Rocket-Dan Sanjō! They are the first installments in the third generation, or the "advanced generation", of the Pokémon video game series, and in turn the Pokémon media franchise. A third version, Pokémon Emerald Version, was released two years later in each region. Remakes of the two games, titled Pokémon Omega Ruby and Alpha Sapphire, were released for the Nintendo 3DS worldwide in November 2014, exactly twelve years to the date of the original Ruby and Sapphire release date, with the exception of Europe, where they released a week later.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Ruby_and_Sapphire'),
  ('Q26903151', 'Pokémon Ruby Version and Pokémon Sapphire Version are 2002 role-playing video games developed by Game Freak for the Game Boy Advance. Although the games were published by Nintendo internationally in 2003, The Pokémon Company published them in Japan in late 2002, making them the first mainline games to have this distinction, as well as the second games to have it overall, after Pokémon Card GB2: Great Rocket-Dan Sanjō! They are the first installments in the third generation, or the "advanced generation", of the Pokémon video game series, and in turn the Pokémon media franchise. A third version, Pokémon Emerald Version, was released two years later in each region. Remakes of the two games, titled Pokémon Omega Ruby and Alpha Sapphire, were released for the Nintendo 3DS worldwide in November 2014, exactly twelve years to the date of the original Ruby and Sapphire release date, with the exception of Europe, where they released a week later.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Ruby_and_Sapphire'),
  ('Q27964097', 'Spirit: Stallion of the Cimarron (or simply Spirit) is a 2002 American animated Western film directed by Kelly Asbury and Lorna Cook, written by John Fusco, from an idea by Jeffrey Katzenberg, who produced with Mireille Soria. Set in the Old West in the late 19th century, the film follows Spirit, a Kiger mustang stallion (voiced by Matt Damon as a narrator), who is captured during the American Indian Wars by the United States Cavalry; he is eventually freed by a Lakota man named Little Creek with whom he bonds, as well as a mare named Rain.

The film was produced by DreamWorks Animation, combining traditional animation and computer animation. In contrast to the anthropomorphic style of animal characters in other animated features, Spirit and his fellow horses communicate with each other through non-linguistic sounds and body language (albeit with many human facial expressions and reactions).', 'https://en.wikipedia.org/wiki/Spirit:_Stallion_of_the_Cimarron'),
  ('Q26910876', 'Pokémon FireRed Version and Pokémon LeafGreen Version are 2004 remakes of the 1996 role-playing video games Pokémon Red and Green. They were developed by Game Freak and published by The Pokémon Company and Nintendo for the Game Boy Advance. FireRed and LeafGreen were first released in Japan in January 2004 and was released in the same year as FireRed and LeafGreen versions in North America and Europe in September and October 2004, respectively. The games are part of the third generation of the Pokémon video game series and hold the distinction of being the first enhanced remakes of previous games within the franchise.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_FireRed_and_LeafGreen'),
  ('Q26910884', 'Pokémon FireRed Version and Pokémon LeafGreen Version are 2004 remakes of the 1996 role-playing video games Pokémon Red and Green. They were developed by Game Freak and published by The Pokémon Company and Nintendo for the Game Boy Advance. FireRed and LeafGreen were first released in Japan in January 2004 and was released in the same year as FireRed and LeafGreen versions in North America and Europe in September and October 2004, respectively. The games are part of the third generation of the Pokémon video game series and hold the distinction of being the first enhanced remakes of previous games within the franchise.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_FireRed_and_LeafGreen'),
  ('Q29907190', 'Motocross Maniacs Advance is a 2002 racing video game developed and published by Konami for the Game Boy Advance. The game is the sequel to the 1989 Game Boy title Motocross Maniacs. Konami announced Motocross Maniacs Advance in December 2001, and showcased the game at E3 in May 2002. Upon release, the game received average reviews, with praise directed to its updated visual presentation and new game modes and criticism to its speed and difficulty.', 'https://en.wikipedia.org/wiki/Motocross_Maniacs_Advance'),
  ('Q28501087', 'The King of Fighters EX: Neo Blood (or KOF EX) is a fighting game developed by Playmore and Artoon in 2002 for Nintendo''s Game Boy Advance. Despite being based on The King of Fighters ''99 in terms of systems and design, the game features different playable characters with an original storyline involving Kyo Kusanagi and his friends being the protagonist of a new "King of Fighters" tournament set by crimelord Geese Howard. The game offers several returning characters with Kyo''s ally Moe Habana being a new character.

Despite SNK going bankrupt, there were no issues with the development of the game, with Marvelous Entertainment developing it. The game received positive response by critics for its controls and cast and was followed by a sequel titled The King of Fighters EX2: Howling Blood in 2003.', 'https://en.wikipedia.org/wiki/The_King_of_Fighters_EX:_Neo_Blood'),
  ('Q28671191', 'The Incredible Hulk is a 2003 beat ''em up video game developed by Pocket Studios and published by Universal Interactive for the Game Boy Advance. The game, featuring an isometric perspective, is based on the Marvel Comics superhero Hulk, who must traverse through a series of levels and destroy enemies with an assortment of physical attacks; a multiplayer mode in which players battle against each other is also featured.

The game was released simultaneously alongside the console and Microsoft Windows title Hulk to coincide with the release of the film, but differs from its counterpart in its basis on the comics rather than the film. Critical reception to the game was mixed; while the visuals were commended, the gameplay, controls, and audio were criticized, and reactions to the multiplayer mode were divided.', 'https://en.wikipedia.org/wiki/The_Incredible_Hulk_(2003_video_game)'),
  ('Q28127241', 'Codename: Kids Next Door – Operation: S.O.D.A. is a 2004 platform video game based on the American animated television series Codename: Kids Next Door on Cartoon Network. Developed by Vicarious Visions and published by Global Star Software for the Game Boy Advance, it was released exclusively in North America.

Operation: S.O.D.A. is one of the only two video games to be solely based on Codename: Kids Next Door. The other, Operation: V.I.D.E.O.G.A.M.E., is a 3D platform game developed by High Voltage Software for the PlayStation 2, GameCube, and Xbox.', 'https://en.wikipedia.org/wiki/Codename:_Kids_Next_Door_%E2%80%93_Operation:_S.O.D.A.'),
  ('Q28127188', 'Hot Wheels: Burnin'' Rubber (released in Japan as Hot Wheels Advance) is a 2001 racing video game developed by Altron and published by THQ for the Game Boy Advance. The game is based on the Hot Wheels toy series.', 'https://en.wikipedia.org/wiki/Hot_Wheels:_Burnin%27_Rubber'),
  ('Q28451208', 'Foster''s Home for Imaginary Friends is an American animated television series created by Craig McCracken for Cartoon Network. Produced by Cartoon Network Studios, it was the network''s first series primarily animated using Adobe Flash. Production took place in Burbank, California, with additional animation services provided by Boulder Media in Ireland.

Set in a world where imaginary friends coexist with humans, the series follows Mac, an eight-year-old boy who is forced by his mother to give up his imaginary friend, Bloo. After discovering an orphanage for abandoned imaginary friends, Bloo moves in and is allowed to remain there on the condition that Mac visits him every day. Episodes center on their interactions with the home''s residents and staff, as everyday situations often lead to unexpected predicaments.', 'https://en.wikipedia.org/wiki/Foster%27s_Home_for_Imaginary_Friends'),
  ('Q28496672', 'Alienators: Evolution Continues is an action game for the Game Boy Advance. It was developed by Digital Eclipse and published by Activision. The game was released in North America on November 13, 2001 and in Europe on November 30, 2001. The game is based on the animated science fiction television show Alienators: Evolution Continues. The player plays as Dr. Ira Kane to save the world from alien domination.', 'https://en.wikipedia.org/wiki/Alienators:_Evolution_Continues_(video_game)'),
  ('Q48081885', 'Altered Beast: Guardian of the Realms is a 2002 beat ''em up video game developed by 3d6 Games and published by Sega for the Game Boy Advance. It was released by THQ in North America in 2002 and by Sega in Europe in 2003. The game is a handheld sequel to Sega''s 1988 arcade video game Altered Beast. The game was the result of a publishing deal between Sega and THQ, with third-party American developer 3d6 creating two Advance titles, also including The Revenge of Shinobi. Upon release, Guardian of the Realms received mixed reviews, with critics praising the game''s likeness to the original release, but critiquing the long level design, limitations to the combat, and inconsistent visuals.', 'https://en.wikipedia.org/wiki/Altered_Beast:_Guardian_of_the_Realms'),
  ('Q48349442', 'Droopy''s Tennis Open is a tennis video game developed by Bit Managers and published by Light & Shadow Production for the Game Boy Advance exclusively in Europe. The game is based on MGM Cartoons'' Droopy animated franchise, and features several characters and locations from the series.', 'https://en.wikipedia.org/wiki/Droopy%27s_Tennis_Open'),
  ('Q52158532', 'Punch King is a boxing video game developed by Full Fat and published by Acclaim Entertainment for Game Boy Advance in 2002.', 'https://en.wikipedia.org/wiki/Punch_King'),
  ('Q50277087', 'Pokémon Mystery Dungeon: Blue Rescue Team and Pokémon Mystery Dungeon: Red Rescue Team are a matched pair of Pokémon video games for the Nintendo DS and Game Boy Advance, respectively. The games were developed by Chunsoft and published by The Pokémon Company and Nintendo. Red Rescue Team was the last Pokémon game released for the Game Boy Advance. The two versions are mostly identical, with Blue Rescue Team taking advantage of the dual-screen features and increased graphical and sound capabilities of the Nintendo DS. The game has six Pokémon exclusive to each version. Mystery Dungeon differs from the mainline games in that the player character is a Pokémon rather than a trainer.', 'https://en.wikipedia.org/wiki/Pok%C3%A9mon_Mystery_Dungeon:_Blue_Rescue_Team_and_Red_Rescue_Team'),
  ('Q48817628', 'Disney''s Lilo & Stitch is a 2002 side-scrolling platform video game developed by Digital Eclipse for the Game Boy Advance. Based on the Disney animated film Lilo & Stitch, it was released in North America on June 7, 2002, by Disney Interactive, with Ubi Soft publishing the game in Europe on October 4, 2002.', 'https://en.wikipedia.org/wiki/Disney%27s_Lilo_%26_Stitch_(GBA_video_game)'),
  ('Q35881040', 'Dungeons & Dragons - Eye of the Beholder is a video game released for the Game Boy Advance in 2002, developed by American studio Pronto Games and published by Infogrames. It is an adaptation of the 1991 game of the same name.', 'https://en.wikipedia.org/wiki/Eye_of_the_Beholder_(2002_video_game)'),
  ('Q39058274', 'Disney''s Herbie: Fully Loaded is a racing game developed by Climax Handheld Games and published by Buena Vista Games for the Game Boy Advance. It was released in North America on June 21, 2005, and in Europe on August 5, 2005. It is loosely based on the 2005 film Herbie: Fully Loaded and features stills from the movie in the game.', 'https://en.wikipedia.org/wiki/Disney%27s_Herbie:_Fully_Loaded'),
  ('Q58106199', 'Boulder Dash EX is an action-puzzle video game developed by Tokyo-based Vision Works and published by Kemco for the Game Boy Advance in September 2002. It is part of the Boulder Dash series and a remake of the arcade version of Boulder Dash.', 'https://en.wikipedia.org/wiki/Boulder_Dash_EX'),
  ('Q55381997', 'Sea Trader: Rise of Taipan is a simulation video game developed and published by Jaleco Entertainment''s American division. The game was released exclusively in North America in 2002 for the Game Boy Advance. In Sea Trader, the player controls a ship and tries to build a trading empire by selling goods between different ports. Reception was mixed, with praise for its addictive nature but criticism of its dated graphics and somewhat bare-bones gameplay.', 'https://en.wikipedia.org/wiki/Sea_Trader:_Rise_of_Taipan'),
  ('Q54938490', 'Jet Grind Radio (released as Jet Set Radio in Europe) is a 2003 video game developed by Vicarious Visions and published by THQ for the Game Boy Advance. It is a handheld adaptation of the 2000 Dreamcast title Jet Set Radio. The game was released in North America on June 26, 2003, and in Europe on February 20, 2004.', 'https://en.wikipedia.org/wiki/Jet_Grind_Radio_(2003_video_game)'),
  ('Q63125241', 'Bubble Bobble is a 1986 platform video game developed and published by Taito for arcades. It was released in North America by Romstar and in Europe by Electrocoin. Players control Bub and Bob, two dragons who set out to save their girlfriends from a world called the Cave of Monsters. In each level, Bub and Bob must defeat every enemy present by trapping them in bubbles and popping them. The enemies will then turn into bonus items when they hit the ground. There are 100 levels total, each becoming progressively more difficult.

Bubble Bobble was designed by Fukio "MTJ" Mitsuji. When he joined Taito in 1986, he felt that Taito''s game output was of mediocre quality. In response, he decided to make a game that was fun to play and could rejuvenate the company''s presence in the industry. Mitsuji hoped his game would appeal to women, specifically couples that visited arcades. As such, he decided to make Bubble Bobble focus largely on its two player co-operative mode. He made bubbles the core mechanic as he thought they would be a fun element that girls would enjoy.', 'https://en.wikipedia.org/wiki/Bubble_Bobble_(video_game)'),
  ('Q67388163', 'Top Gear Rally, known in Japan as Top Gear Rally SP, is a 2003 racing video game developed by Tantalus Interactive and published by Kemco for the Game Boy Advance. It was released by Nintendo outside Japan.', 'https://en.wikipedia.org/wiki/Top_Gear_Rally_(2003_video_game)'),
  ('Q108936109', 'Dr. Sudoku is a 2006 sudoku puzzle video game developed and published by Success in Japan. The game was later published by Mastiff in North America and 505 Gamestreet in the United Kingdom. Upon release, the game received average reviews, with critics enjoying the puzzles, but considering the game lacked additional features and was less accessible than other methods to play the game.', 'https://en.wikipedia.org/wiki/Dr._Sudoku'),
  ('Q106620501', 'Kim Possible: Revenge of Monkey Fist is a 2002 platformer game developed by Digital Eclipse published by Disney Interactive for the Game Boy Advance. It is based on the animated television series of the same name. The game received mixed reviews from critics. While they praised graphics and music''s faithfulness to the show, they criticized its controls and password save system.', 'https://en.wikipedia.org/wiki/Kim_Possible:_Revenge_of_Monkey_Fist'),
  ('Q108607460', 'Duel Masters: Sempai Legends is 2004 role-playing video game developed by Canadian studio Mistic Software and published by Atari.', 'https://en.wikipedia.org/wiki/Duel_Masters:_Sempai_Legends'),
  ('Q110307863', 'Ozzy & Drix is a 2003 video game developed by Raylight Studios and published by Midway Games for the Game Boy Advance (GBA). Based on the animated television series of the same name, the game follows the characters Ozzy and Drix, who must rescue their city''s kidnapped mayor. While the game is primarily a side-scrolling platformer, driving and first-person shooter levels are also included. The game was poorly received by critics, who highlighted significant flaws in gameplay, controls, and level design, despite some praise for its 3D graphics.', 'https://en.wikipedia.org/wiki/Ozzy_%26_Drix_(video_game)'),
  ('Q108610998', 'James Bond 007: Everything or Nothing is a 2003 third-person shooter video game developed by Griptonite Games and published by Electronic Arts for the Game Boy Advance. As MI6 agent James Bond, the player must foil an ex-KGB agent who plans to use nanotechnology for world domination.

Everything or Nothing was released in November 2003, a few months prior to the release of a home console version. It received "mixed or average" reviews according to Metacritic.', 'https://en.wikipedia.org/wiki/James_Bond_007:_Everything_or_Nothing_(GBA_video_game)'),
  ('Q108813099', 'Snood 2: On Vacation (also released as Snood 2: Snoods on Vacation) is a 2005 puzzle video game developed by Gravity-i and published by Destination Software in the United States for the Game Boy Advance and Nintendo DS and Cybiko for mobile phones. Gameplay consists of clearing patterns of ''snoods'' by matching pieces of the same color, in a manner similar to Puzzle Bobble or Bust-a-Move. The game is a sequel to the 1996 title Snood, ported to the Game Boy Advance in 2001. Upon release, Snood 2 met a mixed reception from critics, with praise directed to the game''s variety of modes and criticism of its presentation and lack of originality.', 'https://en.wikipedia.org/wiki/Snood_2:_On_Vacation'),
  ('Q117818136', 'Broken Sword: The Shadow of the Templars is an adventure video game developed by Revolution Software and published by BAM! Entertainment for the Game Boy Advance (GBA) handheld game console. It is based on the original game of the same name from 1996. and released in North America and Europe in March 2002.

The designers chose to build the game from the ground up and picking what content from the original was most important to include. A major change from the original version was the control scheme: the original was a point-and-click adventure game using a computer mouse, but in the port, the player uses the GBA''s d-pad to control the main character and his actions. The GBA version was later used as the basis for Broken Sword: Shadow of the Templars - The Director''s Cut for convenience reasons. While the second game in the series, Broken Sword II: The Smoking Mirror, was planned to have a GBA title as well, it was canceled at the last minute when the studio shut down, leaving The Shadow of the Templars as the sole game in the franchise for the GBA.', 'https://en.wikipedia.org/wiki/Broken_Sword:_The_Shadow_of_the_Templars_(2002_video_game)'),
  ('Q118213987', 'Harry Potter and the Philosopher''s Stone (released in the United States as Harry Potter and the Sorcerer''s Stone) is a 2001 video game developed by Griptonite Games and published by Electronic Arts for the Game Boy Advance. Based on the 1997 novel of the same name, the player controls Harry Potter, who must navigate his first year in the Hogwarts School of Witchcraft and Wizardry and eventually confront the villainous Lord Voldemort.

The Game Boy Advance version was released simultaneously with the PlayStation and Game Boy Color versions and received mixed reviews from critics. While the visuals and faithfulness to the novel were praised, the gameplay was criticized as shallow and repetitive. In the United States, the game was among the highest-selling titles released for handheld consoles between 2000 and 2006.', 'https://en.wikipedia.org/wiki/Harry_Potter_and_the_Philosopher%27s_Stone_(GBA_video_game)'),
  ('Q95678518', 'Space Channel 5 is a 1999 music video game developed and published by Sega for the Dreamcast. It was later ported to the PlayStation 2 and Game Boy Advance. Following space-faring reporter Ulala as she investigates an alien invasion, players engage in rhythm-based combat where Ulala mimics the actions of rivals in time to musical tracks.

The game was conceived by Tetsuya Mizuguchi, who was told to create something aimed at a female audience. Production lasted two years, with a staff of around 20 that included company veterans and newcomers to game development. The music, composed by Naofumi Hataya and Kenichi Tokoi, drew inspiration from big band music, including Ken Woodman''s song "Mexican Flyer", which served as the game''s theme song. The visual style was influenced by culture from the 1950s and 1960s and the later music videos of Peter Gabriel and Michael Jackson, the latter having a cameo appearance in the game.', 'https://en.wikipedia.org/wiki/Space_Channel_5'),
  ('Q92039045', 'F-24: Stealth Fighter is a video game developed by Skyworks Technologies and published by Majesco in 2006 for the Game Boy Advance and 2007 for the Nintendo DS. Upon release, the game received negative reviews, with criticism directed at the game''s visual presentation, poor controls, and resemblance to other flight simulation games.', 'https://en.wikipedia.org/wiki/F24:_Stealth_Fighter');

insert into import_summary (wikidata_id, summary, source) values
  ('Q102181842', 'Tom and Jerry in Infurnal Escape is a 2003 video game for the Game Boy Advance. The game was the first of three video game titles developed by Canadian animation studio CinéGroupe, with the title published by NewKidCo. The game is a platformer using characters licensed from the Tom and Jerry animated series, with players guiding Tom through fifteen levels to escape the underworld. Upon release, Infurnal Escape received a mixed reception, with reviewers praising the game''s visual presentation but critiquing the game''s control scheme and use of traps.', 'https://en.wikipedia.org/wiki/Tom_and_Jerry_in_Infurnal_Escape'),
  ('Q115616575', 'Thunderbirds is a 2004 action game for the Game Boy Advance developed by Saffire and published by Vivendi Universal Games, licensed from the Thunderbirds franchise and based on the film of the same name.', 'https://en.wikipedia.org/wiki/Thunderbirds_(2004_video_game)'),
  ('Q117128752', 'Shrek Swamp Kart Speedway is a kart racing game published by TDK Mediactive released in March 2002 for the Game Boy Advance. The game is based on the Shrek franchise. Players can race as one of twelve Shrek characters against other racers.', 'https://en.wikipedia.org/wiki/Shrek_Swamp_Kart_Speedway'),
  ('Q54844', 'Star Wars: Episode II – Attack of the Clones is an action game based on the 2002 film of the same name, developed by David A. Palmer Productions and published by THQ for the Game Boy Advance. The game was first announced by THQ and LucasArts in February 2002, months prior to the film''s release.', 'https://en.wikipedia.org/wiki/Star_Wars:_Episode_II_%E2%80%93_Attack_of_the_Clones_(video_game)'),
  ('Q55253', 'Star Wars: Flight of the Falcon is a 2003 first-person shooter video game developed by Pocket Studios and published by THQ for the Game Boy Advance. Based on the events of the original Star Wars trilogy of films, the player controls various spaceships in battles against the antagonistic Galactic Empire. The story follows the pilots of the Millennium Falcon, Han Solo and his Wookiee co-pilot Chewbacca, as they help save the galaxy from the Empire''s forces.

Flight of the Falcon was first announced on June 23, 2003, and was originally scheduled to be released that summer, but the release date was pushed back to November 21, 2003. Upon its release, the game received mostly negative reviews, with criticism for its lagging graphics, gameplay, and excessively long levels; however, it received some praise for its sound design and music, as well as for its detailed level backgrounds.', 'https://en.wikipedia.org/wiki/Star_Wars:_Flight_of_the_Falcon'),
  ('Q123154043', 'Ultimate Winter Games is a 2003 video game for the Game Boy Advance developed by Sproing Interactive and published by Telegames. The game features a set of four winter sports, including downhill skiing, curling, snowboarding and bobsledding. Upon release, the game received a mixed reception, with critics praising the game''s visual presentation and critiquing its limited and simplistic series of events.', 'https://en.wikipedia.org/wiki/Ultimate_Winter_Games'),
  ('Q123064405', 'Hot Wheels: All Out is a racing video game developed by British studio TwoFiveSix and published by Destination Software and ZOO Digital Publishing. It was released in 2006 exclusively for the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Hot_Wheels:_All_Out'),
  ('Q124222605', 'The Glucoboy is a medical device developed by Guidance Interactive Healthcare as a removable accessory for the Nintendo Game Boy Advance. The device is a blood glucose monitor targeted at children with diabetes that provides users with incentives to monitor their blood glucose levels through the use of games and points. Advertised as the "first medical device to interface with a Nintendo Game Boy", the Glucoboy received retrospective attention for its innovative and unusual use as a peripheral for handheld devices.

A successor to the Glucoboy called the Didget was released by Bayer HealthCare for the Nintendo DS in 2009 in the UK and 2010 in the US.', 'https://en.wikipedia.org/wiki/Glucoboy'),
  ('Q124457760', 'Mucha Lucha! Mascaritas of the Lost Code is a 2003 beat ''em up video game developed by Digital Eclipse and published by Ubisoft for the Game Boy Advance. Based on the animated television series of the same name, the game follows the series'' main characters Rikochet, Buena Girl, and The Flea, who must recover a stolen tome belonging to their school. The game was critically panned upon release, with reviewers faulting its repetitive gameplay, lack of challenge, and failure to capture the wrestling essence of the source material, despite some praise for its visual fidelity to the cartoon.', 'https://en.wikipedia.org/wiki/Mucha_Lucha!_Mascaritas_of_the_Lost_Code'),
  ('Q54856', 'Star Wars Trilogy: Apprentice of the Force is an action-platform game developed and published by Ubisoft. Released in September 2004 for Game Boy Advance, the game follows Luke Skywalker through the Star Wars original trilogy.', 'https://en.wikipedia.org/wiki/Star_Wars_Trilogy:_Apprentice_of_the_Force'),
  ('Q54845', 'Star Wars: The New Droid Army is a 2002 action video game developed by Helixe and published by THQ for the Game Boy Advance. The game features Anakin Skywalker and takes place shortly after the events of Star Wars: Episode II – Attack of the Clones, which it is a tie-in to.', 'https://en.wikipedia.org/wiki/Star_Wars:_The_New_Droid_Army'),
  ('Q132522026', 'Downtown Nekketsu Monogatari, released as River City Ransom in North America and Street Gangs in PAL regions, is a 1989 action-adventure beat ''em up video game developed and published by Technōs Japan for the Nintendo Entertainment System. It is the third installment of the Kunio-kun series released for the NES, preceded by Renegade and Super Dodge Ball, and the first to be developed specifically for the system.

Gameplay is similar to that of Renegade, but set in a non-linear open world, a first for the series. It was the first console game published by the developer''s North American subsidiary American Technos.', 'https://en.wikipedia.org/wiki/River_City_Ransom'),
  ('Q133760330', 'Tony Hawk''s Pro Skater 2 is a 2001 skateboarding video game developed by Vicarious Visions and published by Activision for the Game Boy Advance (GBA) handheld game console. It is a portable version of the console game of the same name, starring the skateboarder Tony Hawk. While the console versions of the game have the camera positioned behind the player-character, this version uses an isometric perspective, featuring modified levels taken from the console version. The player is tasked with getting as high a score as they can in a limited time by performing skateboarding tricks.

Vicarious Visions proposed the creation of a GBA version, getting approval from Activision and Tony Hawk. To include the tricks from the PlayStation, they created a 3D engine for the game, featuring polygonal characters. The music was composed by Manfred Linzner as a pastiche of the music featured in the series, as well as songs from "skate punk-type artists". Tony Hawk''s series quality assurance testers were initially critical of the game for lacking "purposeful level design" and were brought on to help address these issues. It was released as a launch title for the GBA in North America and Europe in June 2001 after being developed for one year.', 'https://en.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater_2_(GBA_video_game)'),
  ('Q130641562', 'Dogz is a virtual pet and pet simulation game in the Petz series, released for the Game Boy Advance, in 2005, and Nintendo DS, in 2006. It is a localisation of the Japanese game Kawaii Koinu Wonderful, released in November 2004, and developed by MTO as part of the Nakayoshi Pet series. Unlike other games in the Petz series the player controls a playable character in an Isometric world.

It is a distinct game from the Catz games released on the Game Boy Advance and DS, as well as the previous Dogz game released for Game Boy Color.', 'https://en.wikipedia.org/wiki/Dogz_(2005_video_game)'),
  ('Q131450406', 'Inspector Gadget Racing is a 2003 racing video game for the Game Boy Advance developed by Bit Managers and published by Light & Shadow Production. The game is a kart racing game featuring licensed characters from the Inspector Gadget franchise. Upon release, the game received mixed reviews, with reviewers praising the design and variety of the circuits, but critiquing the game''s controls and handling, difficulty and lack of originality in the genre. Retrospective reception of the game was also mixed, with outlets doubting the necessity of a licensed game using Inspector Gadget characters.', 'https://en.wikipedia.org/wiki/Inspector_Gadget_Racing'),
  ('Q131450436', 'Muppet Pinball Mayhem is a 2002 pinball video game for the Game Boy Advance developed by Digital Eclipse and published by NewKidCo in the United States and Ubi Soft in Europe.', 'https://en.wikipedia.org/wiki/Muppet_Pinball_Mayhem'),
  ('Q131584880', 'Disney Sports Motocross is a 2003 motocross racing video game for the Game Boy Advance developed by Jupiter Corporation and published by Konami. The game is the final of a series of Disney-licensed sports titles under the Disney Sports brand. The game is a motocross game in which players can race as Disney licensed characters, including Mickey Mouse, across seven stages. Upon release, Disney Sports Motocross received a mixed reception, with reviewers praising the game''s graphics, and critiquing the game''s lack of variety in courses, confusing controls and visual design, and difficulty.', 'https://en.wikipedia.org/wiki/Disney_Sports_Motocross'),
  ('Q132129060', 'Driver 2 (also known as Driver 2: Back on the Streets and as Driver 2: The Wheelman Is Back in North America) is a 2000 action driving video game and the second installment of the Driver series. It was developed by Reflections Interactive and published by Infogrames for PlayStation. A port to the Game Boy Advance, titled Driver 2 Advance, was released in 2002, developed by Sennari Interactive and released under Infogrames'' Atari range of products.

The follow up to Driver, Driver 2 too was a commercial success, although received a less enthusiastic critical reception in comparison. The next installment would be Driver 3 in 2004, while a prequel title was released as Driver: Renegade in 2011.', 'https://en.wikipedia.org/wiki/Driver_2'),
  ('Q134993296', 'Crash Nitro Kart is a 2003 kart racing video game developed by Vicarious Visions and published by Universal Interactive for the Game Boy Advance. A version for the N-Gage was released in 2004. The plot involves Crash Bandicoot and his friends and enemies being abducted by a galactic dictator and forced to compete in an interplanetary circuit. The game is Vicarious Visions''s first racing game for the GBA, as well as their first GBA game to utilize a Mode 7 engine. The N-Gage version features 3D tracks with contours added to the terrain.

The GBA version was positively received as a competent kart racer with strong mechanics, track design, and replayability, but it was held back by technical slowdowns and lack of originality. Reception to the N-Gage version was mixed, with its core gameplay and content praised but heavily undermined by the platform''s limitations, particularly the narrow screen and control issues.', 'https://en.wikipedia.org/wiki/Crash_Nitro_Kart_(GBA_video_game)'),
  ('Q135509292', 'Turok: Evolution is a side-scrolling shooter game in the Turok series. It was developed by RFX Interactive and published by Acclaim Entertainment for the handheld Game Boy Advance. It was released in 2002, alongside a home console counterpart. Turok: Evolution received mixed reviews according to Metacritic.', 'https://en.wikipedia.org/wiki/Turok:_Evolution_(GBA_video_game)'),
  ('Q135920640', 'Crushed Baseball is a 2004 sports video game developed by Griptonite Games and published by Summitsoft Entertainment for the Game Boy Advance. The game is a non-licensed baseball title in which players accumulate "mojo" to perform supernatural and comic abilities on the pitch. Console versions for the PlayStation 2 and GameCube were unreleased following the collapse of the game''s original publisher BAM! Entertainment prior to release. Upon release, Crushed Baseball received mixed reviews.', 'https://en.wikipedia.org/wiki/Crushed_Baseball'),
  ('Q135928202', 'Turbo Turtle Adventure is a 2002 puzzle video game for the Game Boy Advance developed by Iridon Interactive and published by Majesco. Gameplay involves guiding a rolling turtle through a series of levels, whilst avoiding obstacles. Upon release, the game received generally positive reviews, with praise directed to its addictiveness and resemblance to puzzle titles including Super Monkey Ball and Marble Madness, and criticism to its repetitive trial-and error gameplay.', 'https://en.wikipedia.org/wiki/Turbo_Turtle_Adventure'),
  ('Q136064789', 'Street Jam Basketball is a 2004 basketball sports video game for the Game Boy Advance developed by Prograph Research and published by DSI Games. The game is the first Advance title to be developed by Italian studio Prograph Research. Upon release, Street Jam Basketball received generally unfavorable reviews, with criticism directed to the game''s limited variety and gameplay options, and the confusing presentation of its sprites.', 'https://en.wikipedia.org/wiki/Street_Jam_Basketball'),
  ('Q137594992', 'Sudoku Fever (also titled Global Star Sudoku Fever) is a 2006 sudoku puzzle video game developed by puzzle.tv and published by Global Star Software, a publishing wing of Take-Two Interactive. Upon release, the game received mixed reviews, with praise for the game''s puzzles, but critiques of its visual presentation and lack of additional features.', 'https://en.wikipedia.org/wiki/Sudoku_Fever'),
  ('Q137643978', 'Planet Monsters is a 2001 video game developed by Planet Interactive Development and published by Titus for the Game Boy Advance. It is an action and arcade style game in which players must navigate a maze of monsters and defeat them by pushing blocks and using weapons. Upon release, the game received mixed reviews, with critics comparing the game''s design to earlier arcade titles including Pengo.', 'https://en.wikipedia.org/wiki/Planet_Monsters'),
  ('Q135011408', 'Dogz is a virtual pet and pet simulation game in the Petz series, released for the Game Boy Advance, in 2005, and Nintendo DS, in 2006. It is a localisation of the Japanese game Kawaii Koinu Wonderful, released in November 2004, and developed by MTO as part of the Nakayoshi Pet series. Unlike other games in the Petz series the player controls a playable character in an Isometric world.

It is a distinct game from the Catz games released on the Game Boy Advance and DS, as well as the previous Dogz game released for Game Boy Color.', 'https://en.wikipedia.org/wiki/Dogz_(2005_video_game)'),
  ('Q18928696', 'Sega Arcade Gallery is a compilation of four Sega arcade games ported to the Game Boy Advance. It was released in North America on May 22, 2003 and in Europe on August 1.', 'https://en.wikipedia.org/wiki/Sega_Arcade_Gallery'),
  ('Q126484775', 'The Simpsons: Road Rage is a 2003 driving game developed by Altron and published by THQ for the Game Boy Advance. Based on the animated television series The Simpsons, the game allows players to control several characters from the series, who must drive through the town of Springfield and transport passengers to their destinations within a time limit. The objective is to accumulate one million dollars in fares to repurchase the local transit system from Mr. Burns. The game received mixed reviews upon release, with critics drawing comparisons to Crazy Taxi and praising its amount of content and fast-paced action while criticizing its graphics, fidelity to the series, and password save feature.', 'https://en.wikipedia.org/wiki/The_Simpsons:_Road_Rage_(GBA_video_game)'),
  ('Q137689993', 'The Muppets: On With the Show! is a 2003 video game developed by Activision for Microsoft Windows and Vicarious Visions for the Game Boy Advance, and published by TDK Mediactive on both platforms. It is a collection of action-based minigames in which players help members of The Muppets complete various tasks within a time limit. Upon release, On With the Show! received mixed reviews, with critics faulting the game''s lack of minigame variety, complex goals, and a save system, although characterising it as a simple budget title.', 'https://en.wikipedia.org/wiki/The_Muppets:_On_With_the_Show!'),
  ('Q3282468', 'Pac-Man Collection is a 2001 video game compilation developed by Mass Media and published by Namco for the Game Boy Advance. It includes four titles in the Pac-Man series — the original Pac-Man (1980), Pac-Mania (1987), Pac-Attack (1993), and Pac-Man Arrangement (1996), the latter of which was originally exclusive to the arcade game Namco Classic Collection Vol. 2. Each game includes customizable features such as the ability to alter the number of starting lives or difficulty, with all being stripped of multiplayer features.

Development of the game was headed by California-based studio Mass Media, who previously worked on several Namco Museum collections for other platforms. It was first announced on April 24, 2001 under the name Pac-Man Fever, before being presented at the 2001 Electronic Entertainment Expo (E3) tradeshow. Pac-Man Collection was a commercial success — by 2007 it sold over 2.9 million copies worldwide, making it the ninth best-selling Game Boy Advance game of all time. Critics reacted positively to the title''s selection of games and customizable features, although some criticized the exclusion of games such as Ms. Pac-Man and inability to save high-scores. It was re-released as a budget title in Japan in 2006, and later digitally on the Wii U''s Virtual Console in 2014.', 'https://en.wikipedia.org/wiki/Pac-Man_Collection'),
  ('Q131413997', 'The Flintstones: Big Trouble in Bedrock is a 2001 platform video game for the Game Boy Advance developed by H2O Entertainment. As Fred Flintstone, players complete twelve platforming levels in search of Barney Rubble, who has been kidnapped by Dr. Sinister. Publisher Conspiracy Entertainment announced Big Trouble in Bedrock in 2000 ahead of the release of the Game Boy Advance, it is the first and only GBA game based on The Flintstones. Upon release, the game received negative reviews, with critics focusing on the game''s limited features and poor graphics.', 'https://en.wikipedia.org/wiki/The_Flintstones:_Big_Trouble_in_Bedrock'),
  ('Q2078759', 'Phantasy Star Collection is a compilation of Phantasy Star video games. When released for the Sega Saturn in Japan in 1998, it featured the first four games in the series, whereas the Game Boy Advance version, released in 2002 in North America and in 2003 in Europe, features the first three. The North American and European versions were produced by Digital Eclipse. The Saturn version was later ported to the PlayStation 2 (as Sega Ages 2500 Series Vol. 32: Phantasy Star Complete Collection) in Japan with more games added.

The compilation features ports of the original Phantasy Star games. They are virtually identical to their original versions, as opposed to enhanced remakes. Gameplay has not been altered in each of the collections, but additional options in the Saturn and PlayStation 2 versions can alter the pace and difficulty of the games significantly.', 'https://en.wikipedia.org/wiki/Phantasy_Star_Collection'),
  ('Q6200948', 'Jimmy Neutron vs. Jimmy Negatron is a video game for Microsoft Windows and Game Boy Advance. In the game, the player plays as Jimmy Neutron as he always tries to stop his evil doppelganger, Jimmy Negatron, from his evil deeds. It was published by THQ and Nick Games and developed by AWE Games (PC) and Human Soft (GBA). The PC version contains a demo for SpongeBob SquarePants: Employee of the Month which was released around the same time.', 'https://en.wikipedia.org/wiki/Jimmy_Neutron_vs._Jimmy_Negatron'),
  ('Q3020592', 'Airforce Delta Storm, known as Airforce Delta II in Japan and simply as Deadly Skies (same as the first game) in Europe, is a fighter jet video game developed by Konami Computer Entertainment Studios released in 2001 for the Xbox. It is the sequel to the Sega Dreamcast game Airforce Delta.

A game also named Airforce Delta Storm developed by Mobile 21 was released in 2002 for the Game Boy Advance. While having the same name, this game''s plot is based on the previous title in the series, Airforce Delta.', 'https://en.wikipedia.org/wiki/AirForce_Delta_Storm'),
  ('Q140354597', 'ATV: Thunder Ridge Riders is a racing video game developed for the Game Boy Advance in 2006 and for the Nintendo DS in 2007.', 'https://en.wikipedia.org/wiki/ATV:_Thunder_Ridge_Riders'),
  ('Q6056703', 'Digidrive, released in PAL territories as Intersect, is a 2006 puzzle video game developed by Q-Games and published by Nintendo for the Game Boy Advance. It is the only game in the bit Generations series to not be developed by Skip Ltd. It was later re-released for the Nintendo DSi''s DSiWare digital distribution service as part of the Art Style series, where it was released outside Japan for the first time.', 'https://en.wikipedia.org/wiki/Digidrive'),
  ('Q5096272', 'Chicken Shoot is a video game developed by Toontraxx. It first released online in 2000 for Microsoft Windows and has since been released for Nintendo DS, Wii, and Game Boy Advance.

The Windows version received positive reviews, while reviews for the Game Boy Advance version were mixed, and both the Wii and DS versions were panned by critics.

A sequel, "Chicken Shoot 2", was released in 2005.', 'https://en.wikipedia.org/wiki/Chicken_Shoot'),
  ('Q11751253', 'Chicken Shoot 2 is a 2003 video game developed by Toontraxx and published by Zuxxez Entertainment for Microsoft Windows. A version for the Game Boy Advance was developed by Frontline Studios and Vivid Design and published by DSI Games in 2005. Upon release, the game received negative reviews.', 'https://en.wikipedia.org/wiki/Chicken_Shoot_2'),
  ('Q3576876', 'Deal or No Deal is a video game based upon the American television show of the same name. It was released for Microsoft Windows, Game Boy Advance, Nintendo DS, Wii, iOS, Android and BlackBerry, and is available as a DVD TV game. A "special edition" of the game was later published by Zoo Games for the Nintendo Wii on September 13, 2010 and the Nintendo DS on October 26, 2010.', 'https://en.wikipedia.org/wiki/Deal_or_No_Deal_(video_game)'),
  ('Q5282472', 'Disney Sports Football is a pair of 2002 sports video games released by Konami for the GameCube and Game Boy Advance.', 'https://en.wikipedia.org/wiki/Disney_Sports_Football'),
  ('Q19866258', 'Peter Pan: Adventures in Never Land (also known as Peter Pan in Return to Never Land in North America) is a 2002 action game developed by Doki Denki and published by Sony Computer Entertainment for the PlayStation. Disney Interactive released the game on Windows. It was released as a tie-in to Return to Never Land. An abridged version for the Game Boy Advance developed by Crawfish Interactive was released the same year.', 'https://en.wikipedia.org/wiki/Peter_Pan:_Adventures_in_Never_Land'),
  ('Q85760176', 'F-14 Tomcat is a 2001 action video game released for the Game Boy Advance developed by Virtucraft and published by Majesco. It is an enhanced port of Turn and Burn: No-Fly Zone for the SNES. Two other games for the Game Boy Advance, Super Hornet F/A 18F and F24: Stealth Fighter were built on the same game engine.', 'https://en.wikipedia.org/wiki/F-14_Tomcat_(video_game)'),
  ('Q3110092', 'Golden Nugget Casino DS is a 2005 video game developed by American studio Skyworks Interactive and released by Majesco for the Nintendo DS. The game, named for the Las Vegas casino of the same name, is the first Golden Nugget themed game released for the DS. A prior game was released for the Game Boy Advance in 2004 (this Game Boy Advance game was later released again in 2005 as a 2 Games in 1 pack along with Texas Hold Em Poker), and another prior game was released for the Nintendo 64 (called Golden Nugget 64) back in 1998, preceded by a prior game for the PlayStation back in 1997 and the PC back in 1996.', 'https://en.wikipedia.org/wiki/Golden_Nugget_Casino_DS'),
  ('Q54952586', 'Harlem Globetrotters: World Tour is a basketball sports video game developed by Full Fat and published by Destination Software. It was released for the Game Boy Advance on October 2, 2006, and for the Nintendo DS on March 7, 2007.

World Tour features the Harlem Globetrotters playing against teams from around the world in games of 2-on-2 basketball in a style reminiscent of the NBA Jam series. World Tour garnered negative reviews from critics on release.

A version for the PlayStation Portable was also planned, but it was later cancelled.', 'https://en.wikipedia.org/wiki/Harlem_Globetrotters:_World_Tour'),
  ('Q4915189', 'Lego Bionicle: Quest for the Toa (also known as Lego Bionicle and originally titled Lego Bionicle: Tales of the Tohunga) is a 2001 action-adventure game developed by Saffire and published by Lego Software for the Game Boy Advance. Based on the Lego Group''s Bionicle line of constructible action figures, the game follows Takua, a villager on the island of Mata Nui, on a quest to rescue the island''s Turaga elders and summon the Toa, heroic elemental warriors destined to defeat the evil Makuta.

The game incorporates elements of platform games and takes an isometric perspective; the player traverses through 20 levels, divided among the six elementally-themed regions of the island of Mata Nui. After completing each world, a minigame is unlocked that can be played in single-player or multiplayer. Quest for the Toa was originally designed to be a prequel to Lego Bionicle: The Legend of Mata Nui, a planned PC title developed by Saffire that would ultimately be canceled shortly before release. During development, the game''s name was changed from Tales of the Tohunga to Quest for the Toa due to complaints from the Māori people of New Zealand. Upon its release, Quest for the Toa received mostly negative reviews from critics, with many criticizing its controls and gameplay. Conversely, praise was directed towards the minigames and graphics.', 'https://en.wikipedia.org/wiki/Lego_Bionicle:_Quest_for_the_Toa'),
  ('Q16910194', 'M&M''s Break'' Em is a 2007 puzzle video game developed by Frame Studios Interactive and published by Destination Software for the Game Boy Advance (GBA) and the Nintendo DS. The game is similar to Gem Smashers, a 2003 title by the same developer, featuring tile-breaking gameplay.

The game''s story mode revolves around controlling one of five M&M''s with constant vertical movement, completing various levels—by destroying crystals to free other M&M''s, avoiding hazards, and fighting bosses—in order to defeat Mr. Runch, a rotten and dangerous peanut determined to become an M&M. In addition to this single-player campaign, the game features a local multiplayer mode, wherein two players compete to break more crystals.', 'https://en.wikipedia.org/wiki/M%26M%27s_Break%27_Em'),
  ('Q760211', 'Manic Miner is a platform game written for the ZX Spectrum by Matthew Smith. It was published by Bug-Byte in 1983, then later the same year by Software Projects. The first game in the Miner Willy series, the design was inspired by Miner 2049er (1982) for the Atari 8-bit computers. Retro Gamer called Manic Miner one of the most influential platform games of all time, and it has been ported to numerous home computers, video game consoles, and mobile phones.', 'https://en.wikipedia.org/wiki/Manic_Miner'),
  ('Q28717682', 'Mary-Kate and Ashley: Sweet 16 – Licensed to Drive is a 2002 turn-based party video game published by Acclaim Entertainment under its Club Acclaim label. The game was released for the PlayStation 2, GameCube and Game Boy Advance. n-Space developed the game for the PS2 and GameCube whereas Powerhead Games developed the game for GBA.

It was the final installment to the Mary-Kate and Ashley video game franchise; although, another game, Mary-Kate and Ashley in ACTION!; based on the twins'' animated television series, was scheduled for release in 2003 but was ultimately canceled due to Acclaim''s poor financial status.', 'https://en.wikipedia.org/wiki/Mary-Kate_and_Ashley:_Sweet_16_%E2%80%93_Licensed_to_Drive'),
  ('Q4045148', 'Need for Speed: Carbon – Own the City is a 2006 racing video game and the third portable installment in the Need for Speed series. Developed by Team Fusion and published by Electronic Arts, it was released on October 31, 2006, for the PlayStation Portable, Game Boy Advance, Nintendo DS and on May 25, 2009 as a pack-in title for the Zeebo. The game, a companion title to Need for Speed: Carbon, includes new or modified gameplay elements, a different setting and storyline, and a different selection of teammates. It is the final installment in the series to be released for Game Boy Advance.', 'https://en.wikipedia.org/wiki/Need_for_Speed:_Carbon_%E2%80%93_Own_the_City'),
  ('Q56688283', 'NFL Blitz 20-03 is an American football video game published by Midway Sports for Game Boy Advance, GameCube, PlayStation 2 and Xbox in 2002.', 'https://en.wikipedia.org/wiki/NFL_Blitz_2003'),
  ('Q141777383', 'Operation Armored Liberty is a shooter video game for the Game Boy Advance.', 'https://en.wikipedia.org/wiki/Operation_Armored_Liberty'),
  ('Q1058928', 'Play Novel Silent Hill is a visual novel for the Game Boy Advance. It was released on March 21, 2001, only in Japan, as one of the GBA''s launch titles. The game serves as a novelized adaptation of Konami''s Silent Hill (1999), released for the PlayStation. The story centers on Harry Mason, who arrives in the cursed town of Silent Hill, and while seeking his missing daughter through the town, stumbles upon a cult conducting a rite to revive a deity it worships.

As a visual novel, Play Novel Silent Hill has the player reading the story through text presented over images. The player can then select options to control the narrative in the story, with some choices leading to changes that differ greatly from the original game. The story is interspersed with mini-games. On completion of a playthrough with Harry''s story, a new story option is opened. The player can then switch to the perspective of Cybil Bennett, who Harry encounters in the original game.', 'https://en.wikipedia.org/wiki/Play_Novel_Silent_Hill'),
  ('Q116455450', 'Premier Manager 2003–04 is a football management simulation video game, developed and published by Zoo Digital Publishing and released for the Game Boy Advance, PlayStation 2, and PC Windows in November 2003. It is the ninth game in the Premier Manager series.', 'https://en.wikipedia.org/wiki/Premier_Manager_2003%E2%80%9304'),
  ('Q20986873', 'Quad Desert Fury is a racing video game developed by Skyworks Technologies and published by Majesco Games for the Game Boy Advance in 2003.', 'https://en.wikipedia.org/wiki/Quad_Desert_Fury'),
  ('Q7353376', 'Robot Wars: Extreme Destruction is an action game developed by Climax Development and published by BBC Multimedia under their game development label Gamezlab in 2002 for the Game Boy Advance, Microsoft Windows and Xbox. It was given a release in the run-up to Christmas to build on the success of the three previous games, which had sold over 250,000 copies.

A separate version of the game was released for the Game Boy Advance which was developed by Warthog Games and was also published by BBC Multimedia under the Gamezlab label in 2002. Despite the same name, the gameplay, arenas and available robots differed greatly between the two versions.', 'https://en.wikipedia.org/wiki/Robot_Wars:_Extreme_Destruction'),
  ('Q650757', 'Scramble is a 1981 horizontally scrolling shooter video game developed and published by Konami for arcades. It was distributed by Leijac for manufacture in Japan and Stern in North America. It was the first side-scrolling shooter with forced scrolling and multiple distinct levels, and it established the foundation for a new genre.

It was Konami''s first major worldwide hit. In the United States, it sold 15,136 arcade cabinets within five months and became Stern''s second best-selling game. Scramble was not ported to any major contemporary consoles or computers, but there were releases for the Tomy Tutor and Vectrex as well as dedicated tabletop/handheld versions. Unauthorized clones for the VIC-20 and Commodore 64 use the same name as the original.', 'https://en.wikipedia.org/wiki/Scramble_(video_game)'),
  ('Q60747310', 'Secret Agent Barbie or Barbie: Secret Agent is a multi platform video game released in 2001 for Microsoft Windows and Game Boy Advance. It follows Barbie as a secret agent doing missions all over the world.', 'https://en.wikipedia.org/wiki/Secret_Agent_Barbie'),
  ('Q65174930', 'The Sims 2 is a 2005 life simulation video game developed by Amaze Entertainment and published by Electronic Arts for the Game Boy Advance (GBA). Development of the game began following the success of The Sims 2 for personal computers. The GBA version differs significantly from the original version, being a game with linear progression in the style of a reality show and 2D isometric graphics.

It is the third and final game in the Sims series to be developed by Amaze Entertainment following The Sims Bustin'' Out and The Urbz: Sims in the City. The game received mixed reviews from critics upon release.', 'https://en.wikipedia.org/wiki/The_Sims_2_(GBA_video_game)'),
  ('Q2743425', 'Slime Mori Mori Dragon Quest: Shōgeki no Shippo Dan is a 2003 action-adventure game developed by Tose and published by Square Enix for the Game Boy Advance. It is a spinoff video game to the Dragon Quest series, and the first entry in the Slime subseries.', 'https://en.wikipedia.org/wiki/Slime_Mori_Mori_Dragon_Quest'),
  ('Q2078911', 'Teenage Mutant Ninja Turtles is a 2003 beat ''em up game developed and published by Konami for the Game Boy Advance, and based on the 2003 TV series. In this game, each turtle has his own unique set of levels to complete. In addition to the traditional side-scrolling levels, there are third-person view races, a shell-glider level for Donatello and a bike race between Raphael and Casey Jones. The game was also issued in a double pack with its sequel Teenage Mutant Ninja Turtles 2: Battle Nexus.', 'https://en.wikipedia.org/wiki/Teenage_Mutant_Ninja_Turtles_(GBA_video_game)'),
  ('Q3283340', 'Tim Burton''s The Nightmare Before Christmas: The Pumpkin King is a 2005 platform game developed by Tose for the Game Boy Advance. The game was published by D3 Publisher in Japan, and by Buena Vista Games internationally. A prequel to the 1993 stop motion animated film The Nightmare Before Christmas, it tells the story of Jack Skellington''s first encounter with Oogie Boogie, and how he claimed the title of "The Pumpkin King".

The Pumpkin King was released at the same time in North America as The Nightmare Before Christmas: Oogie''s Revenge for PlayStation 2 and Xbox.', 'https://en.wikipedia.org/wiki/The_Nightmare_Before_Christmas:_The_Pumpkin_King'),
  ('Q3178198', 'Tony Hawk''s American Sk8land is a skateboarding video game in the Tony Hawk''s series. The game, a companion title to Tony Hawk''s American Wasteland, was published by Activision in 2005 as the first handheld release in the series for the Nintendo DS, and the fifth to appear on Game Boy Advance. It was the first third-party game released for the Nintendo DS supporting online play.', 'https://en.wikipedia.org/wiki/Tony_Hawk%27s_American_Sk8land'),
  ('Q2713382', 'Tron 2.0 is a 2003 first-person shooter video game developed by Monolith Productions and published by Buena Vista Interactive. Based on Disney''s science fiction franchise Tron, the game is a sequel to the original 1982 film of the same name. However, Tron 2.0 is set in an alternate continuity from later entries in the franchise; its events were retconned by the plot of Tron: Legacy, the canon sequel to the original film. The Microsoft Windows version of Tron 2.0 was released in August 2003. The Mac OS X version was released by MacPlay on April 21, 2004. Two unique ports for the Xbox and Game Boy Advance (GBA), both titled Tron 2.0: Killer App but containing many differences, were released later in 2004.', 'https://en.wikipedia.org/wiki/Tron_2.0');

update public.game g
set summary_en = i.summary, summary_en_source = i.source
from import_summary i
where g.wikidata_id = i.wikidata_id
  and g.summary_en is null;

drop table import_summary;
